window.kbParts["paper-8bf55e5c9f245124"] = {"qs":{"国考 2023 地市级 行测#1":{"stem":"党的二十大报告指出，全面建成社会主义现代化强国，总的战略安排是分两步走。关于到二〇三五年我国发展的\n总体目标，下列表述正确的有几项？\n①经济实力、科技实力、综合国力大幅跃升，人均国内生产总值迈上新的大台阶，达到中等发达国家水平\n②实现高水平科技自立自强，力争进入创新型国家行列\n③建成现代化经济体系，形成新发展格局，基本实现新型工业化、信息化、城镇化、农业现代化\n④广泛形成绿色生产生活方式，基本实现“碳中和”目标，生态环境根本好转，美丽中国目标全面实现\n⑤把我国建设成为综合国力和国际影响力领先的社会主义现代化强国","options":["2项","3项","4项","5项"],"answer":"A","analysis":"1. 正确答案：A\n解析：\n本题考查政治常识。\n①正确，二十大报告中“三、新时代新征程中国共产党的使命任务”部分指出：“到二〇三五年，我国发展的总体目标\n是：经济实力、科技实力、综合国力大幅跃升，人均国内生产总值迈上新的大台阶，达到中等发达国家水平······”\n②错误，二十大报告中“三、新时代新征程中国共产党的使命任务”部分指出：“到二〇三五年，我国发展的总体目标\n是：经济实力、科技实力、综合国力大幅跃升······实现高水平科技自立自强，进入创新型国家前列······”故应进入创\n新型国家“前列”。\n③正确，二十大报告中“三、新时代新征程中国共产党的使命任务”部分指出：“到二〇三五年，我国发展的总体目标\n是：经济实力、科技实力、综合国力大幅跃升······建成现代化经济体系，形成新发展格局，基本实现新型工业化、\n信息化、城镇化、农业现代化······”\n④错误，二十大报告中“三、新时代新征程中国共产党的使命任务”部分指出：“到二〇三五年，我国发展的总体目标\n是：经济实力、科技实力、综合国力大幅跃升······广泛形成绿色生产生活方式，碳排放达峰后稳中有降，生态环境\n根本好转，美丽中国目标基本实现······”其中“碳排放达峰后稳中有降”为“碳达峰”目标；“排出的二氧化碳或温室气体\n被植树造林、节能减排等形式抵消”为“碳中和”目标。\n⑤错误，二十大报告中“三、新时代新征程中国共产党的使命任务”部分指出：“在基本实现现代化的基础上，我们要\n继续奋斗，到本世纪中叶，把我国建设成为综合国力和国际影响力领先的社会主义现代化强国。”\n综上所述，正确的有①③，共2项。\n故正确答案为A。\n【考点】\n理论与政策-其他,重大会议及讲话","figs":[],"state":"待核","notes":["题目直接考查该报告部署，所给文字只标明目标年份，报告年份决定是否落入时政窗口。"],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-98bb2095a67b66dd","label":"到2035年人均国内生产总值达到中等发达国家水平","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"经济实力、科技实力、综合国力大幅跃升，人均国内生产总值迈上新的大台阶，达到中等发达国家水平","why":"报告同时明确了三项实力跃升和人均国内生产总值的目标水平。","origin":"逐题标记"},{"id":"k-06edceaa98ac52f6","label":"高水平科技自立自强","catalog_id":"08fbc6d8405a3842","type":"制度与规则","role":"直接考查","field":"answer","quote":"实现高水平科技自立自强，进入创新型国家前列","why":"科技目标同时要求实现高水平科技自立自强和进入创新型国家前列。","origin":"逐题标记"},{"id":"k-598e8dde0675f422","label":"到2035年建成现代化经济体系、形成新发展格局并基本实现新型工业化、信息化、城镇化、农业现代化","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"建成现代化经济体系，形成新发展格局，基本实现新型工业化、信息化、城镇化、农业现代化","why":"解析确认这三项要求同属二〇三五年总体目标。","origin":"逐题标记"},{"id":"k-86638e7ed22a64c3","label":"到2035年碳排放达峰后稳中有降、美丽中国目标基本实现","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"广泛形成绿色生产生活方式，碳排放达峰后稳中有降，生态环境\n根本好转，美丽中国目标基本实现","why":"绿色发展目标要求碳排放达峰后稳中有降，并明确美丽中国目标的实现程度为基本实现。","origin":"逐题标记"},{"id":"k-89eb4fb079f70fa6","label":"基本实现社会主义现代化","catalog_id":"053a24013e87f6af","type":"制度与规则","role":"直接考查","field":"answer","quote":"在基本实现现代化的基础上，我们要\n继续奋斗，到本世纪中叶，把我国建设成为综合国力和国际影响力领先的社会主义现代化强国。","why":"两步走战略以二〇三五年基本实现社会主义现代化为第一阶段，以本世纪中叶建成社会主义现代化强国为第二阶段。","origin":"逐题标记"}]},"国考 2023 地市级 行测#2":{"stem":"党的二十大报告指出，要发展全过程人民民主，保障人民当家作主。关于人民民主，下列表述正确的是：\n①人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义\n②全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主\n③协商民主是实践全过程人民民主的重要形式\n④党内民主是全过程人民民主的重要体现","options":["①③④","①②④","①②③","②③④"],"answer":"C","analysis":"2. 正确答案：C\n解析：\n本题考查政治常识。\n①②正确，二十大报告中“六、发展全过程人民民主，保障人民当家作主”部分指出：“我国是工人阶级领导的、以工\n农联盟为基础的人民民主专政的社会主义国家，国家一切权力属于人民。人民民主是社会主义的生命，是全面建设\n社会主义现代化国家的应有之义。全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的\n民主。”\n③正确，二十大报告中“六、发展全过程人民民主，保障人民当家作主”部分指出：“（二）全面发展协商民主。协商\n民主是实践全过程人民民主的重要形式。完善协商民主体系，统筹推进政党协商、人大协商、政府协商、政协协\n商、人民团体协商、基层协商以及社会组织协商，健全各种制度化协商平台，推进协商民主广泛多层制度化发展。”\n④错误，二十大报告中“六、发展全过程人民民主，保障人民当家作主”部分指出：“（三）积极发展基层民主。基层\n民主是全过程人民民主的重要体现。健全基层党组织领导的基层群众自治机制，加强基层组织建设，完善基层直接\n民主制度体系和工作体系，增强城乡社区群众自我管理、自我服务、自我教育、自我监督的实效。”\n综上所述，①②③正确。\n故正确答案为C。\n【考点】\n政治建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论"],"nature":"知识题","current":false,"links":[{"id":"k-c74a86ea848cf0a2","label":"人民民主是社会主义的生命和全面建设社会主义现代化国家的应有之义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"question","quote":"人民民主是社会主义的生命，是全面建设社会主义现代化国家的应有之义","why":"题目直接核对人民民主的政治地位和现代化建设意义。","origin":"逐题标记","originalId":"k-0511b46b2204cf5f"},{"id":"k-4f1da827daf01526","label":"全过程人民民主是社会主义民主政治的本质属性","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"question","quote":"全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主","why":"表述同时考查全过程人民民主的属性定位和三个特征。","origin":"逐题标记"},{"id":"k-53a4c7ef856b2d94","label":"协商民主是实践全过程人民民主的重要形式","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"question","quote":"协商民主是实践全过程人民民主的重要形式","why":"题目直接核对协商民主在全过程人民民主实践中的定位。","origin":"逐题标记"},{"id":"k-60f2a76759a4b86f","label":"基层民主是全过程人民民主的重要体现","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"基层\n民主是全过程人民民主的重要体现。","why":"解析明确把全过程人民民主重要体现的定位赋予基层民主。","origin":"逐题标记"}]},"国考 2023 地市级 行测#3":{"stem":"党的二十大报告指出，新时代十年来“党和国家事业取得历史性成就、发生历史性变革”。关于新时代十年来取得的\n历史性成就，下列表述错误的是：","options":["谷物总产量稳居世界首位","制造业规模、外汇储备稳居世界第一","全社会研发经费支出跃居世界第一","建成世界最大的高速铁路网"],"answer":"C","analysis":"3. 正确答案：C\n解析：\n本题考查政治常识。\n\nC项错误，A、B、D三项正确，二十大报告中“一、过去五年的工作和新时代十年的伟大变革”部分指出：“我们提出并\n贯彻新发展理念，着力推进高质量发展，推动构建新发展格局，实施供给侧结构性改革，制定一系列具有全局性意\n义的区域重大战略，我国经济实力实现历史性跃升······谷物总产量稳居世界首位，十四亿多人的粮食安全、能源安\n全得到有效保障。城镇化率提高十一点六个百分点，达到百分之六十四点七。制造业规模、外汇储备稳居世界第\n一。建成世界最大的高速铁路网、高速公路网，机场港口、水利、能源、信息等基础设施建设取得重大成就。我们\n加快推进科技自立自强，全社会研发经费支出从一万亿元增加到二万八千亿元，居世界第二位，研发人员总量居世\n界首位······”\n本题为选非题，故正确答案为C。\n【考点】\n理论与政策-其他,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["经济","科技"],"nature":"知识题","current":false,"links":[{"id":"k-420b06729d06d18b","label":"新时代十年我国谷物总产量稳居世界首位","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"谷物总产量稳居世界首位","why":"报告明确了这一时期我国谷物总产量的世界位次。","origin":"逐题标记"},{"id":"k-4dc56538d3a86707","label":"新时代十年我国制造业规模和外汇储备稳居世界第一","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"question","quote":"制造业规模、外汇储备稳居世界第一","why":"解析确认制造业规模和外汇储备均稳居世界第一。","origin":"逐题标记","originalId":"k-84cf989831ab111c"},{"id":"k-f278385ad21126e8","label":"全社会研发经费投入","catalog_id":"8df8d4353be4feb1","type":"事实与事件","role":"直接考查","field":"answer","quote":"全社会研发经费支出从一万亿元增加到二万八千亿元，居世界第二位","why":"判断研发经费表述须记住报告所列的世界第二位。","origin":"逐题标记"},{"id":"k-8999d73c34b13da9","label":"新时代十年我国建成世界最大的高速铁路网","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"建成世界最大的高速铁路网、高速公路网","why":"报告明确记载了高速铁路网的规模成就。","origin":"逐题标记"}]},"国考 2023 地市级 行测#4":{"stem":"习近平经济思想是习近平新时代中国特色社会主义思想的重要组成部分。关于习近平经济思想，下列表述正确的\n有几项？\n①进入新发展阶段是我国经济发展的历史方位\n②推动高质量发展是我国经济发展的鲜明主题\n③坚持新发展理念是我国经济发展的指导原则\n④坚持对外开放是我国经济发展的第一动力\n⑤大力发展制造业和实体经济是我国经济发展的主要着力点","options":["2项","3项","4项","5项"],"answer":"C","analysis":"4. 正确答案：C\n解析：\n本题考查政治常识。\n①②③⑤正确，④错误。由中共中央宣传部、国家发展和改革委员会组织编写的《习近平经济思想学习纲要》，将\n习近平经济思想基本内容梳理归纳为十三个方面：（1）加强党对经济工作的全面领导是我国经济发展的根本保证；\n（2）坚持以人民为中心的发展思想是我国经济发展的根本立场；（3）进入新发展阶段是我国经济发展的历史方\n位；（4）坚持新发展理念是我国经济发展的指导原则；（5）构建新发展格局是我国经济发展的路径选择；（6）推\n动高质量发展是我国经济发展的鲜明主题；（7）坚持和完善社会主义基本经济制度是我国经济发展的制度基础；\n（8）坚持问题导向部署实施国家重大发展战略是我国经济发展的战略举措；（9）坚持创新驱动发展是我国经济发\n展的第一动力；（10）大力发展制造业和实体经济是我国经济发展的主要着力点；（11）坚定不移全面扩大开放是\n我国经济发展的重要法宝；（12）统筹发展和安全是我国经济发展的重要保障；（13）坚持正确工作策略和方法是\n做好经济工作的方法论。\n综上所述，正确的有①②③⑤，共4项。\n故正确答案为C。\n【考点】\n经济建设,重要文件","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-35fe5b4ad45579e2","label":"进入新发展阶段是我国经济发展的历史方位","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"question","quote":"进入新发展阶段是我国经济发展的历史方位","why":"解析确认新发展阶段对应经济发展的历史方位。","origin":"逐题标记","originalId":"k-a3c331e495358f16"},{"id":"k-fdb33b9733777e9e","label":"高质量发展","catalog_id":"b1849da23e5bae07","type":"概念与词义","role":"直接考查","field":"question","quote":"推动高质量发展是我国经济发展的鲜明主题","why":"题目考查推动高质量发展在我国经济发展中的主题定位。","origin":"逐题标记"},{"id":"k-78d50a8035b03890","label":"新发展理念","catalog_id":"ffebdd7a058652ba","type":"概念与词义","role":"直接考查","field":"answer","quote":"坚持新发展理念是我国经济发展的指导原则","why":"题目考查坚持新发展理念在我国经济发展中的指导原则定位。","origin":"逐题标记"},{"id":"k-4e745fb604a3c668","label":"创新驱动发展是我国经济发展的第一动力","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"坚持创新驱动发展是我国经济发\n展的第一动力","why":"解析将第一动力明确对应创新驱动发展，并将全面扩大开放定位为重要法宝。","origin":"逐题标记"},{"id":"k-ba21811591ff4d33","label":"实体经济","catalog_id":"d28abd67bac9d0d3","type":"概念与词义","role":"直接考查","field":"answer","quote":"大力发展制造业和实体经济是我国经济发展的主要着力点","why":"题目要求识别制造业和实体经济在我国经济发展中的着力点定位。","origin":"逐题标记"}]},"国考 2023 地市级 行测#5":{"stem":"习近平总书记指出，共同富裕是社会主义的本质要求，是中国式现代化的重要特征。下列对共同富裕的理解，正\n确的有几项？\n①共同富裕是全体人民共同富裕，是人民群众物质生活和精神生活都富裕\n②鼓励各地因地制宜探索有效路径，按照城市、农村以及东部、中部、西部，确定各自指标，分阶段促进共同富裕\n③要处理好效率和公平的关系，构建初次分配、再分配、三次分配协调配套的基础性制度安排\n\n④实现共同富裕的目标，首先要通过全国人民共同奋斗把“蛋糕”做大做好，然后通过合理的制度安排正确处理增长和\n分配关系，把“蛋糕”切好分好","options":["1项","2项","3项","4项"],"answer":"C","analysis":"5. 正确答案：C\n解析：\n本题考查政治常识。\n①正确，在2021年第20期《求是》杂志刊发的《扎实推动共同富裕》一文中，习近平总书记强调，共同富裕是社会\n主义的本质要求，是中国式现代化的重要特征。我们说的共同富裕是全体人民共同富裕，是人民群众物质生活和精\n神生活都富裕，不是少数人的富裕，也不是整齐划一的平均主义。\n②错误，2021年8月17日，中央财经委第十次会议召开，议题之一是研究扎实促进共同富裕问题。会议强调，要坚持\n循序渐进，对共同富裕的长期性、艰巨性、复杂性有充分估计，鼓励各地因地制宜探索有效路径，总结经验，逐步\n推开。在2021年第20期《求是》杂志刊发的《扎实推动共同富裕》一文中，习近平总书记提出，我总的认为，像全\n面建成小康社会一样，全体人民共同富裕是一个总体概念，是对全社会而言的，不要分成城市一块、农村一块，或\n者东部、中部、西部地区各一块，各提各的指标，要从全局上来看。\n③正确，2021年8月17日，中央财经委员会召开第十次会议强调，要坚持以人民为中心的发展思想，在高质量发展中\n促进共同富裕，正确处理效率和公平的关系，构建初次分配、再分配、三次分配协调配套的基础性制度安排。\n④正确，2021年中央经济工作报告指出，实现共同富裕目标，首先要通过全国人民共同奋斗把“蛋糕”做大做好，然后\n通过合理的制度安排把“蛋糕”切好分好。这是一个长期的历史过程。\n故正确的有①③④，共3项。\n故正确答案为C。\n【考点】\n社会建设,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["政治理论","经济"],"nature":"知识题","current":false,"links":[{"id":"k-aa052a4589f73e60","label":"全体人民共同富裕","catalog_id":"c1c181c77df0cdd7","type":"概念与词义","role":"直接考查","field":"question","quote":"共同富裕是全体人民共同富裕，是人民群众物质生活和精神生活都富裕","why":"该表述明确了共同富裕的覆盖对象和物质、精神两个方面。","origin":"逐题标记"},{"id":"k-706c0629001c340d","label":"促进共同富裕应全局统筹并允许各地因地制宜探索路径","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"全体人民共同富裕是一个总体概念，是对全社会而言的，不要分成城市一块、农村一块，或\n者东部、中部、西部地区各一块，各提各的指标，要从全局上来看。","why":"地方可因地制宜探索实现路径，目标和指标须从全社会的整体出发。","origin":"逐题标记"},{"id":"k-1bb202a2f48a8ed3","label":"促进共同富裕要协调初次分配、再分配和三次分配","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"正确处理效率和公平的关系，构建初次分配、再分配、三次分配协调配套的基础性制度安排","why":"题目直接考查兼顾效率与公平的三层分配制度安排。","origin":"逐题标记"},{"id":"k-f2ca64cda9069956","label":"实现共同富裕须以共同奋斗扩大成果并以制度安排合理分配","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"通过全国人民共同奋斗把“蛋糕”做大做好，然后\n通过合理的制度安排把“蛋糕”切好分好","why":"该表述明确共同富裕的实现路径先做大发展成果，再通过制度安排合理分配。","origin":"逐题标记"}]},"国考 2023 地市级 行测#6":{"stem":"《“十四五”全国农业绿色发展规划》是我国首部农业绿色发展专项规划，对“十四五”农业绿色发展工作作出了系统\n部署和具体安排。下列与之相关的说法错误的是：","options":["到2035年，农村生态环境根本好转，绿色生产生活方式广泛形成","以果菜茶优势区为重点推动粪肥还田利用，减少化肥用量","在西北地区支持一批用膜大县整县推进农膜回收","在长江中下游、西南地区等南方粮食主产区集中示范耕作压盐技术模式"],"answer":"D","analysis":"6. 正确答案：D\n解析：\n本题考查政治常识。\n《“十四五”全国农业绿色发展规划》以下简称《规划》。\n\nA项正确，《规划》第二章第三节“发展目标”部分指出：“到2035年，农业绿色发展取得显著成效，农村生态环境根本\n好转，绿色生产生活方式广泛形成，农业生产与资源环境承载力基本匹配，生产生活生态相协调的农业发展格局基\n本建立，美丽宜人、业兴人和的社会主义新乡村基本建成。”\nB项正确，《规划》第四章第一节“推进化肥农药减量增效”部分指出：“推进化肥减量增效。技术集成驱动，以化肥减\n量增效为重点，集成推广科学施肥技术。在粮食主产区、园艺作物优势产区和设施蔬菜集中产区，推广机械施肥、\n种肥同播等措施，示范推广缓释肥、水溶肥等新型肥料，改进施肥方式。有机肥替代推动，以果菜茶优势区为重点\n推动粪肥还田利用，减少化肥用量，增加优质绿色产品供给。引导地方加大投入，在更大范围推进有机肥替代化\n肥。新型经营主体带动，培育扶持一批专业化服务组织，开展肥料统配统施社会化服务。鼓励农企合作推进测土配\n方施肥。”\nC项正确，《规划》第四章第三节“加强白色污染治理”部分指出：“推进农膜回收利用。落实严格的农膜管理制度，加\n强农膜生产、销售、使用、回收、再利用等环节管理。推广普及标准地膜，开展地膜覆盖技术适宜性评估，因地制\n宜调减作物覆膜面积。强化市场监管，禁止企业生产、采购、销售不符合国家强制性标准的地膜。积极探索推广环\n境友好生物可降解地膜。促进废旧地膜加工再利用，培育专业化农膜回收主体，发展废旧地膜机械化捡拾，建设农\n膜储存加工场点。建立健全农膜回收利用机制，在西北地区支持一批用膜大县整县推进农膜回收，加强长江经济带\n农膜回收利用，健全回收网络体系。开展区域农膜回收补贴制度试点，探索建立地膜生产者责任延伸制度。建立健\n全农田地膜残留监测点，开展常态化、制度化监测评估。”\nD项错误，《规划》第三章第一节“加强耕地保护与质量建设”部分指出：“加强退化耕地治理。坚持分类分区治理，集\n成推广土壤改良、地力培肥、治理修复等技术，有序推进退化耕地治理。在长江中下游、西南地区、华南地区等南\n方粮食主产区集成推广施用土壤调理剂、绿肥还田等技术模式，逐步实现酸化耕地降酸改良。在西北灌溉区、滨海\n灌溉区和松嫩平原西部等盐碱集中地区集成示范施用土壤调理剂、耕作压盐等技术模式，逐步实现盐碱耕地压盐改\n良。‘十四五’期间累计治理酸化、盐碱化耕地1400万亩。”\n本题为选非题，故正确答案为D。\n【考点】\n社会建设,重要文件","figs":[],"state":"待核","notes":["题目直接考查规划部署，所给数据只标明规划期和远景目标年份，发布日期年份决定是否落入时政窗口。"],"domains":["生态环境"],"nature":"知识题","current":false,"links":[{"id":"k-7081e04dab610420","label":"到2035年农村生态环境根本好转并广泛形成绿色生产生活方式","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"到2035年，农村生态环境根本好转，绿色生产生活方式广泛形成","why":"解析确认这两项要求均属于规划的远期目标。","origin":"逐题标记"},{"id":"k-11e85c28a9075b2c","label":"果菜茶优势区重点推广粪肥还田以减少化肥用量","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"question","quote":"以果菜茶优势区为重点推动粪肥还田利用，减少化肥用量","why":"规划明确以果菜茶优势区为重点，以粪肥替代部分化肥。","origin":"逐题标记"},{"id":"k-98f984f05f1aea9f","label":"西北地区支持用膜大县整县推进农膜回收","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"在西北地区支持一批用膜大县整县推进农膜回收","why":"规划同时规定了农膜回收支持的区域、县域对象和推进尺度。","origin":"逐题标记"},{"id":"k-036485e66ac9034c","label":"南方粮食主产区治理耕地酸化，盐碱集中地区示范耕作压盐","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"方粮食主产区集成推广施用土壤调理剂、绿肥还田等技术模式，逐步实现酸化耕地降酸改良。在西北灌溉区、滨海\n灌溉区和松嫩平原西部等盐碱集中地区集成示范施用土壤调理剂、耕作压盐等技术模式","why":"识别治理措施的适用地区，需要区分酸化耕地降酸与盐碱耕地压盐。","origin":"逐题标记"}]},"国考 2023 地市级 行测#7":{"stem":"下列与金融活动相关的说法错误的是：","options":["有价证券的债务人可以请求债权人支付相应对价","开展储蓄业务有助于实现货币购买力和商品供应量的平衡","分红型商业保险的收益与保险公司的经营状况有关","办理国家助学贷款的学生不需要办理贷款担保或抵押"],"answer":"A","analysis":"7. 正确答案：A\n解析：\n本题考查经济常识。\nA项错误，有价证券，是指标有票面金额，用于证明持有人或该证券指定的特定主体对特定财产拥有所有权或债权的\n凭证。有价证券的法律特征有：（一）有价证券与证券上所记载的财产权利不能分离。（二）有价证券的债务人是\n特定的，即证券的权利人只能向证券上记载的债务人请求实现债权。（三）有价证券的债务人的支付是单方义务，\n债务人不得请求权利人支付相应对价。\nB项正确，储蓄是指每个人或家庭，把节约的钱存到银行的经济活动。居民储蓄被银行积累起来，相应地增加社会可\n用的资金总量，支援社会生产发展，促进了社会积累的形成或增长。国家通过开展储蓄业务，可以有效地减少需求\n压力，实现货币购买力和商品供应量的平衡，调节货币流通。\nC项正确，分红型商业保险指保险公司将其实际经营成果优于定价假设的盈余，按一定比例向保单持有人进行分配的\n人寿保险产品。保单持有人可以分享保险公司经营成果的保险种类，保单持有人每年都有权获得建立在保险公司经\n营成果基础上的红利分配。\nD项正确，国家助学贷款是由政府主导，金融机构向高校家庭经济困难学生提供的信用助学贷款，帮助解决在校期间\n的学费和住宿费。国家助学贷款是信用贷款，学生不需要办理贷款担保或抵押，但需要承诺按期还款，并承担相关\n法律责任。\n本题为选非题，故正确答案为A。\n【考点】\n宏观经济与调控政策","figs":[],"state":"已标记","notes":[],"domains":["经济","法律"],"nature":"知识题","current":false,"links":[{"id":"k-4982f03b1299726b","label":"有价证券债务人的支付属于单方义务","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"有价证券的债务人的支付是单方义务，\n债务人不得请求权利人支付相应对价。","why":"债务人的单方支付义务决定其无权向证券权利人请求对应给付。","origin":"逐题标记"},{"id":"k-9e00b5c22927fe65","label":"居民储蓄有助于平衡货币购买力和商品供应量","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"实现货币购买力和商品供应量的平衡，调节货币流通","why":"吸收居民储蓄可以缓解即期商品需求压力并调节货币流通。","origin":"逐题标记"},{"id":"k-a976247acd3a4de2","label":"分红型商业保险红利取决于保险公司经营成果","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"建立在保险公司经\n营成果基础上的红利分配","why":"分红来源于保险公司实际经营成果优于定价假设所产生的盈余。","origin":"逐题标记","originalId":"k-e41680440b4a9182"},{"id":"k-5d9a97755247e962","label":"国家助学贷款属于无须担保或抵押的信用贷款","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"国家助学贷款是信用贷款，学生不需要办理贷款担保或抵押","why":"信用贷款的性质决定了该项助学贷款的担保要求。","origin":"逐题标记"}]},"国考 2023 地市级 行测#8":{"stem":"根据《中华人民共和国退役军人保障法》，下列说法正确的是：","options":["参战退役军人的随迁子女入学可以得到优先保障","退役的军士和义务兵可以逐月领取退役金","已被大学录取的现役军人可以在退伍后四年内入学","退役军人创办企业可以享受免税、贷款免息等优惠政策"],"answer":"A","analysis":"8. 正确答案：A\n解析：\n本题考查法律常识。\nA项正确，根据《中华人民共和国退役军人保障法》第二十九条第四款第一项规定：“随迁子女需要转学、入学的，\n安置地人民政府教育行政部门应当予以及时办理。对下列退役军人的随迁子女，优先保障：（一）参战退役军人。”\nB项错误，根据《中华人民共和国退役军人保障法》第二十一条第一款规定：“对退役的军官，国家采取退休、转\n业、逐月领取退役金、复员等方式妥善安置。”第二十二条第一款规定：“对退役的军士，国家采取逐月领取退役金、\n\n自主就业、安排工作、退休、供养等方式妥善安置。”第二十三条第一款规定：“对退役的义务兵，国家采取自主就\n业、安排工作、供养等方式妥善安置。”因此，退役的军官与军士可适用逐月领取退役金的安置方式，对于退役的义\n务兵并未规定可适用逐月领取退役金的安置方式。\nC项错误，根据《中华人民共和国退役军人保障法》第三十五条规定：“现役军人入伍前已被普通高等学校录取或者\n是正在普通高等学校就学的学生，服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学，可以按照\n国家有关规定转入本校其他专业学习。达到报考研究生条件的，按照国家有关规定享受优惠政策。”因此，已被大学\n录取的现役军人可以在退伍后两年内入学，而非四年。\nD项错误，根据《中华人民共和国退役军人保障法》第四十六条规定：“退役军人创办小微企业，可以按照国家有关\n规定申请创业担保贷款，并享受贷款贴息等融资优惠政策。退役军人从事个体经营，依法享受税收优惠政策。”因\n此，退役军人创办企业可以享受税收优惠、贷款贴息等优惠政策，而非享受免税、贷款免息等优惠政策。\n故正确答案为A。\n【考点】\n其他法律法规","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false,"links":[{"id":"k-a6e4dd95d97c36c8","label":"参战退役军人随迁子女入学转学享受优先保障","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"对下列退役军人的随迁子女，优先保障：（一）参战退役军人。","why":"条文明确把参战退役军人的随迁子女列为优先保障对象。","origin":"逐题标记"},{"id":"k-ef6576c99f720e30","label":"逐月领取退役金是退役军官和退役军士可适用的安置方式","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"退役的军官与军士可适用逐月领取退役金的安置方式，对于退役的义\n务兵并未规定可适用逐月领取退役金的安置方式。","why":"判断该项安置方式的适用对象须区分退役军官、军士和义务兵。","origin":"逐题标记"},{"id":"k-29ea1742bf587271","label":"入伍前已获普通高校录取或正在就学的军人可在退役后两年内入学或复学","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"服现役期间保留入学资格或者学籍，退役后两年内允许入学或者复学","why":"条文规定服役期间保留资格或学籍，并明确退役后入学或复学的两年期限。","origin":"逐题标记","originalId":"k-32156d1b910f06ee"},{"id":"k-5b7bf537c5ac2899","label":"退役军人创办小微企业可申请创业担保贷款和贴息，从事个体经营依法享受税收优惠","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"规定申请创业担保贷款，并享受贷款贴息等融资优惠政策。退役军人从事个体经营，依法享受税收优惠政策。","why":"条文按经营情形分别规定小微企业融资优惠和个体经营税收优惠。","origin":"逐题标记"}]},"国考 2023 地市级 行测#9":{"stem":"根据《中华人民共和国生物安全法》，下列说法错误的是：","options":["境外组织不得在我国从事中、高风险的生物技术研究、开发活动","任何单位和个人未经批准，不得擅自引进、释放或者丢弃外来物种","对高致病性的病原微生物，一律不得从事相关实验活动","国家对我国人类遗传资源和生物资源享有主权"],"answer":"C","analysis":"9. 正确答案：C\n解析：\n本题考查法律常识。\nA项正确，根据《中华人民共和国生物安全法》第三十八条第一款规定：“从事高风险、中风险生物技术研究、开发\n活动，应当由在我国境内依法成立的法人组织进行，并依法取得批准或者进行备案。”\nB项正确，根据《中华人民共和国生物安全法》第六十条第三款规定：“任何单位和个人未经批准，不得擅自引进、\n释放或者丢弃外来物种。”\nC项错误，根据《中华人民共和国生物安全法》第四十六条第一款规定：“高等级病原微生物实验室从事高致病性或\n者疑似高致病性病原微生物实验活动，应当经省级以上人民政府卫生健康或者农业农村主管部门批准，并将实验活\n动情况向批准部门报告。”\nD项正确，根据《中华人民共和国生物安全法》第五十三条第二款规定：“国家对我国人类遗传资源和生物资源享有\n主权。”\n本题为选非题，故正确答案为C。\n【考点】\n其他法律法规","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false,"links":[{"id":"k-154df3807c95078a","label":"《中华人民共和国生物安全法》对高致病性或疑似高致病性病原微生物实验活动实行审批管理","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"疑似高致病性病原微生物实验活动，应当经省级以上人民政府","why":"区分依法审批的实验活动与一律禁止的说法。","origin":"逐题标记"}]},"国考 2023 地市级 行测#10":{"stem":"下列与交通安全有关的说法错误的是：","options":["机动车载运放射性危险物品应当经公安机关批准后按指定的时间、路线、速度行驶","在允许拖拉机通行的道路上，拖拉机可以从事货运，但是不得用于载人","行人故意碰撞机动车造成交通事故的，机动车一方承担次要责任","前车为执行紧急任务的救护车、工程救险车的，后车不得超车"],"answer":"C","analysis":"10. 正确答案：C\n解析：\n本题考查法律常识。\nA项正确，根据《中华人民共和国道路交通安全法》第四十八条第三款规定：“机动车载运爆炸物品、易燃易爆化学\n物品以及剧毒、放射性等危险物品，应当经公安机关批准后，按指定的时间、路线、速度行驶，悬挂警示标志并采\n取必要的安全措施。”\nB项正确，根据《中华人民共和国道路交通安全法》第五十五条第二款规定：“在允许拖拉机通行的道路上，拖拉机\n可以从事货运，但是不得用于载人。”\nC项错误，根据《中华人民共和国道路交通安全法》第七十六条第二款规定：“交通事故的损失是由非机动车驾驶\n人、行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。”由此说明机动车一方无需承担次要责任。\nD项正确，根据《中华人民共和国道路交通安全法》第四十三条第三项规定：“同车道行驶的机动车，后车应当与前\n车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车：（三）前车为执行紧急任务的警车、消\n防车、救护车、工程救险车的。”\n本题为选非题，故正确答案为C。\n【考点】\n其他法律法规","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false,"links":[{"id":"k-a853499c2f59aca3","label":"非机动车驾驶人或行人故意碰撞机动车造成事故损失时，机动车一方不承担赔偿责任","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。","why":"故意碰撞是判断机动车一方赔偿责任的关键条件。","origin":"逐题标记"}]},"国考 2023 地市级 行测#11":{"stem":"关于电信诈骗，下列说法错误的是：","options":["非法使用“伪基站”实施电信诈骗的以非法侵入计算机信息系统罪追究刑事责任","实施电信诈骗最高可被判处无期徒刑","电信诈骗受害人可以通过诉讼程序要求服务存在缺陷的电信运营商承担相应责任","负责招募他人实施电信网络诈骗犯罪活动的，以共同犯罪论处"],"answer":"A","analysis":"11. 正确答案：A\n解析：\n本题考查法律常识。\nA项错误，根据《关于办理电信网络诈骗等刑事案件适用法律若干问题的意见》第三节第一点规定：“（一）在实施\n电信网络诈骗活动中，非法使用‘伪基站’‘黑广播’，干扰无线电通讯秩序，符合刑法第二百八十八条规定的，以扰乱无\n\n线电通讯管理秩序罪追究刑事责任。同时构成诈骗罪的，依照处罚较重的规定定罪处罚。”因此，非法使用“伪基\n站”实施电信网络诈骗活动，可能构成扰乱无线电通讯管理秩序罪或诈骗罪，不构成非法侵入计算机信息系统罪。\nB项正确，根据《中华人民共和国刑法》第二百六十六条规定：“诈骗公私财物，数额较大的，处三年以下有期徒\n刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚\n金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。本法\n另有规定的，依照规定。”若是诈骗数额特别巨大或者有其他特别严重情节的可被判处无期徒刑。\nC项正确，根据《中华人民共和国反电信网络诈骗法》第四十六条第二款规定：“电信业务经营者、银行业金融机\n构、非银行支付机构、互联网服务提供者等违反本法规定，造成他人损害的，依照《中华人民共和国民法典》等法\n律的规定承担民事责任。”第六条第五款规定：“电信业务经营者、银行业金融机构、非银行支付机构、互联网服务提\n供者承担风险防控责任，建立反电信网络诈骗内部控制机制和安全责任制度，加强新业务涉诈风险安全评估。”因\n此，电信运营商服务存在缺陷违反了《中华人民共和国反电信网络诈骗法》规定，受害人可以通过诉讼程序要求其\n承担相应责任。\nD项正确，根据《关于办理电信网络诈骗等刑事案件适用法律若干问题的意见》第四节第四点规定：“负责招募他人\n实施电信网络诈骗犯罪活动，或者制作、提供诈骗方案、术语清单、语音包、信息等的，以诈骗共同犯罪论处。”\n本题为选非题，故正确答案为A。\n【考点】\n其他法律法规","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false,"links":[{"id":"k-2cec074bf48cfbbc","label":"使用伪基站实施诈骗并扰乱无线电通讯秩序，符合刑法第二百八十八条的按扰乱无线电通讯管理秩序罪处理，同时构成诈骗罪的从一重处罚","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"同时构成诈骗罪的，依照处罚较重的规定定罪处罚。","why":"该规则用于判断相关行为的罪名及同时构成诈骗罪时的处理方式。","origin":"逐题标记"}]},"国考 2023 地市级 行测#12":{"stem":"根据《中华人民共和国职业教育法》，关于企业开展职业教育，下列说法错误的是：","options":["企业设立产教融合实训基地的，在公共事业费用上享受高于职业学校的优惠政策","企业应当按照职工工资总额一定比例提取使用职工教育经费","用于一线职工职业教育的经费应当达到国家规定的比例","企业安排职工到职业学校接受职业教育的，应支付职业教育期间工资"],"answer":"A","analysis":"12. 正确答案：A\n解析：\n本题考查法律常识。\nA项错误，根据《中华人民共和国职业教育法》第五十八条第二款规定：“企业设立具备生产与教学功能的产教融合\n实习实训基地所发生的费用，可以参照职业学校享受相应的用地、公用事业费等优惠。”题中，应是参照职业学校享\n受相应的公用事业费优惠，而非享受高于职业学校的优惠政策。\nB、C、D三项正确，根据《中华人民共和国职业教育法》第五十八条第一款规定：“企业应当根据国务院规定的标\n准，按照职工工资总额一定比例提取和使用职工教育经费。职工教育经费可以用于举办职业教育机构、对本单位的\n职工和准备招用人员进行职业教育等合理用途，其中用于企业一线职工职业教育的经费应当达到国家规定的比例。\n用人单位安排职工到职业学校或者职业培训机构接受职业教育的，应当在其接受职业教育期间依法支付工资，保障\n相关待遇。”\n本题为选非题，故正确答案为A。\n【考点】\n其他法律法规","figs":[],"state":"已标记","notes":[],"domains":["法律"],"nature":"知识题","current":false,"links":[{"id":"k-c1666a11d5805da7","label":"企业设立具备生产与教学功能的产教融合实习实训基地可参照职业学校享受用地、公用事业费等优惠","catalog_id":null,"type":"制度与规则","role":"直接考查","field":"answer","quote":"可以参照职业学校享受相应的用地、公用事业费等优惠","why":"职业学校是确定实训基地公用事业费优惠的参照标准。","origin":"逐题标记"}]},"国考 2023 地市级 行测#13":{"stem":"习近平主席在二〇二二年新年贺词中提到了“祝融”探火、“羲和”逐日、“天和”遨游星辰。下列与之相关的说法正确\n的是：","options":["“祝融号”火星车使用的是核动力电池","“羲和号”是我国首颗太阳探测科学技术试验卫星","“祝融”“羲和”“天和”都是古代神话中的人物","聂海胜等三名航天员搭乘神舟十四号前往天和核心舱"],"answer":"B","analysis":"13. 正确答案：B\n解析：\n本题考查政治常识。\nA项错误，中国的“祝融号”火星车并没有配备核电池，在火星上的一切行动依靠太阳能帆板来提供动力。“祝融号”火\n星车采用了4块超大型太阳能帆板，而且会随着太阳光的照射进行旋转，确保能吸收充足的太阳能。\nB项正确，2021年10月14日18时51分，我国在太原卫星发射中心采用长征二号丁运载火箭，成功发射首颗太阳探测\n科学技术试验卫星“羲和号”，实现我国太阳探测零的突破，这标志着我国正式步入“探日”时代。\nC项错误，祝融，号赤帝，中国古代神话中的火神、南方神、南岳神、南海神、夏神、灶神，五行神之一。羲和，中\n国上古神话中的太阳女神与制定时历的女神。羲和的原始形态来源于远古神话，在时代的更迭中她由最初的“日母”演\n变成“日御”，在后来的不断演化发展中，羲和又作为太阳神话、天文史官的代表人物。“天和”一词，最早出自《庄子·\n知北游》：若正汝形，一汝视，天和将至。天和指人的元气，也指天地祥和之气，自然和顺之理，天地之和气，并\n非古代神话中的人物。\nD项错误，2022年6月5日，搭载神舟十四号载人飞船的长征二号F遥十四运载火箭点火发射并取得圆满成功。当天，\n在神舟十四号载人飞船与空间站组合体成功实现自主快速交会对接后，航天员陈冬、刘洋、蔡旭哲依次进入中国空\n间站天和核心舱，正式开启为期6个月的在轨驻留。\n故正确答案为B。\n【考点】\n理论与政策-其他,重大会议及讲话","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"知识题","current":false,"links":[{"id":"k-cb2ec5d5c7ad611d","label":"“羲和号”是我国首颗太阳探测科学技术试验卫星","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"question","quote":"“羲和号”是我国首颗太阳探测科学技术试验卫星","why":"卫星的探测对象和在我国航天史上的首创地位共同确定其身份。","origin":"逐题标记"}]},"国考 2023 地市级 行测#14":{"stem":"“亲人送水来解渴，军民鱼水一家人。横断山，路难行。······乌江天险重飞渡，兵临贵阳逼昆明。敌人弃甲丢烟\n枪，我军乘胜赶路程。调虎离山袭金沙······”这是歌曲《四渡赤水出奇兵》中的一段歌词，下列与之相关的说法正确\n\n的是：","options":["“调虎离山袭金沙”是由毛泽东指挥的","李白《蜀道难》描写的正是此地“路难行”的状况","“军民鱼水”之情表现了沿途人民群众对新四军的支持","“乌江天险”正是楚汉战争时项羽兵败自刎的地方"],"answer":"A","analysis":"14. 正确答案：A\n\n解析：\n本题考查人文常识。\nA项正确，“调虎离山袭金沙”是指四渡赤水，南渡乌江后，中央红军就把敌人的追兵甩在了后面。此时，毛泽东指\n出：要实现从云南北渡金沙江入川的战略目标，就在于能否调出滇军，调出滇军就是胜利。毛泽东采取声东击西的\n战术，命一部分兵力向瓮安、黄平方向佯攻，做出东进湖南与二、六军团会合的姿态，主力则直逼贵阳。在贵阳督\n战的蒋介石，急调滇军三个旅驰援贵阳，中央红军突然调头西进云南，做出攻打昆明的态势。龙云惊恐万状，火速\n从金沙江边调回民团以解昆明之急，金沙江一线江防顿时空虚，红军主力则迅速兵分三路，从寻甸、嵩明之间穿\n过，以每日120里的急行军速度直插金沙江边的皎平、龙街和洪门渡口。\nB项错误，李白《蜀道难》描绘了秦蜀道路上奇丽惊险的山川，“蜀道”指的是今四川广元市境内剑门一带。而歌曲描\n述的四渡赤水的地点在贵州省、四川省、云南省交界地区，不是同一地方。\nC项错误，新四军即国民革命军陆军新编第四军，隶属于国民党军队战斗序列，是第二次国共合作期间由第五次反围\n剿失败后留在南方八省进行游击战争的中国工农红军和游击队改编的队伍。“军民鱼水”之情表现的是长征途中沿途人\n民群众对中央红军的支持。\nD项错误，“乌江天险”中的乌江，又名黔江，是贵州的第一道大江，自古有天险之称。而项羽的自刎之地是现在的安\n徽省和县乌江镇。\n故正确答案为A。\n【考点】\n中国历史","figs":[],"state":"已标记","notes":[],"domains":["历史"],"nature":"知识题","current":false,"links":[{"id":"k-5fd25b8cc8f0973b","label":"毛泽东指挥中央红军渡过金沙江","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"question","quote":"“调虎离山袭金沙”是由毛泽东指挥的","why":"歌词中的金沙江行动对应中央红军长征中的一次渡江，题目考查其指挥者。","origin":"逐题标记"}]},"国考 2023 地市级 行测#15":{"stem":"近年来，我国不断推进水生态修复保护工作。生态塘是包含水生动植物和微生物的一种水生态修复方式。下列与\n之相关的说法，错误的是：","options":["狐尾藻可用于富营养化水体的生态修复是因其可吸收氮磷","可以用生石灰对生态塘沿岸土壤进行消毒处理","池塘中的水体出现黑臭时可通过种植芦苇等植物进行改善","生态塘中的青鱼等肉食性鱼类主要在池塘上层水体活动"],"answer":"D","analysis":"15. 正确答案：D\n解析：\n本题考查科技常识。\nA项正确，狐尾藻是小二仙草科狐尾藻属植物，多年生粗壮沉水草本。根状茎发达，在水底泥中蔓延，节部生根，对\n富营养化水中的氮磷均有较好的净化作用。\nB项正确，蛋白质在遇到高温、强碱、强酸、重金属离子时会变性，蛋白质就失去了生物活性。生石灰遇水会发生反\n应放出大量的热，并且生成强碱，可以使细菌的蛋白质失去活性从而起到杀菌消毒的作用。\nC项正确，芦苇的根状茎十分发达，其叶、叶鞘、茎、根状茎和不定根都具有通气组织。当黑臭污水通过芦苇湿地系\n统时，芦苇能从污水中吸收营养物质加以利用，并能吸附和富集重金属及一些有毒有害物质，使水质得到净化。\nD项错误，青鱼是鲤科、青鱼属鱼类，体长可达145厘米，通常栖息在水的中下层，生性不活泼。其主要的食物来源\n为螺蛳、蚌、蚬、蛤等，偶尔也捕食虾和昆虫幼虫。\n本题为选非题，故正确答案为D。\n【考点】\n生物常识","figs":[],"state":"已标记","notes":[],"domains":["生态环境","科技"],"nature":"知识题","current":false,"links":[{"id":"k-a989fcfd3b8bd308","label":"青鱼通常栖息在水体中下层","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"通常栖息在水的中下层","why":"青鱼的典型栖息水层是判断其在生态塘中活动位置的依据。","origin":"逐题标记"}]},"国考 2023 地市级 行测#16":{"stem":"关于人体的生理现象，下列说法正确的是：","options":["人体在流汗时汗腺内的盐分浓度会降低","蚊虫叮咬造成的皮肤发痒属于过敏反应","打嗝声是由胃部痉挛和声带闭合造成的","皮肤受伤流血处的血管会先扩张后收缩"],"answer":"B","analysis":"16. 正确答案：B\n解析：\n本题考查科技常识。\nA项错误，汗液的形成一般是由于外界气温升高或者体内产热导致热刺激，激活汗腺功能，分泌大量液体，通过汗孔\n排到体表。由于汗腺还具备从产生出的汗液中再次将盐分吸收回体内的功能，所以通过再次吸收盐分，可以将盐分\n的流失抑制到最小程度。因此人体在流汗时汗腺内的盐分浓度会升高。\nB项正确，蚊虫叮咬引起的过敏症状有皮肤出现红肿、瘙痒，这是比较常见的过敏症状，也是比较轻微的过敏症状。\n出现这些症状是因为蚊虫叮咬所释放的唾液在皮肤组织产生刺激性的反应。\nC项错误，打嗝指气从胃中上逆，喉间频频作声，声音急而短促。这是一个生理上常见的现象，是由横膈膜痉挛收缩\n引起的。健康人打嗝多与饮食有关，特别是饮食过快、过饱，摄入很热或冷的食物饮料、饮酒等，外界温度变化和\n过度吸烟亦可引起。\nD项错误，当皮肤受伤流血后，血管会立即收缩，而不是先扩张后收缩。其收缩的目的是减少流向受伤部位的血液。\n过一段时间受伤部位的血液就会自动凝结变成血块，不让血液继续流出。\n故正确答案为B。\n【考点】\n生物常识","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"知识题","current":false,"links":[{"id":"k-1e6fe4c72f2fb9a5","label":"蚊虫叮咬后，唾液可引起局部红肿和瘙痒等过敏反应","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"蚊虫叮咬引起的过敏症状有皮肤出现红肿、瘙痒","why":"该反应说明蚊虫叮咬后的局部瘙痒可归为过敏表现。","origin":"逐题标记"}]},"国考 2023 地市级 行测#17":{"stem":"关于自然节律变化，下列说法错误的是：","options":["惊蛰后华北地区可能会出现“万里雪飘”的现象","2月北回归线附近会出现“儿童急走追黄蝶，飞入菜花无处寻”的现象","冬至时，在广东汕头竖直立杆会出现“立竿无影”的现象","谷雨前后江浙地区可能会出现“一把青秧趁手青，轻烟漠漠雨冥冥”的现象"],"answer":"C","analysis":"17. 正确答案：C\n解析：\n\n本题考查地理国情。\nA项正确，惊蛰，又名“启蛰”，是二十四节气中的第三个节气，于每年公历3月5-6日交节。有谚语“雪打惊蛰节，四十\n五天阴”，意思是惊蛰节气出现下雪天气，后期天气持续阴冷。即惊蛰后华北地区可能出现“万里雪飘”的景象。\nB项正确，选项中诗句出自宋代杨万里的《宿新市徐公店》，意思是小孩子奔跑着追赶黄蝴蝶，可是蝴蝶飞入菜花丛\n中就再也找不到了。北回归线自西向东穿过中国云南、广西、广东、福建（海域）、台湾五省区。2月我国北回归线\n附近的地区平均气温在      ，金黄色的油菜花会开放，所以可以出现诗句中的景象。\nC项错误，立竿无影是一种自然景象，即直立在地上的物体没有阴影显现。在夏至正午时分，太阳直射北回归线呈绝\n对（接近）直射状，北回归线地区就会出现短暂的“立竿无影”现象。冬至时，太阳直射南回归线，在广东汕头竖直立\n杆，日影应朝北而不是无影。\nD项正确，选项中诗句出自宋代虞似良的《横溪堂春晓》，意思是将一把青色的秧苗，插入水中，那秧苗瞬间变得青\n葱，就好似农夫的手，将它染绿，天空中，飘洒着朦胧如烟的细雨。谷雨，是二十四节气中的第六个节气，春季的\n最后一个节气，于每年公历4月19日-21日交节。谷雨取自“雨生百谷”之意，此时降水明显增加，田中的秧苗初插、作\n物新种，最需要雨水的滋润。故谷雨前后江浙地区可能会出现诗句中的景象。\n本题为选非题，故正确答案为C。\n【考点】\n自然常识","figs":[],"state":"已标记","notes":[],"domains":["地理"],"nature":"知识题","current":false,"links":[{"id":"k-abfdb2511698cad1","label":"冬至太阳直射南回归线，汕头正午竖杆的影子朝北","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"冬至时，太阳直射南回归线","why":"汕头位于冬至直射点以北，正午太阳在南侧，竖杆因此向北投影。","origin":"逐题标记"}]},"国考 2023 地市级 行测#18":{"stem":"下列关于化石的说法正确的是：","options":["三叶虫化石是侏罗纪地层中的典型化石","硅化木是树木埋入地下后形成的化石","琥珀的硬度比和田玉大","大多数化石是在侵入岩中被发现的"],"answer":"B","analysis":"18. 正确答案：B\n解析：\n本题考查科技常识。\nA项错误，三叶虫化石，古时称作燕子石，也叫蝙蝠石。三叶虫属古生节肢动物，属三叶虫纲，生于海底，其种类繁\n多，生于古生代的寒武纪，至奥陶纪最盛，消亡于二叠纪末期的二叠纪大灭绝事件。侏罗纪界于三叠纪和白垩纪之\n间，是恐龙的鼎盛时期。\nB项正确，硅化木是真正的木化石，是几百万年或更早以前的树木被迅速埋入地下后，被地下水中的二氧化硅替换而\n成的树木化石，它保留了树木的木质结构和纹理。\nC项错误，琥珀，一种透明的生物化石，是松柏科、云实科、南洋杉科等植物的树脂化石。树脂滴落，掩埋在地下千\n万年，在压力和热力的作用下石化形成琥珀。其硬度比较低，一般莫氏硬度为2-3。和田玉属镁质大理岩与中酸性岩\n浆岩接触交代而形成的变质岩，内含透闪石、角闪石、阳起石等多矿物集合体，化学成分是含水的钙镁硅酸盐，莫\n氏硬度在6-6.5之间。\nD项错误，沉积岩，又称为水成岩，是三种组成地球岩石圈的主要岩石之一（另外两种是岩浆岩和变质岩）。沉积岩\n保留了许多地球的历史信息，包括大多数古代动植物化石，沉积岩的层理也有地球气候环境变化的信息。侵入岩是\n指当上覆岩层压力减轻时，软流层中的岩浆就钻出，在地壳深处冷凝而形成的岩石。\n故正确答案为B。\n【考点】\n生物常识","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"知识题","current":false,"links":[{"id":"k-232eaaa60c5f1a41","label":"硅化木由埋藏木材被二氧化硅置换形成，并保留原有的木质结构和纹理","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"answer","quote":"树木被迅速埋入地下后，被地下水中的二氧化硅替换而\n成的树木化石","why":"木材埋藏后的二氧化硅置换解释了硅化木的来源。","origin":"逐题标记"}]},"国考 2023 地市级 行测#19":{"stem":"关于我国著名的资源调配工程，下列说法正确的是：","options":["南水北调中线工程的起点是小浪底水库","西电东送中部通道的电力主要来源于火力发电","北煤南运的主要通道包括兰新线和陇海线","西气东输工程贯穿了新疆、甘肃、安徽等省区"],"answer":"D","analysis":"19. 正确答案：D\n解析：\n本题考查地理国情。\nA项错误，“南水北调工程”是中华人民共和国的战略性工程，分东、中、西三条线路，东线工程起点位于江苏扬州江\n都水利枢纽。中线工程起点位于汉江中上游丹江口水库，供水区域为河南、河北、北京和天津。\nB项错误，“西电东送”就是把煤炭、水能资源丰富的西部省区的能源转化成电力资源，输送到电力紧缺的东部沿海地\n区。西电东送主要形成了三大电力输送通道：北线由陕西、山西、内蒙古等省区向华北输送电力，以黄河中上游的\n水电和山西、内蒙古火电为主。中线主要有四川等省区向华东和华中输送电力，以三峡和金沙江的水电为主。南线\n主要是云南、贵州、广西等省区向华南输送电力，以水电为主。\nC项错误，北煤南运宏观上指中国北方地区煤炭向南方地区大量运输。北煤南运的主要通道是大同-秦皇岛，太原-青\n岛，侯马-石臼所，长治-连云港，长治-枝城，长治-武汉等铁路。陇海兰新线是贯穿我国东西的一条铁路大动脉，由\n陇海线与兰新线组成。\nD项正确，西气东输工程是我国距离最长、口径最大的输气管道，该工程贯穿了新疆、甘肃、安徽等省区，其路线有\n西气东输一线、西气东输二线、西气东输三线、西气东输四线。西气东输一线西起新疆塔里木盆地的轮南，东至上\n海；西气东输二线西起新疆霍尔果斯口岸，南至广州、香港；西气东输三线西起新疆霍尔果斯口岸，东至福建福\n州；西气东输四线西起新疆乌恰县，终点在宁夏中卫。\n\n故正确答案为D。\n【考点】\n国情社情","figs":[],"state":"已标记","notes":[],"domains":["地理"],"nature":"知识题","current":false,"links":[{"id":"k-d293d508f53d82b3","label":"西气东输工程途经新疆、甘肃和安徽","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"该工程贯穿了新疆、甘肃、安徽等省区","why":"途经省区是核对西气东输工程线路的依据。","origin":"逐题标记"}]},"国考 2023 地市级 行测#20":{"stem":"关于生活常识，下列说法错误的是：","options":["腹部核磁共振时憋气可让脏器显影更充分","食用蜡可以用于防止微生物对果实的侵害","马铃薯切开后浸泡于清水中可以防止氧化","可以通过虫子取食痕迹判断蘑菇是否有毒"],"answer":"D","analysis":"20. 正确答案：D\n解析：\n本题考查科技常识。\nA项正确，患者进行磁共振扫描检查需要憋气，是因为呼吸期间腹部可出现起伏运动，因为腹部脂肪、水分随着起伏\n运动出现伪影，影响检查的清晰度，甚至可出现异常的检查结果，导致疾病误诊、漏诊等。患者检查时憋气可让脏\n器显影更充分，得到较准确的检查结果。\nB项正确，在水果表皮打上食用蜡，不仅可以保鲜，还能防止微生物对果实进行侵害。食用蜡对健康无明显影响，但\n如果是工业蜡则对身体有害。\nC项正确，马铃薯切开之后浸泡到清水里能防止马铃薯氧化，避免马铃薯变黑，但是将马铃薯切好之后浸泡时间最好\n不要过长，因为虽然泡水可以去除马铃薯中过多的淀粉，但浸泡时间过长就会出现变质的情况，且也会造成营养流\n失，吃起来口感下降。\nD项错误，很多对人有毒的蘑菇是其他动物的美食，比如豹斑鹅膏经常被蛞蝓取食，白毒伞也有被虫啮食的记录。\n本题为选非题，故正确答案为D。\n【考点】\n生活常识","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"知识题","current":false,"links":[{"id":"k-3941eb78632b15f1","label":"虫子取食痕迹不足以判断蘑菇对人体的毒性","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"白毒伞也有被虫啮食的记录","why":"对人有毒的蘑菇也可能被虫取食，因此虫啮痕迹不足以判断人体食用安全性。","origin":"逐题标记"}]},"国考 2023 地市级 行测#21":{"stem":"构建新发展格局的关键在于经济循环的      ，就像人们讲的要调理好统摄全身阴阳气血的任督二脉。经济活\n动需要各种生产要素的组合在生产、分配、流通、消费各环节有机衔接，从而实现循环流转。\n填入画横线部分最恰当的一项是：","options":["行之有效","环环相扣","畅通无阻","井然有序"],"answer":"C","analysis":"21. 正确答案：C\n解析：\n根据“就像人们讲的要调理好统摄全身阴阳气血的任督二脉”“实现循环流转”可知，横线处应体现经济循环畅通之意。\nC项“畅通无阻”指毫无阻碍地通行或通过，符合文意，当选。A项“行之有效”指实行起来有成效，B项“环环相扣”指每\n一个相互关连的关键或事物紧密配合，D项“井然有序”指整整齐齐，次序分明，条理清楚，三者均无法体现“畅通”之\n意，排除。\n故正确答案为C。\n【文段出处】习近平：把握新发展阶段，贯彻新发展理念，构建新发展格局\n【考点】\n成语填空,形象表达","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-ba33b5486fe871ee","label":"“畅通无阻”指毫无阻碍地通行或通过","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“畅通无阻”指毫无阻碍地通行或通过","why":"成语强调通行顺畅，对应生产要素在各环节之间的流转。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"根据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"有机衔接，从而实现循环流转","why":"结合任督二脉的比喻和各环节衔接所要实现的结果，确定空格描述的状态。","origin":"逐题标记"}]},"国考 2023 地市级 行测#22":{"stem":"“报得准”是气象监测预报预警的生命力。天气预报准确率高，防灾减灾才能    ，为有关部门正确决策提供科\n学客观的支撑，应急处置才能有力有效。\n填入画横线部分最恰当的一项是：","options":["有条不紊","有的放矢","全力以赴","万无一失"],"answer":"B","analysis":"22. 正确答案：B\n解析：\n根据“‘报得准’是气象监测预报预警的生命力”可知，强调天气预报准确率高很重要，后文论证，天气预报的准确性\n高，让防灾减灾更精准，所以横线处需要体现精准、有针对性，B项“有的放矢”指对准靶子射箭，比喻言论、行动目\n标明确，符合文意，当选。A项“有条不紊”指有条理，有次序，一点儿不乱，文段并非强调防灾减灾的条理性，C\n项“全力以赴”指把全部力量投入进去，文段并非强调投入全部力量，均与文意不符，排除；D项“万无一失”形容有绝\n对把握，绝不会出差错，表述过于绝对，排除。\n故正确答案为B。\n【文段出处】人民日报《庄国泰：早预警早行动 筑牢气象防灾减灾第一道防线》\n【考点】\n成语填空,主题词","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-bc355a724e1a49bf","label":"“有的放矢”比喻言论或行动目标明确、有针对性","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“有的放矢”指对准靶子射箭","why":"成语的比喻义对应准确预报给防灾减灾行动带来的针对性。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"根据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"“报得准”是气象监测预报预警的生命力","why":"抓住预报准确这一条件，推断空格应体现防灾减灾行动因此获得的优势。","origin":"逐题标记"}]},"国考 2023 地市级 行测#23":{"stem":"红树林的地下部分长期处于厌氧环境，减缓了根系和凋落物的分解速率，加速了碳埋藏速率。此外，红树林大多\n分布于沉积型海岸河口，由上游河流和海洋潮汐共同作用带来的大量外源性碳，被它们固定并快速沉积下来。这“\n  ”的组合拳使得红树林成为海岸带蓝碳碳汇的主要贡献者。\n填入画横线部分最恰当的一项是：","options":["取长补短","标本兼治","开源节流","一举两得"],"answer":"C","analysis":"23. 正确答案：C\n解析：\n根据“减缓了根系和凋落物的分解速率，加速了碳埋藏速率”及“此外······由上游河流和海洋潮汐共同作用带来的大量\n外源性碳，被它们固定并快速沉积下来”可知，横线处体现红树林两方面的作用和好处，且双引号引导形象表达。C\n项“开源节流”比喻在财政经济上增加收入，节省开支，置于此处，“开源”可以对应红树林固定并沉积外源性碳，“节\n流”对应“减缓了根系和凋落物的分解速率”，符合文意，当选。\nA项“取长补短”表示在同类事物中吸取这个的长处来弥补那个的短处，文段并未涉及两者的“长处”与“短处”，与文意不\n符，排除；B项“标本兼治”指对事物的枝节和根本都加以治理，文段并未涉及“枝节”和“根本”，与文意不符，排除；D\n\n项“一举两得”意为做一件事得到两方面的好处，文段的结论仅提及“成为海岸带蓝碳碳汇的主要贡献者”这一个结果，\n并未体现出两方面的好处，与文意不符，排除。\n故正确答案为C。\n【文段出处】《会打“组合拳”的“武林高手”——红树林》\n【考点】\n成语填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-90785fda85f68e8b","label":"“开源节流”指增加收入、节省开支","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"比喻在财政经济上增加收入，节省开支","why":"成语的两个部分分别对应固定外源性碳和减缓有机物分解。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"根据语境辨析词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"减缓了根系和凋落物的分解速率，加速了碳埋藏速率","why":"结合这处描述和后文固定外源性碳的内容，逐一核对成语能否涵盖两项作用。","origin":"逐题标记"}]},"国考 2023 地市级 行测#24":{"stem":"我国十四亿多人口整体迈向现代化社会，规模超过现有发达国家人口的总和，艰巨性和复杂性    ，发展途\n径和推进方式也必然具有自己的特点。我们始终从国情出发想问题、作决策、办事情，既不好高骛远，也不因循守\n旧，保持历史      ，坚持稳中求进、循序渐进、持续推进。\n依次填入画横线部分最恰当的一项是：","options":["无与伦比 清醒","前所未有 耐心","无以复加 自信","异乎寻常 主动"],"answer":"B","analysis":"24. 正确答案：B\n解析：\n本题从第二空入手，根据横线后内容“坚持稳中求进、循序渐进、持续推进”可知，横线处表达不急于求成，B项“耐\n心”指不急躁，不厌烦，与文意相符，保留。A项“清醒”指清楚、明白，侧重不糊涂，C项“自信”指自己相信自己，侧\n重不自馁，D项“主动”指不待外力推动而行动，侧重不被动，三者均与文意不符，排除。\n第一空，代入验证，B项“前所未有”指以前从来没有过，可以体现“艰巨性和复杂性”在以往的历史上不曾出现，与前\n文“规模超过现有发达国家人口的总和”对应恰当，当选。\n故正确答案为B。\n【文段出处】瞭望《以中国式现代化全面推进中华民族伟大复兴》\n【考点】\n混搭填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-3afc67d7d76282fe","label":"“耐心”指不急躁、不厌烦","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"指不急躁，不厌烦","why":"词义对应循序渐进和持续推进所体现的心态。","origin":"逐题标记"},{"id":"k-e101eb3ad29ac9e5","label":"“前所未有”指以前从来没有过","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“前所未有”指以前从来没有过","why":"成语强调缺少先例，与前文给出的人口规模比较相呼应。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"根据语境逐空验证词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"坚持稳中求进、循序渐进、持续推进","why":"先用推进方式锁定第二空，再以人口规模的比较验证同组第一空。","origin":"逐题标记","originalId":"s-53e06077ddb3a29c"}]},"国考 2023 地市级 行测#25":{"stem":"相比于其他全球卫星导航系统采取单一轨道星座构型，北斗系统    ，坚定选择了混合星座的特色发展之\n路，并首创短文通报模式，开创了通信导航一体化的独特服务模式，信息发送能力从一次120个汉字提升到一次1200\n个汉字，遇到突发情况时无需       ，足以将情节一次性说清楚。\n依次填入画横线部分最恰当的一项是：","options":["与众不同 言简意赅","独树一帜 字斟句酌","遥遥领先 删繁就简","迎难而上 惜墨如金"],"answer":"B","analysis":"25. 正确答案：B\n解析：\n第一空，搭配“北斗系统”，且根据后文“特色发展之路”“首创短文通报模式，开创了······独特服务模式”可知，“北斗系\n统”与其他卫星导航系统不同，具有独特性。B项“独树一帜”指单独树立起一面旗帜，指自成一家，A项“与众不同”指\n与大家不一样，二者均能够体现出独特性，符合文意，保留；C项“遥遥领先”指远远地走在最前面，D项“迎难而上”形\n容不怕困难挫折，勇敢地挑战，二者均与文意无关，排除。\n第二空，对应前文“信息发送能力从一次120个汉字提升到一次1200个汉字”，后文“一次性说清楚”，可知，北斗系统\n信息发送能力得到提升，遇到突发情况不必过分推敲，删减字数。B项“字斟句酌”指写文章或说话慎重细致，一字一\n句地推敲琢磨，与文意相符，当选；A项“言简意赅”指语言简明而意思完备，“无需言简意赅”指的是表述啰嗦、繁复\n冗长，北斗系统的信息发送能力提升，并不意味着表述啰嗦、冗长，与文意不符，排除。\n故正确答案为B。\n【文段出处】光明网《圆梦！中国北斗正式登上世界舞台》；中国经济网《“北斗三号”收官，正式服务全球》\n【考点】\n成语填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-bd2e936b37cb058b","label":"“独树一帜”指自成一家","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“独树一帜”指单独树立起一面旗帜，指自成一家","why":"成语的比喻义对应北斗系统自行开创的特色路径和服务模式。","origin":"逐题标记"},{"id":"k-1093001e80c5db03","label":"“字斟句酌”指逐字逐句推敲","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“字斟句酌”指写文章或说话慎重细致","why":"成语指细致推敲措辞，放在“无需”之后能够体现容量提升后对字数限制的缓解。","origin":"逐题标记","originalId":"k-603eabbee2f76392"},{"id":"s-bc177199c1351631","label":"根据语境逐空验证词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"足以将情节一次性说清楚","why":"先用特色发展路径筛选第一空，再结合容量提升核对第二空在“无需”之后的含义。","origin":"逐题标记","originalId":"s-53e06077ddb3a29c"}]},"国考 2023 地市级 行测#26":{"stem":"地方政府要以民众利益、公共利益、国家利益为重，不能只追求短期利益，只追求政绩，而做出    的事情\n来。对官员的政绩考核、对政府的绩效评估，更要注重民生，注重社会的长远发展。这样才能从根本上避免破坏可\n持续发展大局、损害民众利益等“      ”现象的继续发生。\n依次填入画横线部分最恰当的一项是：","options":["本末倒置 抱薪救火","饮鸩止渴 掩耳盗铃","扬汤止沸 移花接木","竭泽而渔 杀鸡取卵"],"answer":"D","analysis":"26. 正确答案：D\n解析：\n第一空，根据横线前“不能只追求短期利益，只追求政绩”可知，横线处所填成语应表达只图眼前利益，不作长远打算\n之意。A项“本末倒置”比喻把主要事物和次要事物或事物的主要方面和次要方面弄颠倒了，置于此处可表达地方政府\n不以民众、公共、国家利益为重，而只追求政绩的短视行为，符合文意，保留；D项“竭泽而渔”比喻取之不留余地，\n只顾眼前利益，不作长远打算，符合文意，保留。B项“饮鸩止渴”比喻用错误的方法解决眼前的困难而不顾严重后\n果，文段并无“解决眼前的困难”之意，与文意不符，排除；C项“扬汤止沸”比喻办法不对头，不能从根本上解决问\n题，文段强调的是只图眼前利益，不作长远打算，与文意不符，排除。\n第二空，根据横线前“避免破坏可持续发展大局”及“损害民众利益”可知，横线处所填成语应表达不顾可持续发展大\n局，损害民众利益，只顾眼前利益之意。D项“杀鸡取卵”比喻只图眼前的好处而损害长远的利益，符合文意，当选。\nA项“抱薪救火”比喻因为方法不对，虽然有心消灭祸患，结果反而使祸患扩大，文段并无要“消灭祸患”之意，与文意\n不符，排除。\n故正确答案为D。\n【文段出处】《世界地质公园遭破坏 保护环境就要肃清错误政绩观》\n【考点】\n成语填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-1df63b2ff79f438c","label":"“竭泽而渔”比喻取之不留余地，只顾眼前利益","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“竭泽而渔”比喻取之不留余地","why":"成语的比喻义贴合只追求短期利益和政绩的行为。","origin":"逐题标记","originalId":"k-39d3c3bf33c8d457"},{"id":"k-2dd9e94ee7543266","label":"“杀鸡取卵”比喻只图眼前好处而损害长远利益","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“杀鸡取卵”比喻只图眼前的好处而损害长远的利益","why":"成语明确包含损害长远利益的后果，与第二空前描述的现象一致。","origin":"逐题标记","originalId":"k-a7c7a4581dae0412"},{"id":"s-bc177199c1351631","label":"根据语境逐空验证词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"不能只追求短期利益，只追求政绩","why":"用短期政绩动机筛选第一空，再根据危及持续发展和损害民众利益的后果核对第二空。","origin":"逐题标记","originalId":"s-53e06077ddb3a29c"}]},"国考 2023 地市级 行测#27":{"stem":"翻开古代农书，几千年间古人对于土地的保养，几乎与当代耕作学关注的措施    ，其中历代农书涉及最多\n的是施肥。在中国古人的摸索中，施肥成为一种讲究，何时、何地施肥，施何种肥，怎样施肥，形成了一个        的\n体系，在每个年度的农业生产进程中，精心安排在各个时节。\n依次填入画横线部分最恰当的一项是：","options":["一脉相承 科学","如出一辙 固定","别无二致 完整","不谋而合 复杂"],"answer":"C","analysis":"27. 正确答案：C\n解析：\n\n第一空，形容古人对土地的保养方法与当代耕作措施的关系。B项“如出一辙”比喻两件事情非常相似，C项“别无二\n致”指区分不出两者的差别，D项“不谋而合”指事先没有商量过，意见或行动却完全一致，均有相似之意，符合文段语\n境，保留。A项“一脉相承”比喻某种思想、行为或学说之间有继承关系，一般用法为“现在的情况”和“之前的情况”一脉\n相承，不能说“古人的做法”与“当代的措施”一脉相承，用法不当，排除。\n第二空，根据“何时、何地施肥，施何种肥”“精心安排在各个时节”可以看出，古人经过摸索，施肥的措施已经十分完\n善和周到。C项“完整”指具有或保持着应有的部分，没有损坏或残缺，符合文意，当选。B项“固定”指不变动或不移动\n的，文段并没有体现出“不变”，排除；D项“复杂”指（事物的种类、头绪等）多而杂，文段没有体现出“复杂”，且感情\n色彩较为消极，排除。\n故正确答案为C。\n【文段出处】《古代农业中的人地关系》\n【考点】\n混搭填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-7e0782d0d7deddc8","label":"“别无二致”指两者没有差别","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"指区分不出两者的差别","why":"成语与题干的“几乎”组合，表达古今两种做法高度相似。","origin":"逐题标记"},{"id":"k-069f3d23e20bf93d","label":"“完整”指具备应有的各个部分","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“完整”指具有或保持着应有的部分，没有损坏或残缺","why":"词义对应施肥时间、地点、种类和方法等方面均有安排。","origin":"逐题标记","originalId":"k-77833174dcd05b5d"},{"id":"s-bc177199c1351631","label":"根据语境逐空验证词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"何时、何地施肥，施何种肥，怎样施肥","why":"根据古今措施的比较筛选第一空，再用列举的施肥要素判断第二空所概括的体系特征。","origin":"逐题标记","originalId":"s-53e06077ddb3a29c"}]},"国考 2023 地市级 行测#28":{"stem":"要加强国际传播的理论研究，掌握国际传播的规律，构建对外话语体系，提高传播艺术。要采用   不同区域、\n不同国家、不同群体受众的精准传播方式，推进中国故事和中国声音的全球化表达、区域化表达、分众化表达，增\n强国际传播的      和实效性。\n依次填入画横线部分最恰当的一项是：","options":["满足 影响力","贴近 亲和力","融合 感染力","细分 说服力"],"answer":"B","analysis":"28. 正确答案：B\n解析：\n第一空，根据文意可知，要针对不同区域、不同国家、不同群体受众采用精准的传播方式。B项“贴近”指靠近，D\n项“细分”指详细区分，置于文段均符合文意，保留。A项“满足”指使满足，填入此处应为“满足不同区域、不同国家、\n不同群体需求的精准传播方式”，故用法错误，排除；C项“融合”指几种不同的事物合为一体，置于文段意为采用一种\n传播方式，与后文“精准传播方式”矛盾，与文意不符，排除。\n第二空，根据文意可知，横线处所填词语应体现出“精准传播方式”对“国际传播”的意义。B项“亲和力”比喻使人亲近、\n愿意接触的力量，D项“说服力”指说话者运用各种可能的技巧去说服受众的能力，采用精准的方式进行“国际传播”可\n使传播内容更易被接受，而非说服别人，且B项“亲和力”与“贴近”能形成前后呼应，故B项更契合文意，当选，排除D\n项。\n故正确答案为B。\n【文段出处】《习近平在中共中央政治局第三十次集体学习时强调 加强和改进国际传播工作 展示真实立体全面的中\n国》\n【考点】\n实词填空,词的辨析-程度轻重,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-3f87a082ec3083ea","label":"“贴近”指靠近，可用于表达与受众接近","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“贴近”指靠近","why":"词义和搭配能够体现传播方式主动接近不同受众。","origin":"逐题标记"},{"id":"k-221e4b4327bac07f","label":"“亲和力”指使人愿意亲近和接触的力量","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"愿意接触的力量","why":"词义体现受众更愿意接触传播内容的效果，与第一空呼应。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"根据语境逐空验证词语","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"不同群体受众的精准传播方式","why":"先核对第一空与受众的搭配，再检查第二空表达的效果能否由这种传播方式推出。","origin":"逐题标记","originalId":"s-53e06077ddb3a29c"}]},"国考 2023 地市级 行测#29":{"stem":"对于新业态新模式冲击本地的传统产业，是包容审慎，还是        ？对于非本地人才就业创业、非本地企业项\n目立项推广，能否        ，甚至千方百计降门槛、清路障以留人留项目？纵观先进制造业集群所在地，无一不是当\n地政府部门怀着“开放之心”，营造出良好的创新生态。\n依次填入画横线部分最恰当的一项是：","options":["如芒在背 一视同仁","退避三舍 不偏不倚","拒之门外 开诚布公","推三阻四 海纳百川"],"answer":"A","analysis":"29. 正确答案：A\n解析：\n第一空，根据“是······还是”可知，横线处与“包容审慎”构成反义并列，体现出与“包容”相对的态度，即不接受新业\n态、新模式。A项“如芒在背”意为像芒刺扎在背上一样，形容坐立不安，C项“拒之门外”意为把人挡在门外，形容拒绝\n协商或共事，D项“推三阻四”意为以各种借口推托，三者均符合文意，保留。B项“退避三舍”泛指对人让步，不与相\n争，与文意不符，排除。\n第二空，依据“甚至千方百计降门槛、清路障以留人留项目”可知，横线处所填内容与后文相似，但是程度比后文轻，\n且横线处修饰“当地部门”与“非本地人才、非本地企业项目”关系。A项“一视同仁”意为同样看待，不分亲疏厚薄，能够\n表达当地部门对待本地创业的人和项目与非本地创业的人和项目同等看待、公平公正的态度，“同等看待”到“对非本\n地人才、非本地企业项目有政策倾斜”，能够形成很好的语义加重，当选。C项“开诚布公”意为诚意待人，坦白无私，\n强调真诚、坦诚、坦白，和后文的“政策倾斜”无法构成递进关系，排除。D项“海纳百川”比喻接纳和包容的东西非常\n广泛，而且数量很大，用于此处程度过重，且与后文的递进关系不及A项准确，排除。\n故正确答案为A。\n【文段出处】《开放是创新的最佳滋养（观象台）》\n【考点】\n成语填空,词的辨析-程度轻重,关联关系-并列关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-042c8a1ee55bb9bf","label":"一视同仁指同等看待、不分亲疏厚薄","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“一视同仁”意为同样看待，不分亲疏厚薄","why":"同等看待本地与非本地人才和项目，可以与后文主动降门槛形成递进。","origin":"逐题标记","originalId":"k-dd2683236cc6d027"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"甚至千方百计降门槛、清路障以留人留项目？","why":"利用前一问的对照确定态度方向，再用“甚至”判断第二空所需的语义程度。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2023 地市级 行测#30":{"stem":"法律惩罚的正当性一定程度上源于公众朴素的道德期待。在具体执法时，不能仅仅       地依赖客观后果，进行简\n单归责和惩戒，而应全面考察当事人的主观认知、动机目的等情节，并综合         其社会危害性，由此来审慎决定是\n否启动惩罚机制。\n依次填入画横线部分最恰当的一项是：","options":["机械 评估","单纯 辨别","盲目 分析","草率 判断"],"answer":"A","analysis":"30. 正确答案：A\n解析：\n第一空，形容对客观后果的依赖，根据“不能······而应······”可知，横线处与“全面考察”语意相反，应体现出对客观后\n果的绝对依赖，而不考虑其他方面之意，A项“机械”意为方式拘泥死板，B项“单纯”意为简单、不复杂、单一，填入此\n处均能体现对客观后果的绝对依赖，保留。C项“盲目”意为认识不清，D项“草率”意为不认真、敷衍了事，均与文意不\n符，排除。\n\n第二空，搭配“社会危害性”，A项“评估”意为评价估量，填入此处，“评估社会危害性”为常见搭配，当选。B项“辨\n别”意为对不同的事物在认识上加以区别，通常搭配“真伪”“好坏”等，与“社会危害性”搭配不当，排除。\n故正确答案为A。\n【文段出处】《“以罚代征”案中的法律认识错误》\n【考点】\n实词填空,词的辨析-搭配对象,关联关系-并列关系【逻辑填空】","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-ee4ea8e8d0c29e89","label":"“评估”与“社会危害性”的搭配","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“评估社会危害性”为常见搭配","why":"第二空需要表示对危害程度作综合评价，动词与宾语的搭配可区分候选项。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"而应全面考察当事人的主观认知、动机目的等情节","why":"根据“而应全面考察”反推前空所描述的依赖方式，再核对后空的动宾搭配。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2023 地市级 行测#31":{"stem":"在过去百年中，地球升温约1摄氏度，考虑到人类在大气中排放的温室气体的积累，这种变暖实际上与基础物理\n学的预期是       的。那么，问题其实并不在于是否在变暖，而在于变暖速度有多快，但科学家在利用现有模型预测\n未来变暖时仍然存在       ，尤其是，类似极端降水这样的关键变量将如何变化，仍有很大的不确定性。\n依次填入画横线部分最恰当的一项是：","options":["一致 分歧","同步 短板","吻合 瑕疵","相符 漏洞"],"answer":"A","analysis":"31. 正确答案：A\n解析：\n本题可从第二空入手，根据“尤其是，类似极端降水这样的关键变量将如何变化，仍有很大的不确定性”可知，科学家\n在预测未来变暖时，对一些关键变量如何变化仍有不确定性，故横线处应体现科学家对于预测未来变暖的看法不一\n致，A项“分歧”指不一致、有差异，符合文意，保留。B项“短板”指人的短处、不擅长的地方，C项“瑕疵”指微小的缺\n点，D项“漏洞”指容易让东西透过或滴下的不该有的孔隙或裂缝，也指因说话、做事等不周密而留下的破绽，均体现\n不出不一致之意，与文意不符，排除。\n第一空，代入验证。A项“一致”意思是没有分歧，代入文段可体现出地球升温约1摄氏度与基础物理学的预期是一样\n的，符合文意，当选。\n故正确答案为A。\n【文段出处】原理公众号《10年、100年，甚至更久之后，地球会怎样？》\n【考点】\n实词填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-68cfff6392294960","label":"分歧指看法或判断不一致","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“分歧”指不一致、有差异","why":"第二空以预测判断之间是否存在差异为辨析重点。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"尤其是，类似极端降水这样的关键变量将如何变化，仍有很大的不确定性","why":"从“尤其是”引出的具体说明判断第二空的语义，再回填核对第一空。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2023 地市级 行测#32":{"stem":"长期以来，城管执法部门对职责内的执法事项通常是      “用力”，对所有的执法对象“一碗水端平”，以体现执法\n的公平性、公正性。但对于超大城市而言，由于城管执法事项繁多，涉及市场主体庞杂，而城管执法力量是有限\n的，实践中很难做到        ，进而可能会影响执法效果和执行力。\n依次填入画横线部分最恰当的一项是：","options":["精准 滴水不漏","均衡 百无一失","精确 精益求精","平均 面面俱全"],"answer":"D","analysis":"32. 正确答案：D\n解析：\n第一空，根据后文“对所有的执法对象‘一碗水端平’，以体现执法的公平性、公正性”可知，横线处要体现出城管执法\n部门对职责内的执法事项不偏不倚，B项“均衡”指平衡，D项“平均”指没有轻重或多少的分别，均符合文意，保留。A\n项“精准”指非常准确，精确，C项“精确”指非常准确，文段并非要表达执法的准确性，均与文意不符，排除。\n第二空，根据“由于城管执法事项繁多，涉及市场主体庞杂，而城管执法力量是有限的”，且横线前有“很难做到”的表\n述可知，横线处要体现执法全面没有遗漏之意，D项“面面俱全”指各方面都能照顾到，没有遗漏疏忽，符合文意，当\n选。B项“百无一失”形容极有把握，不会出差错，文段并未体现把握大，不出差错之意，与文意不符，排除。\n故正确答案为D。\n【文段出处】中工网-工人日报《期待分类分级执法推动城市治理效能提升》\n【考点】\n混搭填空,关联关系-因果关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-75c99e386a66aaa8","label":"面面俱全指各方面均得到照顾","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“面面俱全”指各方面都能照顾到，没有遗漏疏忽","why":"第二空考查各类执法事项能否得到全面覆盖。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"由于城管执法事项繁多，涉及市场主体庞杂，而城管执法力量是有限","why":"用“一碗水端平”判断第一空的用力方式，再从事项多、力量有限推断第二空所指的困难。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2023 地市级 行测#33":{"stem":"设立国家公园有助于权责统一，改变过去“九龙治水”的情况，大幅度     国土资源的管理效能。尤其是国家公园\n内有相当多的偏远、人居密度较低的区域，被划入国家公园后也可明确产权归属，将其机制化地管理起来，避免出\n现生态环境恶化却        的情况。\n依次填入画横线部分最恰当的一项是：","options":["增强 听之任之","发挥 鞭长莫及","改善 爱莫能助","提升 无人问津"],"answer":"D","analysis":"33. 正确答案：D\n解析：\n第一空，搭配“管理效能”，且根据“有助于权责统一，改变过去‘九龙治水’的情况”可知，横线处应体现出能够让国土资\n源的管理效能有所改变之意，A项“增强”指增进、加强，B项“发挥”指把内在的性质或能力表现出来，D项“提升”指提\n高，均与“管理效能”搭配恰当且符合文意，保留。C项“改善”指改变原有情况使好一些，常搭配“生活”“环境”等，与“管\n理效能”搭配不当，排除。\n第二空，“将其机制化地管理起来”中的“其”指代前文“偏远、人居密度较低的区域”，且横线前的“却”引导转折关系，根\n据前文“出现生态环境恶化”可知，当国家公园中偏远、人居密度较低的区域出现生态环境恶化的情况时，需要对这个\n情况进行管理，而不能出现没人管理的现象，故横线处搭配“区域”且应体现出没人管理之意，D项“无人问津”指没有\n人来探问、尝试或购买，与“区域”搭配恰当且符合文意，当选。A项“听之任之”指听任事情自然发展变化，不管不\n问，B项“鞭长莫及”指相隔太远，力量达不到，均与“区域”搭配不当，排除。\n故正确答案为D。\n【文段出处】光明网《第一批国家公园设立，意义重大》\n【考点】\n混搭填空,词的辨析-搭配对象,关联关系-转折关系【逻辑填空】","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-9b52ade8a4859e40","label":"无人问津可形容某处无人过问","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"与“区域”搭配恰当且符合文意","why":"第二空要求成语能够形容生态恶化的区域无人过问。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"现生态环境恶化却        的情况","why":"先核对动词与“管理效能”的搭配，再用“却”后的语义和所描述的对象筛选成语。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2023 地市级 行测#34":{"stem":"在普通人看来，法律都是        的，自己一辈子都不会和法律打交道。但在瞬息万变的社会里，人们随时可能\n触及法律的红线。很多人平时法律观念和意识不强，柔性执法不仅可以起到         作用，而且有利于提高群众的学法\n懂法意识。\n依次填入画横线部分最恰当的一项是：","options":["高高在上 教育","高深莫测 预防","遥不可及 警戒","事不关己 提醒"],"answer":"C","analysis":"34. 正确答案：C\n解析：\n第一空，横线后出现关联词“但”表示转折，前后语义相反。根据后文“自己一辈子都不会和法律打交道”、“人们随时可\n能触及法律的红线”可知，横线处所填成语应体现普通人认为与“法律”存在距离感，法律离生活很遥远。C项“遥不可\n\n及”指非常遥远而不可到达，D项“事不关己”指事情同自己没有关系，均符合文意，保留。A项“高高在上”形容领导者\n脱离群众，不深入实际，与“法律”搭配不当，排除；B项“高深莫测”指高深的程度无法揣测，形容使人难以理解，\n与“距离遥远”无关，与后文无法构成转折，排除。\n第二空，所填词语表示“柔性执法”的作用，C项“警戒”表示警示告诫，使人注意，D项“提醒”表示从旁指点，引起注\n意，“执法”对于可能触及法律红线的行为不是通过语言提醒，而是起到警示的作用，“警戒”填入文段更加恰当，排除\nD项。\n故正确答案为C。\n【文段出处】《柔性执法兼容法理与人情》\n【考点】\n混搭填空,词的辨析-搭配对象,关联关系-转折关系【逻辑填空】","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-a5e5218196226f6e","label":"“警戒”的警示告诫义与“提醒”的提示义","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“警戒”表示警示告诫，使人注意","why":"第二空需要辨明柔性执法对可能触及法律红线的行为所起的警示作用。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"但在瞬息万变的社会里，人们随时可能\n触及法律的红线。","why":"通过“但”前后的对照确定第一空所需的距离感，再根据执法情境比较第二空词义。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2023 地市级 行测#35":{"stem":"注册制改革越包容，市场主体越要       。随着注册制全面推进，新股上市数量势必增多，上市公司“    ”的时\n代一去不返。将自身相关信息说完整、说清楚，既是上市公司的法定责任，也是逐浪资本市场的立身之本。因此，\n企业应提升    和竞争意识，高度负责、抱诚守真地“自我介绍”。\n依次填入画横线部分最恰当的一项是：","options":["自律 待价而沽 紧迫感","自重 滥竽充数 使命感","自觉 奇货可居 危机感","自强 一枝独秀 责任感"],"answer":"C","analysis":"35. 正确答案：C\n解析：\n本题可从第二空入手。根据“新股上市数量势必增多”“······的时代一去不返”可知，横线处所填成语应与“数量势必增\n多”语义相反，体现随着新股上市数量不断增多，上市公司变得不再少有、稀缺，C项“奇货可居”指把少有的货物囤积\n起来，等待高价出售，也比喻拿某种专长或独占的东西作为资本，等待时机，以捞取名利地位，D项“一枝独秀”指其\n他花都没有开放，只有这一枝在开着，比喻技高一筹，优势明显，均符合文意，保留。A项“待价而沽”原比喻等待时\n机出来做官，后多比喻等待有好的待遇、条件才肯答应任职或做事，侧重强调等待，无法体现上市公司变得不再稀\n有之意，与文意不符，排除；B项“滥竽充数”比喻无本领的冒充有本领，次货冒充好货，与文意无关，排除。\n第一空，根据“将自身相关信息说完整、说清楚······也是逐浪资本市场的立身之本”“企业应······高度负责、抱诚守真\n地‘自我介绍’”可知，市场主体将相关信息说完整、说清楚是其能够安身立命的资本，横线处所填词语应体现注册制改\n革越包容，市场主体越要主动、负责、诚实地介绍相关信息，C项“自觉”指自己有所认识而主动去做，符合文意，保\n留。D项“自强”指自己努力图强，与文意无关，排除。\n第三空，代入验证。横线处所填词语与“竞争意识”构成并列关系，应体现企业要认识到竞争增加，保有忧患意识，C\n项“危机感”指认识到已经发生或者预见到将要发生的问题或困难，并感到紧迫担心的一种忧患意识，符合文意，当\n选。\n故正确答案为C。\n【文段出处】经济日报《金观平：给投资者一个真实的上市公司》\n【考点】\n混搭填空,关联关系-并列关系【逻辑填空】,关联关系-因果关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-8df34ad8e0ed37e9","label":"奇货可居比喻凭借稀缺事物谋取利益","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“奇货可居”指把少有的货物囤积\n起来，等待高价出售","why":"第二空需体现新股数量增多后逐渐消失的稀缺优势。","origin":"逐题标记","originalId":"k-d1e16f2fd6b24cc0"},{"id":"k-68485632d6f896b9","label":"自觉指自己有所认识并主动去做","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"“自觉”指自己有所认识而主动去做","why":"第一空凭主动履行信息披露责任的词义确定候选词。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"新股上市数量势必增多，上市公司“    ”的时\n代一去不返。","why":"从数量增加反推第二空对应的旧处境，再用信息披露和竞争意识两处线索检验组合。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2023 地市级 行测#36":{"stem":"随着技术发展，以数字手段为支撑的“沉浸式”“交互式”网上博物馆日益增多，提高了展览的     。但随着智能终\n端的普及，人们难免会对数字博物馆产生         。博物馆在利用数字技术的基础上，也不能忽视实物展览内涵的提\n升，使之兼备文化和教育功能，突出           的特点。\n依次填入画横线部分最恰当的一项是：","options":["科技性 排斥 润物无声","便捷性 厌倦 触手可及","趣味性 疲劳 寓教于乐","交融性 失望 与时俱进"],"answer":"C","analysis":"36. 正确答案：C\n解析：\n本题可从第三空入手，根据横线前“博物馆在利用数字技术的基础上······兼备文化和教育功能”可知，横线处应表达数\n字博物馆能够通过“沉浸式”“交互式”的方式使人们在娱乐中受到教育之意。C项“寓教于乐”指把教育跟娱乐融合为一\n体，使人在娱乐中受到教育，符合文意，保留。A项“润物无声””指有大胸怀者，做了贡献而不张扬，默默奉献，文段\n并未体现出“默默奉献”之意，与文意不符，排除；B项“触手可及”指一伸手便可接触到，形容距离很近，文段此处强\n调的是数字博物馆在“文化和教育”上的特点，并非强调“距离很近”，与文意不符，排除；D项“与时俱进”指随着时代的\n发展而不断发展、前进，与文意无关，排除。\n第一空，代入验证。C项“趣味性”强调能够使人感到愉快，引起兴趣的特性，与横线前“‘沉浸式’‘交互式’网上博物\n馆”对应恰当，符合文意，保留。\n第二空，代入验证。C项“疲劳”指因体力或脑力消耗过多而需要休息，置于此处强调智能终端普及之后，人们会对数\n字博物馆失去新鲜感之意，符合文意，当选。\n故正确答案为C。\n【文段出处】光明日报《发挥好博物馆的教育功能》\n【考点】\n混搭填空,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-88b6a24894fbb9ff","label":"寓教于乐指使人在娱乐中受到教育","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"使人在娱乐中受到教育","why":"第三空需要用成语表达有趣的展览体验与教育功能的结合。","origin":"逐题标记","originalId":"k-f25cf78b155daaa5"},{"id":"s-bc177199c1351631","label":"依据语境辨析选词","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"使之兼备文化和教育功能","why":"从末句的功能描述确定第三空，再用沉浸式体验和终端普及后的反应检验前两空。","origin":"逐题标记","originalId":"s-e32f9d0d9836336c"}]},"国考 2023 地市级 行测#37":{"stem":"环境整治关键要不留死角、不存盲点，光靠人为监管恐怕会        。目前，“互联网＋”数字技术已成为环境监测\n的利器，为生态环境监测布下“天罗地网”。这张网使任何“        ”，都能充分暴露在数据“阳光”之下，让环境监测和\n污染防治变得更加       、更加具象。\n依次填入画横线部分最恰当的一项是：","options":["捉襟见肘 一举一动 有效","力不从心 风吹草动 精细","顾此失彼 小打小闹 动态","收效甚微 蛛丝马迹 直观"],"answer":"B","analysis":"37. 正确答案：B\n解析：\n第一空，根据“环境整治关键要不留死角、不存盲点”可知，横线处应体现出光靠人为监管恐怕不够之意，A项“捉襟见\n肘”指顾此失彼，应付不过来，B项“力不从心”指心里想做，可是能力或力量够不上，C项“顾此失彼”指顾了这个，顾\n\n不了那个，均符合文意，保留。D项“收效甚微”指付出的努力基本没什么效果，文段强调的是只靠人为监管可能会不\n够，而不是人为的监管基本没有效果，置于此处程度过重，排除。\n第二空，横线处应体现出“为生态环境监测布下‘天罗地网’”的结果，即这张网能够让任何小的变动暴露在数据下之\n意，A项“一举一动”指人的每一个动作，B项“风吹草动”比喻轻微的动荡或变故，均符合文意，保留。C项“小打小\n闹”指小规模、零零碎碎地做事，文段并无做事规模大小之意，排除。\n第三空，横线处对应前文“充分暴露在数据‘阳光’之下”，且与“具象”构成并列关系，应体现出环境监测和污染防治能够\n更加具体之意，B项“精细”指精密细致，符合文意，当选。A项“有效”指能实现预期目的，有效果，无法与“具象”构成\n并列关系，排除。\n故正确答案为B。\n【文段出处】《用好环境监测的“智慧大脑”》\n【考点】\n混搭填空,词的辨析-程度轻重,关联关系-并列关系【逻辑填空】","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-260631b636304546","label":"“力不从心”表示有意愿但能力不足","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“力不从心”指心里想做，可是能力或力量够不上","why":"首空需要表达仅凭人工监管恐怕难以覆盖全部区域。","origin":"逐题标记"},{"id":"k-8a61abea221f8e4e","label":"“风吹草动”比喻轻微的动荡或变故","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“风吹草动”比喻轻微的动荡或变故","why":"第二空指数字监测能够察觉的微小变动。","origin":"逐题标记"},{"id":"k-f6b1953419789c80","label":"“精细”与“有效”的词义辨析","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“精细”指精密细致","why":"“精细”描写监测的细致程度，与“具象”并列。“有效”侧重能否达到预期目的。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"结合语境辨析填空词义","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"更加具象","why":"利用末空与“具象”的并列关系，判断填入词是否同样体现监测的细致和具体。","origin":"逐题标记","originalId":"s-c976e5508b449f79"}]},"国考 2023 地市级 行测#38":{"stem":"培育强大的创新实力，中小企业要有“十年磨一剑”的      和志气。要克服融资难、原料贵、订单少等重重困难，\n持续投入，迎难而上，才能在           中迈上发展新台阶。当前，一家家优质中小企业在自主创新的道路上     ，\n勇毅前行，成长为能打硬仗的科技尖兵、稳链强链的有生力量。\n依次填入画横线部分最恰当的一项是：","options":["定力 厚积薄发 自强不息","决心 卧薪尝胆 稳扎稳打","耐性 筚路蓝缕 兢兢业业","智慧 山重水复 步步为营"],"answer":"A","analysis":"38. 正确答案：A\n解析：\n第一空，通过“和”可知，横线处所填词语应与“志气”语义相近，又根据横线前“十年磨一剑”可知，横线处应体现出中\n小企业的坚定意志，A项“定力”借指处变和把握自己的意志力，B项“决心”指坚定不移的意志，C项“耐性”指能忍耐、\n不急躁的性格，均符合文意，保留。D项“智慧”指辨析判断、发明创造的能力，与文意不符，排除。\n第二空，根据横线前“要克服······重重困难，持续投入，迎难而上”可知，横线处所填成语应体现出中小企业只有持续\n克服困难才能成功迈上发展新台阶之意，A项“厚积薄发”形容积累丰富的学问而不轻易表现出来，也形容准备充分才\n能办好事情，B项“卧薪尝胆”比喻刻苦自励，发愤图强，均符合文意，保留。C项“筚路蓝缕”多形容创业的艰辛，文段\n与创业无关，与文意不符，排除。\n第三空，与“勇毅前行”语义相近，又根据前后文“持续投入，迎难而上”“成长为能打硬仗的科技尖兵”可知，横线处所\n填成语应体现出中小企业在自主创新的道路上不畏困难，积极拼搏之意，A项“自强不息”指努力上进，永不懈怠，符\n合文意，当选。B项“稳扎稳打”比喻有步骤、有把握地做事，无法体现不畏艰难困苦和积极拼搏之意，与文意不符，\n排除。\n故正确答案为A。\n【文段出处】人民网《让更多“小巨人”撑起“大创新”（人民时评）》\n【考点】\n混搭填空,关联关系-并列关系【逻辑填空】,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-ead9a7f74aca339f","label":"“厚积薄发”强调充分积累后再取得成果","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"持续投入，迎难而上，才能在           中迈上发展新台阶。","why":"第二空要体现长期积累与后续发展的关系。","origin":"逐题标记"},{"id":"k-196a76c16bd67925","label":"“自强不息”与“稳扎稳打”的词义辨析","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“自强不息”指努力上进，永不懈怠","why":"“自强不息”强调持续奋进，契合自主创新中迎难而上的语境。“稳扎稳打”强调做事有步骤、有把握。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"结合语境辨析填空词义","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"勇毅前行，成长为能打硬仗的科技尖兵","why":"利用第三空后的并列语句和前文迎难而上的描述，判断末空应体现持续奋进。","origin":"逐题标记","originalId":"s-c976e5508b449f79"}]},"国考 2023 地市级 行测#39":{"stem":"开展未成年人网络环境整治，势在必行且        。网络上可能存在的色情、暴力、过度娱乐等有害信息，会对\n普遍拥有智能设备、全面触网的未成年人产生潜移默化的不良影响。只有         清朗洁净的网络空间，才能让青少年\n健康成长。实现这一愿景，需要发挥多主体多领域联动优势，         合力，撑起清朗网络蓝天。\n依次填入画横线部分最恰当的一项是：","options":["蓄势待发 创设 形成","刻不容缓 营造 凝聚","迫在眉睫 构筑 集成","任重道远 共建 汇聚"],"answer":"B","analysis":"39. 正确答案：B\n解析：\n第一空，根据“势在必行”“网络上可能存在的色情······不良影响”可知，文段表达“开展未成年人网络环境整治”的必要\n性及紧迫性，故横线处应体现亟需采取行动之意，B项“刻不容缓”形容形势非常紧迫，片刻也不能拖延，C项“迫在眉\n睫”比喻事情已到眼前，急迫得就像逼近了眉毛和睫毛一样，二者均与文意相符，保留。A项“蓄势待发”指贮备随时可\n以展现的实力，待机而发，D项“任重道远”比喻肩负的责任重大，并需要长期的艰苦努力，二者均无法体现事情的紧\n迫性，排除。\n第二空，搭配“网络空间”，B项“营造”指有目的、有计划地造，C项“构筑”指构建，二者均搭配恰当，保留。\n第三空，搭配“合力”，根据前文“需要发挥多主体多领域联动优势”这一对策可知，横线处需体现将多方力量集中在一\n起共同发力的过程，B项“凝聚”指聚集，与文意相符且搭配恰当，当选。C项“集成”指总体，强调结果，与文意不符，\n排除。\n故正确答案为B。\n【文段出处】《多方发力，为未成年人撑起清朗网络蓝天》\n【考点】\n混搭填空,词的辨析-搭配对象,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-23b1fb81256b60f3","label":"“刻不容缓”表示形势紧迫、片刻不能拖延","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“刻不容缓”形容形势非常紧迫，片刻也不能拖延","why":"首空需要在说明整治有必要的基础上强调行动的紧迫性。","origin":"逐题标记","originalId":"k-e28ce530262b1181"},{"id":"k-992e344097c435a7","label":"“凝聚合力”的搭配及含义","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“凝聚”指聚集，与文意相符且搭配恰当","why":"末空强调把多主体、多领域的力量汇集起来共同发力。","origin":"逐题标记","originalId":"k-eab10fe5e1577fb8"},{"id":"s-c5eac332ba86912d","label":"依据搭配对象筛选填空词语","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"第三空，搭配“合力”","why":"以“合力”为搭配对象，结合多主体联动的语境检验动词能否表达汇集力量的过程。","origin":"逐题标记","originalId":"s-979820fe839cedac"}]},"国考 2023 地市级 行测#40":{"stem":"竞争与创新总是      。平台反垄断最终要在抑制垄断与鼓励创新之间达到平衡。一方面，要加快健全市场准\n入制度、公平竞争审查机制，预防和         滥用行政权力限制竞争，充分   市场竞争机制的强大动能；另一方面，\n要引导和激励平台企业把更多精力用在创新上。唯有如此，平台经济方能为全社会注入持久的创新活力。\n依次填入画横线部分最恰当的一项是：","options":["如影随形 约束 调控","互为表里 杜绝 挖掘","相辅相成 打击 激发","息息相关 制止 释放"],"answer":"D","analysis":"40. 正确答案：D\n解析：\n第一空，根据“平台反垄断最终要在抑制垄断与鼓励创新之间达到平衡”可知，竞争与创新二者关系是密切的，横线处\n所填成语应体现两者之间的关系非常密切，A项“如影随形”比喻两个事物关系密切或两个人关系密切不能分离，D\n项“息息相关”指彼此呼吸都相互关联，形容关系非常密切，均符合文意，保留。B项“互为表里”指甲为乙的外表，乙\n为甲的内里，比喻互相依存，互相接受，文段并非强调二者是互相依存的关系，与文意不符，排除；C项“相辅相\n\n成”指两件事物互相配合，互相补充，缺一不可，文段侧重强调的是竞争与创新之间有密切的关系，而非强调二者互\n相配合，互相补充，与文意不符，排除。\n第二空，根据“要加快健全市场准入制度、公平竞争审查机制”可知，横线处所填词语应体现要营造公平竞争的环境，\n使滥用行政权力限制竞争这类行为不再发生，D项“制止”指强迫使停止，不允许继续，符合文意，保留。A项“约束”指\n限制管束使不越出范围，置于此处程度过轻，文段强调的是“使之不再发生”，排除。\n第三空，代入验证，横线处所填词语搭配“动能”，根据文意可知，需体现发挥市场竞争机制的强大动能的含义，D\n项“释放”符合文意，且与“动能”为常见搭配，当选。\n故正确答案为D。\n【文段出处】广州日报《平台反垄断要用好“两手”》\n【考点】\n混搭填空,词的辨析-搭配对象,词的辨析-程度轻重,前后呼应","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-b66f5908fe5557d4","label":"“息息相关”与“相辅相成”的词义辨析","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"形容关系非常密切","why":"“息息相关”强调联系密切，“相辅相成”还要求双方相互配合和补充。","origin":"逐题标记"},{"id":"k-d1af7383f2618d43","label":"“制止”与“约束”的词义辨析","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“制止”指强迫使停止，不允许继续","why":"处置语境要求使限制竞争的行为停止，“约束”侧重限制行为的范围。","origin":"逐题标记"},{"id":"k-e7b0b7249dce7e00","label":"“释放动能”的动宾搭配","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“释放”符合文意，且与“动能”为常见搭配","why":"末空需要表达让市场竞争机制已有的动能发挥出来。","origin":"逐题标记"},{"id":"s-bc177199c1351631","label":"结合语境辨析填空词义","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"置于此处程度过轻","why":"根据公平竞争语境判断第二空所需的处置力度，并核对首空成语是否准确描述两者关系。","origin":"逐题标记","originalId":"s-c976e5508b449f79"},{"id":"s-c5eac332ba86912d","label":"依据搭配对象筛选填空词语","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"横线处所填词语搭配“动能”","why":"以“动能”为搭配对象，检验末空动词是否符合让市场竞争机制发挥作用的语境。","origin":"逐题标记","originalId":"s-979820fe839cedac"}]},"国考 2023 地市级 行测#41":{"stem":"构建人类命运共同体是世界各国人民前途所在。          。只有各国行天下之大道，和睦相处、合作共赢，\n繁荣才能持久，安全才有保障。中国提出了全球发展倡议、全球安全倡议，愿同国际社会一道努力落实。中国坚持\n\n对话协商，推动建设一个持久和平的世界；坚持共建共享，推动建设一个普遍安全的世界；坚持合作共赢，推动建\n设一个共同繁荣的世界；坚持交流互鉴，推动建设一个开放包容的世界；坚持绿色低碳，推动建设一个清洁美丽的\n世界。\n填入画横线部分最恰当的一项是：","options":["河海不择细流，故能就其深","大道之行也，天下为公","万物并育而不相害，道并行而不相悖","芳林新叶催陈叶，流水前波让后波"],"answer":"C","analysis":"41. 正确答案：C\n解析：\n本题为语句填空题，横线在中间，故需结合前后文进行分析。横线前强调构建人类命运共同体事关世界各国人民的\n前途，横线后先是通过“只有······才”强调各国应该团结合作，然后介绍了中国提出的全球发展和全球安全倡议，希望\n同国际社会一起落实，并在尾句通过五个分句具体介绍了中国提出的倡议，再次强调各国应通过开放包容、合作共\n享来落实倡议的观点。故横线处应表达世界各国团结合作，和平共处之意。C项“万物并育而不相害，道并行而不相\n悖”意思是万物一起生长而互不妨害，遵循各自的规律运行而互不冲突，常用来比喻要以开放包容的心态对待他人，\n和谐共处，符合文意，当选。\nA项，“河海不择细流，故能就其深”意思是江河湖海不拒绝细小溪流的汇入，所以能成就它的深广，意在表达只有不\n排斥、不拒绝细小的力量，才能够成就真正的伟大，与文意不符，排除；\nB项，“大道之行也，天下为公”意思是在大道施行的时候，天下是人们所共有的，与“团结合作，和平共处”之意不\n符，排除；\nD项，“芳林新叶催陈叶，流水前波让后波”比喻新事物代替旧事物，后人接替前人的自然规律，与文意无关，排除。\n故正确答案为C。\n【文段出处】《高举中国特色社会主义伟大旗帜 为全面建设社会主义现代化国家而团结奋斗》\n【考点】\n承上启下","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"综合题","current":false,"links":[{"id":"k-d7e6ccc2e416504e","label":"“万物并育而不相害，道并行而不相悖”的含义","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"万物并育而不相害，道并行而不相悖","why":"理解万物共同生长而互不妨害、各循其道而互不冲突，才能将古语与开放包容、和谐共处相联系。","origin":"逐题标记"},{"id":"s-4eebda7bdff18647","label":"补全语句衔接","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"和睦相处、合作共赢","why":"结合空前的人类命运共同体话题与空后的各国相处方式，确定承上启下的古语应表达的意思。","origin":"逐题标记"}]},"国考 2023 地市级 行测#42":{"stem":"当前，社会治理形势复杂，仅靠职能部门、专业力量远远不够，迫切需要人民群众和社会各界的积极支持与参\n与，共同创造公共价值。众包是公众和外包的组合词，意指发包方依托互联网或其衍生工具，在数字平台上设计规\n则与任务并向广泛、非确定的公众发包，公众根据自身能力自愿接包并完成特定事务。众包强调大众参与的开放式\n合作，促使组织边界向更广泛的大众群体开放，旨在挖掘隐藏在公众中的巨大潜力。因此，相较于政府购买等专业\n性较强的政府合同外包服务，政府众包展现出更开放的社会治理格局。\n最适合做这段文字标题的是：","options":["众包：共享经济下的新型用工模式","政府众包：公众参与社会治理新方式","公众参与：开放式合作的新形式","“互联网+”：公共管理新范式"],"answer":"B","analysis":"42. 正确答案：B\n解析：\n文段开篇交代背景，指出社会治理形势存在的问题，并论述其需要人民群众和社会各界共同创造公共价值。接着引\n出“众包”的话题并给出定义，即公众可根据自身能力自愿接包并完成特定事务。接下来指出众包强调大众参与，旨在\n挖掘公众潜力。最后尾句通过“因此”总结前文，得出结论，并通过程度词“更”强调政府众包可以让社会治理格局更加\n开放。故文段重点围绕“政府众包”进行论述，强调其可解决当下社会治理存在的问题，对应B项。\nA项，“共享经济”为文段未提及内容，无中生有，且“众包”将文段核心话题“政府众包”范围扩大，排除；\nC项，缺少文段核心话题“政府众包”，排除；\nD项，“互联网+”为文段未提及内容，无中生有，且缺少文段核心话题“政府众包”，排除。\n故正确答案为B。\n【文段出处】中国社会科学网《政府众包：公众参与社会治理的新趋势》\n【考点】\n契合文段中心","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"政府众包展现出更开放的社会治理格局。","why":"根据“因此”引出的结论确定标题的范围，并用前文关于大众参与的说明概括这一方式的特点。","origin":"逐题标记"}]},"国考 2023 地市级 行测#43":{"stem":"农业是个生态产业，农村是生态系统的重要一环。要健全草原森林河流湖泊休养生息制度，巩固退牧还草、退耕\n还林成果，开展大规模国土绿化行动，加强生物多样性保护。这方面要有个科学规划，荒山、沙漠、滩涂、森林、\n草原等治理要因地制宜、符合实际，不能都是一种套路。长江、黄河流域是生态文明建设的主战场，农业农村任务\n十分艰巨。长江流域要抓好十年禁渔，加强执法监督和市场监管，妥善解决好渔民转产转业和社会保障问题。黄河\n流域要抓好农业深度节水控水，因水施种，发展节水农业、旱作农业，把农业用水效率提上去、总量省出来。\n这段文字意在说明：","options":["农业与农村生态文明建设任重道远","农业发展与生态治理需做好统筹","农业生态建设要做好科学规划","生态文明建设要找准着力点"],"answer":"C","analysis":"43. 正确答案：C\n解析：\n文段开篇指出农村是生态系统的重要一环，随后指出应该从哪几个方面入手做好农村生态建设，紧接着通过“这方\n面”指代前文并通过“要”给出对策，强调做好农业生态文明建设要有科学规划，后文通过论述长江、黄河流域的具体\n做法进行解释说明。故文段强调做好农业生态文明建设要有科学规划，核心话题为“科学规划”，对应C项。\nA项，偏离文段核心话题“科学规划”，且“任重道远”为问题表述，非重点，排除；\nB项，对应文段解释说明部分，非重点，且偏离文段核心话题“科学规划”，排除；\nD项，“找准着力点”表述不明确，文段强调要进行“科学规划”，不如C项明确，排除。\n故正确答案为C。\n\n【文段出处】人民网《坚持把解决好“三农”问题作为全党工作重中之重 举全党全社会之力推动乡村振兴》\n【考点】\n中心理解题-关联词-对策,中心理解题-主题词,分述句特征-举例子,分述句特征-引入铺垫","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"这方面要有个科学规划","why":"抓住“这方面”承接前文引出的总体对策，并将长江、黄河流域的具体做法归入对策的例证。","origin":"逐题标记"}]},"国考 2023 地市级 行测#44":{"stem":"银河系是星系考古学研究的“重点实验室”，恒星则是银河系考古的天然“化石”：恒星表面的化学元素，完整记录\n着其诞生时银河系星际环境的化学组成；恒星运动的相似性，也为天文学家研究恒星起源问题提供了重要线索。因\n此，实现对银河系形成和演化全面认识的关键，在于获取银河系中数量足够多、分布足够广、足够有代表性的恒星\n的位置、运动、年龄及化学组成等信息。\n这段文字接下来最可能讨论的是：","options":["获取恒星信息的方法和途径","星系考古学的前沿研究领域","恒星对宇宙起源研究的意义","关于银河系诞生原因的假说"],"answer":"A","analysis":"44. 正确答案：A\n解析：\n根据提问方式可知，本题为接语选择题，应在通读全文的基础上，重点关注文段最后论述的核心话题。文段开篇指\n出恒星对于银河系考古具有重要价值并具体展开介绍，尾句通过结论词“因此”得出结论，强调实现对银河系全面认识\n的关键，在于获取银河系中恒星的相关信息。故文段最后论述的核心内容为“获取恒星信息”，下文应围绕这一话题展\n开具体论述，即如何获取恒星的相关信息，对应A项。\nB项“星系考古学的前沿研究领域”、D项“关于银河系诞生原因的假说”均与文段最后论述的核心话题“获取恒星信息”不\n一致，排除；\nC项，“恒星对宇宙起源研究的意义”前文已经论述过，后文不会再论述，排除。\n故正确答案为A。\n【文段出处】《银河系史册：揭开银河系早期形成之谜 | 赛先生天文》\n【考点】\n根据尾句确定答案","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-94e5b1e84b4945ab","label":"根据文段结尾推断下文","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"文段最后论述的核心内容为“获取恒星信息”","why":"从“因此”引出的尾句锁定待展开的话题，判断下文会接着说明如何获取这些信息。","origin":"逐题标记","originalId":"s-70d365695b24c8c7"}]},"国考 2023 地市级 行测#45":{"stem":"火山灰是指火山爆炸性喷发形成的，直径小于2毫米的喷发碎屑。在爆炸性火山活动中，围岩和岩浆被炸碎成细\n小的颗粒，形成火山灰。火山灰从火山口喷发到大气中，经过大气搬运再沉降到各类环境中，整个过程通常只有数\n年，从地质时间尺度来看，几乎只是瞬间。所以在各种地质记录中，火山灰是一种高精度的绝对时间标志层。火山\n灰年代学正是利用地质记录中的火山灰层来确定地质年代的科学，该学科可以解决一些重要的科学问题，比如大型\n火山喷发事件与气候变化、人类演化之间的关系，以及气候快速变化的区域差异等。\n这段文字主要介绍了：","options":["火山灰的形成过程与主要特点","火山灰年代学的研究思路和价值","火山灰在自然环境中的分布状态","火山喷发对环境和人类的影响"],"answer":"B","analysis":"45. 正确答案：B\n解析：\n文段开篇引出火山灰的话题，并指出其形成与爆炸性火山活动有关，紧接着又指出火山灰形成的过程非常的短暂，\n随后通过结论词“所以”进行总结，指出在各种地质记录中，火山灰是一种高精度的绝对时间标志层，接着通过程度\n词“正是”强调，火山灰年代学是利用地质记录中的火山灰层来确定地质年代的科学，并且其可以解决一些重要的科学\n问题，最后通过“比如”进行举例说明。故文段为分总结构，重点强调了火山灰年代学是一门利用火山灰层来确定地质\n年代的科学，并且还可以解决一些重要的科学问题，对应B项。\nA项，“火山灰的形成过程”对应文段开篇，属于分述句部分内容，非重点，排除；\nC项，偏离文段核心话题“火山灰年代学”，且“分布状态”文段并未提及，无中生有，排除；\nD项，偏离文段核心话题“火山灰年代学”，且“火山喷发对环境和人类的影响”文段并未提及，无中生有，排除。\n故正确答案为B。\n【文段出处】《我科学家用贝叶斯统计方法厘清了准确的火山喷发年龄》\n【考点】\n中心理解题-主题词,中心理解题-程度词","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"来确定地质年代的科学，该学科可以解决一些重要的科学问题","why":"从火山灰的特点过渡到火山灰年代学后，文段集中说明了该学科如何确定年代及其能解决的问题。","origin":"逐题标记"}]},"国考 2023 地市级 行测#46":{"stem":"我国在改革开放后逐渐认识到保护民间文学艺术作品的重要性，并在1990年著作权法规定保护办法另行规定。但\n时隔三十余年，保护办法仍未出台。尽管如此，在著作权法颁布后，学界就民间文学艺术作品法律保护展开研究讨\n论，提出多种保护方案，涉及权利客体、权利主体、权利内容、保护期限、权利限制等方面的问题。当然，也有个\n\n别学者反对用著作权法保护民间文学艺术作品，主张通过公法加以保护。与此同时，国家版权局也加快推进相关立\n法，但因质疑声音过大而夭折。\n作者可能赞同下列哪一观点？","options":["通过公法保护民间文学艺术作品是最可行的路径","围绕民间文学艺术作品法律保护的争议流于表面","国家版权局应就民间文学保护倾听多方面意见","民间文学艺术作品法律保护缺位状态亟须改变"],"answer":"D","analysis":"46. 正确答案：D\n解析：\n文段开篇指出我国认识到保护民间文学艺术作品的重要性，并在著作权法中规定对保护办法另行规定。随后通\n过“但”表转折，指出当前民间文学艺术作品的保护办法仍然没有出台。接着介绍著作权法颁布后，学界针对民间文学\n艺术作品法律保护曾提出多种保护方案，涉及多方面问题，并指出个别学者主张通过公法加以保护。最后通过“与此\n同时”表示并列，介绍国家版权局也加快推进相关立法，但因受到强烈质疑而夭折。整个文段都是围绕民间文学艺术\n作品法律保护缺失这一问题展开论述，意在强调当前亟须出台民间文学艺术作品的保护法，对应D项。\nA项，“通过公法保护民间文学艺术作品”仅为个别学者的观点，“最可行”表述过于绝对，排除；\nB项，文段指出学界就民间文学艺术作品法律保护展开的研究讨论涉及多方面问题，“流于表面”与文意相悖，排除；\nC项，仅对应“与此同时”之后的内容，表述片面，且文段指出国家版权局的立法工作因受到质疑而夭折，并非没有“倾\n听多方面意见”，排除。\n故正确答案为D。\n【文段出处】《中国特色民间文学艺术作品著作权保护理论的构建》\n【考点】\n中心理解题-关联词-转折,中心理解题-特殊问法-其他","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"推断作者观点","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"时隔三十余年，保护办法仍未出台。","why":"转折突出保护办法长期缺位，后文的学界讨论和立法受阻共同指向作者对这一缺位的关切。","origin":"逐题标记","originalId":"s-6cbe71bb96acbbfe"},{"id":"s-300f89e88263b685","label":"通过转折定位文段重心","catalog_id":"ddd96a3c875dfde1","type":null,"role":"原有题组","field":"group","quote":"读出转折后的讨论重点","why":"原训练目录收录于该题组。","origin":"技能点库"}]},"国考 2023 地市级 行测#47":{"stem":"生物质炭由生物质在缺氧条件下经过高温转化而成，是一种富含碳素的多孔固体颗粒物质，大量有机废弃物都可\n用作制备原料。这一“古老”的新生事物能将生物质中不稳定的有机碳转化固定，具有多重潜在价值。在农业领域，土\n壤中添加生物质炭可以改善持水能力和养分供应，增加微生物活性，利于作物增产；在工业领域，生物质炭可以用\n作电池电极或催化剂，比如用作石墨的替代品；在环境领域，生物质炭作为优良的吸附材料，可以去除环境中的污\n染物，还可以吸附游离碳和氮化合物，减少生物质在转化过程中温室气体的排放。\n下列哪一说法无法从原文中得到支持？","options":["工业中使用生物质炭作为原料由来已久","自然界中生物质炭一般以固体形式存在","生物质炭可以由有机废弃物产生","利用生物质炭可以有效改良土壤"],"answer":"A","analysis":"47. 正确答案：A\n解析：\nA项，根据“这一‘古老’的新生事物”及“在工业领域，生物质炭可以用作电池电极或催化剂，比如用作石墨的替代品”可\n知，文段仅论述生物质炭为“‘古老’的新生事物”，可用于工业领域，但并非代表生物质炭用于工业原料由来已久，无\n中生有，当选；\n\nB项，根据“生物质炭由生物质在缺氧条件下经过高温转化而成，是一种富含碳素的多孔固体颗粒物质”可知，“生物质\n炭一般以固体形式存在”可以从原文中得到支持，排除；\nC项，根据“大量有机废弃物都可用作制备原料”可知，“生物质炭可以由有机废弃物产生”可以从原文中得到支持，排\n除；\nD项，根据“在农业领域，土壤中添加生物质炭可以改善持水能力和养分供应，增加微生物活性，利于作物增产”可\n知，“生物质炭可以有效改良土壤”可以从原文中得到支持，排除。\n本题为选非题，故正确答案为A。\n【文段出处】《生物质炭——转化固废“碳足迹”》\n【考点】\n常规解题方法","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-ef0f414c890a2427","label":"核对原文与选项","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"工业中使用生物质炭作为原料由来已久","why":"核对时需区分原文所述的工业用途与选项额外加入的使用时间判断。","origin":"逐题标记"}]},"国考 2023 地市级 行测#48":{"stem":"步兵融入联合作战，是指在联合作战体系架构下，以指挥信息系统为平台，根据作战需求，及时对接指挥关系，\n合理区分作战行动和保障路径，以实现步兵作战与联合作战的无缝对接。在联合作战中，可以采取火力打、远程\n击、空中炸、地面围等手段，歼灭敌方有生力量。步兵持有轻武器，善于近战歼敌，且机动灵活，适应性强，是直\n达战场、一线冲锋的优选力量。因此，近战歼灭敌方是步兵在联合作战体系内的首要任务。这意味着步兵将在其他\n军兵种力量的支援配合下，发挥夜战、近战和灵活机动的特长，实现歼灭据守之敌、驱逐进犯之敌、围捕空降之敌\n等目标。\n这段文字主要分析联合作战中：","options":["步兵的独特优势","步兵的主要任务","歼灭敌方的重要手段","步兵武器装备的特点"],"answer":"B","analysis":"48. 正确答案：B\n解析：\n文段开篇介绍步兵融入联合作战的定义，接着指出在联合作战中歼灭敌方有生力量的手段，后文介绍了步兵作战的\n优势。随后通过“因此”总结前文得出结论，强调步兵在联合作战体系内的首要任务是近战歼灭敌方，尾句通过指代\n词“这”指代前文的首要任务，后文对步兵如何完成近战歼灭敌方的任务进行进一步阐述。故文段重点围绕步兵在联合\n作战中的首要任务进行论述，对应B项。\nA项，“独特优势”对应结论前的内容，非重点，排除；\nC项，“重要手段”表述不明确，且缺少文段主题词“步兵”，偏离文段核心话题，排除；\nD项，“武器装备”对应结论前的内容，非重点，排除。\n故正确答案为B。\n【文段出处】《把准步兵融入联合作战的任务定位》\n【考点】\n普通考法","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"随后通过“因此”总结前文得出结论","why":"“因此”引出步兵职责的结论，尾句以“这”回指并继续说明，据此可抓住文段重点。","origin":"逐题标记"}]},"国考 2023 地市级 行测#49":{"stem":"肺鱼是一类可用“肺”呼吸的肉鳍鱼，它们的“肺”是特化的鱼鳔，能吸收空气。这一特殊技能使其可以摆脱水的束\n缚，在河水干涸时潜入洞穴，躲在分泌物形成的茧中，等待雨季到来。此外，肺鱼还是能“啃硬骨头”的鱼，它们咬合\n力强大，一些带壳的无脊椎动物也是其捕食对象，这种能吃带壳动物的能力，被称为食壳性或甲食性。泥盆纪早期\n的奇异鱼被认为是最原始的肺鱼，已经具有典型的肺鱼食壳性特征，比如有发达的齿板与短而粗壮的下颌。而杨氏\n鱼的系统发育位置较奇异鱼更为原始，是研究肺鱼类食壳性起源的关键。\n这段文字接下来最可能介绍：","options":["关于杨氏鱼的最新研究成果","动物食壳性特征的产生原因","肺鱼在生物演化史上的重要意义","杨氏鱼与其他泥盆纪物种的区别"],"answer":"A","analysis":"49. 正确答案：A\n解析：\n根据提问方式可知，本题为接语选择题。文段开篇介绍肺鱼是可用“肺”呼吸的肉鳍鱼，接着介绍肺鱼这一特殊技能在\n河水干涸时的作用，后文介绍肺鱼的咬合力强大，具有吃带壳动物的能力，并介绍此种能力被称为食壳性或甲食\n性，接着指出奇异鱼被认为是最原始的肺鱼，其已经具有食壳性特征，尾句强调杨氏鱼较奇异鱼更为原始，是研究\n肺鱼类食壳性起源的关键。故后文应继续围绕“杨氏鱼”这一话题展开论述，介绍“杨氏鱼”的相关研究，对应A项。\nB项，“动物食壳性特征”范围扩大，与文段最后讨论的核心话题不一致，无法与文段衔接，排除；\nC项，“生物演化史”与文段最后讨论的核心话题不一致，无法与文段衔接，排除；\nD项，“其他泥盆纪物种”属于无中生有的内容，无法与文段衔接，排除。\n故正确答案为A。\n【文段出处】《这种用“肺”呼吸的鱼，吃肉不吐壳》\n【考点】\n根据尾句确定答案","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-94e5b1e84b4945ab","label":"推断下文内容","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"是研究肺鱼类食壳性起源的关键。","why":"尾句将话题聚焦到杨氏鱼及其研究价值，为判断后文延续的研究对象提供线索。","origin":"逐题标记"}]},"国考 2023 地市级 行测#50":{"stem":"《新青年》创刊时名为《青年杂志》，因与《上海青年》杂志的名称部分雷同，从第二卷第一号开始，正式改名\n为《新青年》。这次更名本是被迫与无奈之举，但在陈独秀的巧妙处理下，却成为促进刊物发展的绝佳机遇。在更\n名后第一期杂志的篇首，刊登了陈独秀的文章，重新定义了“新青年”这一概念，提出要以“生理心理”的标准，而非“年\n龄”来区分新旧青年。这一期杂志还刊登了一则通告，告知读者杂志更名事宜。变被动为主动，赋予“新青年”三个字\n鲜明的时代意义与先锋的思想价值，也让《新青年》有了更加精准的办刊定位。\n这段文字中的“巧妙处理”指的是：","options":["精准定位受众，激发情感共鸣","采取差异策略，力求独树一帜","明晰用户心理，精准投放内容","借助事件传播，创造全新概念"],"answer":"D","analysis":"50. 正确答案：D\n解析：\n首先定位“巧妙处理”位于文段的中间，结合上下文语境，上文介绍《新青年》因名称与其他杂志部分雷同而被迫更\n名，本是无奈之举，随后，通过关联词“但”转折，指出陈独秀“巧妙处理”，随后后文对“巧妙处理”进行详细的解释说\n明，即在更名后的第一期杂志中刊登了陈独秀的文章，文章重新定义了“新青年”这一概念，同时，这期杂志还刊登了\n一则通告，告知读者杂志更名事宜，赋予“新青年”新的意义与价值。故“巧妙处理”指借助杂志更名事件传播全新的“新\n青年”概念，对应D项。\nA项，文段并未提及“精准定位受众”和“情感共鸣”，无中生有，排除；\nB项，文段并未论述《新青年》与其他刊物的策略区别，无中生有，排除；\nC项，文段并未提及“明晰用户心理”和“精准投放”，无中生有，排除。\n故正确答案为D。\n【文段出处】《<新青年>杂志的传播策略》\n【考点】\n实词","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-8713d7d1007a8167","label":"根据上下文理解词句含义","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"刊登了陈独秀的文章，重新定义了“新青年”这一概念","why":"后文用重新定义“新青年”和刊登更名通告两件事具体说明了“巧妙处理”的含义。","origin":"逐题标记","originalId":"s-05b453224b0dbbe0"}]},"国考 2023 地市级 行测#51":{"stem":"①这会使病情恶化，并最终导致相关的关节功能障碍\n②大量临床及基础研究显示，软骨病理性钙化是导致骨关节病软骨退变的关键致病机制之一\n\n③软骨病理性钙化通过诱导软骨细胞表型改变，最终呈现出一种病理状态\n④关节软骨渐进性退变是骨关节病最主要的病理改变\n⑤这些病态的软骨细胞通过有丝分裂增加自身数量，并通过分泌炎症因子、降解软骨基质引发组织炎症，最终发生\n凋亡\n⑥凋亡小体在吸收钙离子后，又会成为新的病理性矿化结晶，循环往复，致使软骨退变加重、剥脱\n将以上6个句子重新排列，语序正确的是：","options":["④②③⑤⑥①","④③⑤①②⑥","②③⑤⑥④①","②⑤④③①⑥"],"answer":"A","analysis":"51. 正确答案：A\n解析：\n对比选项，确定首句。②句指出骨关节病软骨退变的致病机制，④句通过“最主要”引出关节软骨渐进性退变这一话\n题，按照逻辑顺序，应先引出话题，再具体论述其致病机制，故④句更适合作为首句，排除C、D两项。\n继续对比选项，A、B两项的区别在于④句之后接②句还是③句，②句是对④句的具体论述，符合逻辑。③句围绕话\n题“软骨病理性钙化”展开论述，与④句话题不一致，无法衔接，排除B项。\n故正确答案为A。\n【文段出处】科技日报《导致关节软骨病理性钙化的元凶找到了》\n【考点】\n日常逻辑-其他","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-871196fcda246b8d","label":"依据衔接线索排列语句","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"应先引出话题，再具体论述其致病机制","why":"先找引出软骨退变的总述句，再接解释其成因的句子，并按指代和因果关系串起后续过程。","origin":"逐题标记","originalId":"s-5f620a52cb4fe64f"}]},"国考 2023 地市级 行测#52":{"stem":"①例如位于我国四川的深地核天体物理实验室，其上覆盖的垂直岩石厚达2400米\n②因此，旨在直接探测暗物质的实验室通常会建于极深的地下或山里，尽最大可能屏蔽掉这些干扰\n③直接探测暗物质的方式类似于守株待兔\n④当然，这种能量波动极其微弱，而且宇宙中的各种射线同样也有机会与这个原子核来一场亲密的邂逅，从而对实\n验结果产生干扰\n⑤专家解释说，我们生活在一团暗物质云中，每秒钟可能有几百万甚至上千万的暗物质粒子穿过我们的身体\n⑥直接探测暗物质的方法之一，就是利用精密的仪器密切观察大量的原子核，如果足够幸运，某一时刻暗物质碰撞\n到某个原子核，会在原子核上留下残余能量\n将以上6个句子重新排列，语序正确的是：","options":["⑥②①⑤③④","⑥④⑤②③①","③⑤⑥④②①","③⑥②⑤①④"],"answer":"C","analysis":"52. 正确答案：C\n解析：\n对比选项，确定首句，首句分别为③句和⑥句，③句引出“直接探测暗物质的方式”的话题，⑥句则具体解释了“直接\n探测暗物质的方法之一”，故⑥句是对③句的详细解释，根据观点+解释说明的逻辑顺序，③句更适合作首句，排除\nA、B两项。\n继续观察选项，①句出现“例如”为举例论述，之前应提出对应的观点。结合选项需判断①句之前是②句还是⑤句，②\n句提出直接探测暗物质的实验室通常会建于极深的地下或山里，与①句“四川的深地核天体物理实验室”衔接恰当，故\n②句应在①句之前，C项当选。⑤句提到暗物质粒子穿过我们的身体，与①句话题不一致，无法衔接，D项排除。\n故正确答案为C。\n【文段出处】《为何暗物质越来越少？能量低就会被宇宙“冰封”淘汰》\n【考点】\n观点+解释说明","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-871196fcda246b8d","label":"依据衔接线索排列语句","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"①句出现“例如”为举例论述，之前应提出对应的观点。","why":"先用总述引出探测方法，再根据“当然”“因此”衔接干扰与屏蔽措施，并将四川实验室的例子接在对应说明之后。","origin":"逐题标记","originalId":"s-5f620a52cb4fe64f"}]},"国考 2023 地市级 行测#53":{"stem":"事实推定是指法官在确证基础事实之上，借助经验法则推定待证事实的一种司法认知方法，这实际上是法官价值\n判断的过程。受个人经验、情感、家庭背景等因素的影响，法官进行价值判断时可能具有个体特征。价值判断联通\n了基础事实与推定事实，对各类事实所作的价值判断不同，得出的判决结论也将不同。因此，       。\n填入画横线部分最恰当的一项是：","options":["对事实推定价值判断的说理可提升判决的可接受性","需要对事实推定中的价值判断进行规范","程序正义有助于减少法官个体差异对判决的影响","价值判断不仅要符合形式合理性也要及时回应社会关切"],"answer":"B","analysis":"53. 正确答案：B\n解析：\n横线在文段结尾，由“因此”可知，横线处内容应总结前文。文段开篇引出“事实推定”这一话题，指出事实推定实际上\n是法官价值判断的过程，会受到多种因素的影响。接着指出法官进行价值判断时可能具有个体特征，对各类事实的\n价值判断不同，使得最终得出的判决结论也不同，故文段重在强调，法官在事实推定的过程中，对于价值判断的不\n同可能会影响判决结论这一问题，故尾句可针对这一问题提出对策，对应B项。\nA项，“对事实推定价值判断的说理”文段未提及，无法衔接上文，排除；\nC项，缺少核心话题“事实推定”，文段重在讨论事实的重要性，“程序正义”文段未提及，无中生有，排除；\nD项，缺少核心话题“事实推定”，且“要符合形式合理性也要及时回应社会关切”文段未提及，无法衔接上文，排除。\n故正确答案为B。\n【文段出处】《规范裁判文书对事实推定的价值判断说理》\n【考点】\n总结前文,提出对策","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-4eebda7bdff18647","label":"补全语句衔接","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"得出的判决结论也将不同。因此，","why":"尾句由“因此”承接价值判断差异影响判决的问题，需要补入针对该问题的对策。","origin":"逐题标记"}]},"国考 2023 地市级 行测#54":{"stem":"要推动老旧小区的适老化改造和无障碍环境建设，关键是提升整个社会对适老化改造的思想认识，实现适老化改\n造特别是居家适老化改造“心理无障碍”。要多渠道、全方位宣传引导居家适老化改造的政策与价值，转变老人、子女\n和社会对居家适老化改造的认知；同时，要通过养老服务中心、居家养老服务中心等载体，打造居家适老化改造样\n板房，强化直观感受，转变老人的传统观念，让老人逐步形成“为养老服务买单”、让子女形成更加关注父母居家养老\n环境的社会意识，提升适老化改造的家庭主观能动性。\n这段文字强调要：","options":["平衡主体利益，因地制宜推动适老化改造","统筹各方资源，激活适老化改造的多元力量","补位标准规范，提升适老化改造的品质与效率","加强宣传引导，做到适老化改造“心理无障碍”"],"answer":"D","analysis":"54. 正确答案：D\n解析：\n文段开篇通过“要······关键是”提出对策，强调提升整个社会对适老化改造的思想认识，对实现适老化改造特别是居家\n适老化改造“心理无障碍”的重要性，接着围绕这一对策论述其具体措施，首先要通过多渠道、全方位宣传引导转变老\n人、子女和社会对居家适老化改造的认知，然后通过并列关联词“同时”引出另一方面提升适老化改造思想认识的具体\n措施，即通过多种载体打造居家适老化改造样板房，转变老人的传统观念，提升适老化改造的家庭主观能动性，故\n整个文段重在强调通过宣传和引导的方式实现适老化改造“心理无障碍”，对应D项。\nA项，“因地制宜推动适老化改造”文段并未提及，无中生有，排除；\nB项，文段强调要实现适老化改造“心理无障碍”，选项“激活适老化改造的多元力量”偏离文段讨论的核心重点，排\n除；\nC项，“补位标准规范”文段并未提及，无中生有，排除。\n故正确答案为D。\n【文段出处】《改造只是起步 更多适老化堵点有待打通》\n【考点】\n中心理解题-关联词-对策,中心理解题-程度词,分述句特征-多角度论述","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"关键是提升整个社会对适老化改造的思想认识","why":"段首以“关键是”点明重点，后文的宣传引导和样板房展示都服务于转变观念。","origin":"逐题标记"}]},"国考 2023 地市级 行测#55":{"stem":"科学家早就知道月球有两面：面向地球的一面较为平坦，背向地球的一面凹凸不平，遍布撞击坑，月球为何具有\n截然不同的两副面孔，是其众多谜团之一。近日，科学家提出一种全新解释：数十亿年前，形成月球背面盆地的巨\n大撞击，产生了足以传遍月球的巨大热量，促成月幔物质的熔化，其中的稀土和放射性生热元素钍以及钾、磷等被\n携带到与撞击区域对称的月面，形成克里普岩，分布在月球正面风暴洋及其周围，放射性生热元素的集中，产生了\n月球表面的熔岩流，最终形成月球正面的火山平原。\n最适合做这段文字标题的是：","options":["盆地与平原：两副面孔，两种材质","月球上的熔岩流：亟待开发的宝藏","双面月球：一次撞击，两种结局","放射性生热元素：月球的化妆师"],"answer":"C","analysis":"55. 正确答案：C\n解析：\n文段开头提出问题，即月球为何有两副面孔，接下来给出解释说明，详细分析了撞击过后月球背面盆地与正面火山\n平原是如何形成的。故文段为总分结构，通过后文对撞击的分析解释月球正反两面截然不同的原因，对应C项。\nA项，未提及“月球”，且根据文意可知，月球正反面并非“两种材质”，排除；\nB项，熔岩流属于后文解释部分的内容，且文段未论述其价值，无中生有，排除；\nD项，“放射性生热元素”属于后文解释部分的内容，且文段主要回答“月球为何有两幅面孔”这一问题，非重点，排\n除。\n故正确答案为C。\n【文段出处】《双面月球：一次巨大撞击的两种结局》\n【考点】\n契合文段中心","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"通过后文对撞击的分析解释月球正反两面截然不同的原因","why":"标题要同时覆盖段首提出的月球两面差异和后文给出的撞击解释。","origin":"逐题标记"}]},"国考 2023 地市级 行测#56":{"stem":"在生命科学领域，观测和解析蛋白质结构一直是令科学家着迷的话题，但也面临着难度大、成本高、进展有限的\n局面。传统观测蛋白质结构的方法主要有三种：核磁共振、X射线、冷冻电镜。这些方法依赖大量试错和昂贵设备，\n每种结构的研究长达数年。现有的实验手段还不足以揭示一些重要的蛋白质结构，需借助更多计算生物学手段。用\n计算机来计算蛋白质结构，运算量惊人，连超级计算机也难以承受。为此，蛋白质结构预测成为结构生物学的重要\n分支。未来将通过人工智能算法，根据氨基酸序列预测其空间结构。\n这段文字没有解释：","options":["传统蛋白质结构观测方法存在哪些弊端","人工智能算法预测蛋白质结构有何优势","现有技术为何无法满足对蛋白质结构的探索","蛋白质结构预测为何成为结构生物学的分支"],"answer":"B","analysis":"56. 正确答案：B\n解析：\nA项，根据“这些方法依赖大量试错和昂贵设备，每种结构的研究长达数年”可知，解释了“传统蛋白质结构观测方法存\n在哪些弊端”，排除；\nB项，文段并未解释“人工智能算法预测蛋白质结构有何优势”，当选；\nC项，根据“现有的实验手段还不足以揭示一些重要的蛋白质结构，需借助更多计算生物学手段。用计算机来计算蛋\n白质结构，运算量惊人，连超级计算机也难以承受”可知，解释了“现有技术为何无法满足对蛋白质结构的探索”，排\n除；\nD项，根据“现有的实验手段还不足以揭示一些重要的蛋白质结构，需借助更多计算生物学手段。用计算机来计算蛋\n白质结构，运算量惊人，连超级计算机也难以承受。为此，蛋白质结构预测成为结构生物学的重要分支”可知，解释\n了“蛋白质结构预测为何成为结构生物学的分支”，排除。\n本题为选非题，故正确答案为B。\n【文段出处】人民网《弥补传统观测方法不足 加速生命科学领域研究 人工智能预测蛋白质结构（新知）》\n【考点】\n常规解题方法","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-ef0f414c890a2427","label":"核对原文与选项","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"这段文字没有解释","why":"逐项查找相应解释，并区分提及人工智能预测的用途和说明其优势。","origin":"逐题标记"}]},"国考 2023 地市级 行测#57":{"stem":"生态修复请求分为生态修复的行为请求和费用请求，前者是为了防止生态环境权益损害的发生或扩大，请求责任\n人停止污染破坏行为；当被破坏的生态环境无法恢复时，请求责任人进行人工修复。如果责任人不具有修复能力或\n意愿，可请求责任人承担修复费用。因此，修复行为请求应作为首要诉求，在责任人不能或不愿进行修复时，才能\n提出修复费用请求。在司法实践中，很多公益诉讼人却往往将修复费用请求作为首要诉求，但由于诉求和判决的修\n复费用数额不易确定，责任主体短期内难以承担修复费用，生态修复工作很难有效开展。\n这段文字意在说明：","options":["应该制定生态修复费用的分级标准","修复费用请求往往很难得到有效落实","应根据责任人的能力确定生态修复诉求","生态修复诉讼应当首先提出修复行为请求"],"answer":"D","analysis":"57. 正确答案：D\n解析：\n文段开篇指出生态修复请求分为“行为请求”与“费用请求”两种，然后围绕“行为请求”进行介绍，并说明“如果责任人不\n具有修复能力或意愿，可请求责任人承担修复费用”。接着通过结论标志词“因此”对前文进行总结，提出观点，即修\n复行为请求应排在修复费用请求之前，来作为生态修复的首要诉求。尾句通过阐述将修复费用请求作为首要诉求时\n很难有效开展工作这一现状，站在反面的角度论证前文观点。故文段重在强调生态修复的“修复行为请求应作为首要\n诉求”，对应D项。\nA项，“制定生态修复费用的分级标准”文段未提及，无中生有，排除；\nB项，“修复费用请求往往很难得到有效落实”对应文段尾句，为反面论证内容，非文段重点，排除；\nC项，文段重在强调“生态修复行为请求”，“责任人的能力”偏离文段重点，排除。\n故正确答案为D。\n【文段出处】《生态修复责任在环境公益诉讼中的实现路径》\n【考点】\n中心理解题-关联词-对策,分述句特征-引入铺垫,分述句特征-其他","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"因此，修复行为请求应作为首要诉求","why":"“因此”后的句子提出诉求次序，尾句以费用请求优先时的实践困境支持这一主张。","origin":"逐题标记"}]},"国考 2023 地市级 行测#58":{"stem":"早在1938年，毛泽东同志就说过：“我们这个民族有数千年的历史，有它的特点，有它的许多珍贵品。对于这\n些，我们还是小学生。今天的中国是历史的中国的一个发展；我们是马克思主义的历史主义者，我们不应当割断历\n史。从孔夫子到孙中山，我们应当给以总结，承继这一份珍贵的遗产。这对于指导当前的伟大的运动，是有重要的\n帮助的。”\n这段文字最适合做下列哪一观点的例证？","options":["拥有马克思主义科学理论指导是我们党坚定信仰信念、把握历史主动的根本所在","我们党历来用历史唯物主义的立场观点方法看待中华民族历史，继承和弘扬中华优秀传统文化","中华文明源远流长、博大精深，是中华民族独特的精神标识，是当代中国文化的根基","我们党的每一段革命历史，都是一部理想信念的生动教材"],"answer":"B","analysis":"58. 正确答案：B\n解析：\n文段开篇通过毛泽东同志的话指出中华民族的历史是有特点，有许多珍贵品的。接着提出对策，我们不应当割断历\n史，应当继承中华民族历史的珍贵遗产，并指出这一对策的重要意义。故文段重在强调我们应当继承中华民族历史\n的珍贵遗产，即中华优秀传统文化，对应B项。\nA项，“马克思主义”并非文段重点，文段重在强调要继承中华民族历史的珍贵遗产这一对策，与文意不符，排除；\nC项，文段并非强调中华文明的重要性，而是强调要继承中华民族历史的珍贵遗产这一对策，与文意不符，排除；\nD项，“理想信念”文段未提及，无中生有，排除。\n故正确答案为B。\n\n【文段出处】《王伟光：坚定文化自信 传承和弘扬中华优秀传统文化-新华网》\n【考点】\n中心理解题-特殊问法-其他","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-b2f959b1b4484115","label":"匹配例证与观点","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"这段文字最适合做下列哪一观点的例证？","why":"先提炼引文中总结和承继历史遗产的主张，再匹配能够由该引文支持的观点。","origin":"逐题标记","originalId":"s-1975cb775ec48b9b"}]},"国考 2023 地市级 行测#59":{"stem":"我国在经济快速发展的同时，培育和形成了全球少有的超大规模内需市场。与小规模经济体相比，超大规模经济\n体在全球经济运行中通常发挥着“锚”的作用。改革开放以来，我国之所以能够成功应对亚洲金融危机、国际金融危机\n等的冲击，一定程度上就得益于此。另外，超大规模市场的多样性意味着更强的内部稳定性。产业发展、区域发展\n的差异性可以减少冲击的影响，局部的内部冲击不易在全国形成共振效应；部分行业、部分区域发展面临困境，并\n不会对宏观经济总体稳定产生巨大冲击。\n这段文字意在说明：","options":["我国既是经济全球化的受益者也是贡献者","多措并举对保障内需市场稳定有重大意义","超大规模市场有助于我国经济保持稳定","超大规模经济体助力全球经济平稳运行"],"answer":"C","analysis":"59. 正确答案：C\n解析：\n文段开篇指出我国形成了超大规模内需市场，随后论述超大规模经济体的优势，即可以在全球经济运行中发挥\n如“锚”一般的稳定作用，让我国得以成功应对亚洲金融危机、国际金融危机等的冲击，接着通过关联词“另外”引导并\n列关系，指出超大规模市场的多样性意味着更强的内部稳定性，后文围绕这一观点进行具体的解释说明，故整个文\n段为并列结构，需对文段进行全面概括，文段通过两个方面的论述重在强调超大规模市场对于我国经济保持稳定的\n重要作用，对应C项。\nA项，未提及文段核心话题“超大规模市场”，偏离文段核心，排除；\nB项，“内需市场”对应并列的第一个方面，表述片面，且“多措并举”强调同时采取多个措施，文段并未提及，无中生\n有，排除；\nD项，文段重在强调超大规模市场在我国经济中发挥的作用，“全球经济”范围扩大，排除。\n故正确答案为C。\n【文段出处】《充分发挥超大规模市场优势》\n【考点】\n中心理解题-关联词-并列,中心理解题-主题词","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-gist","label":"概括文段主旨","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"另外，超大规模市场的多样性意味着更强的内部稳定性。","why":"“另外”连接抵御外部冲击与缓冲内部冲击两层论述，需要概括二者对我国经济稳定的共同作用。","origin":"逐题标记"}]},"国考 2023 地市级 行测#60":{"stem":"。我们要结合我国发展需要和可能，做好我国数字经济发展顶层设计和体制机制建设。要加强形势\n研判，抓住机遇，赢得主动。各级领导干部要提高数字经济思维能力和专业素质，增强发展数字经济本领，强化安\n全意识，推动数字经济更好服务和融入新发展格局。要提高全民全社会数字素养和技能，夯实我国数字经济发展社\n会基础。\n填入画横线部分最恰当的一项是：","options":["数字经济事关国家发展大局","要把发展数字经济自主权牢牢掌握在自己手中","数字经济影响程度之深前所未有","数字经济有利于推动各级资源要素快速流动"],"answer":"A","analysis":"60. 正确答案：A\n解析：\n横线出现在文段开头，需结合后文内容分析。文段首先指出我们要结合我国发展做好数字经济建设，随后提出各级\n领导干部要推动数字经济更好服务和融入新发展格局，尾句论述要提高全民全社会数字素养和技能，夯实我国数字\n经济发展社会基础。故文段通过“要”引导对策，从三个方面论述如何做好数字经济建设以推动我国发展，故横线处可\n以引出数字经济对我国发展的重要性，对应A项。\nB项，“发展数字经济自主权牢牢掌握在自己手中”强调要把握主动性，文段未提及，无中生有，排除；\nC项，强调了数字经济的重要性，但未提及“国家发展”，“影响程度之深”表述不明确，排除；\nD项，“各级资源要素快速流动”文段未提及，无中生有，排除。\n故正确答案为A。\n【文段出处】求是《（讲话）习近平：不断做强做优做大我国数字经济》\n【考点】\n概括后文","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-4eebda7bdff18647","label":"补全语句衔接","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"从三个方面论述如何做好数字经济建设以推动我国发展","why":"首句需要总领后文的多项对策，概括数字经济发展与国家发展的关系。","origin":"逐题标记"}]},"国考 2023 地市级 行测#61":{"stem":"商店销售某种商品，打八折销售时卖2件的利润与按定价销售时卖1件的利润相同，相当于降价120元/件销售时卖\n3件的利润。问该商品的定价为多少元/件？","options":["360","450","540","720"],"answer":"B","analysis":"61. 正确答案：B\n解析：\n设该商品每件定价为x元，成本为y元，根据题意可得：x-y=（80%x-y）×2······①，x-y=（x-120-y）×3······②，联立\n①②，解得x=450，即该商品的定价为450元/件。\n故正确答案为B。\n【考点】\n经济利润问题","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-216fb68de7a89297","label":"销售总利润等于单位售价减单位成本后乘以销量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"x-y=（80%x-y）×2","why":"将各方案的实际售价换算成单位利润，再按销量计算总利润。","origin":"逐题标记"},{"id":"s-55b69f4a0862f7f1","label":"计算成本、售价和利润","catalog_id":"M04","type":null,"role":"直接考查","field":"question","quote":"打八折销售时卖2件的利润与按定价销售时卖1件的利润相同","why":"把折扣和定额降价换算为实际售价，用总利润相等列式求定价。","origin":"逐题标记"}]},"国考 2023 地市级 行测#62":{"stem":"农科院在某村287名淡水鱼养殖人员中开展防病培训和育种培训。已知参加防病培训的养殖人员中，参加育种培\n训的人数比未参加的多21%；参加育种培训的养殖人员中，参加防病培训的人数比未参加的多76人。问共有多少人\n未参加任何一项培训？","options":["21","23","25","27"],"answer":"A","analysis":"62. 正确答案：A\n解析：\n根据“参加防病培训的养殖人员中，参加育种培训的人数比未参加的多21%”，可知只参加防病培训的人数是100的倍\n数。由于总人数为287人，当只参加防病培训的人数是200人时，参加防病培训的共有200×（1+21%）+200＞287\n人，排除。则只参加防病培训的人数为100人，此时既参加防病培训又参加育种培训的有100×（1+21%）=121人，\n只参加育种培训的有121-76=45人。未参加培训的人数=总数-只参加防病培训的人数-只参加育种培训的人数-两者都\n参加的人数=287-100-45-121=21人，即共有21人未参加任何一项培训。\n故正确答案为A。\n【考点】\n两集合,倍数特性法","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-46946a2a390ef27d","label":"两集合容斥原理","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"287-100-45-121","why":"将恰好参加一项的人数和两项都参加的人数各扣除一次，得到两项均未参加的人数。","origin":"逐题标记"},{"id":"s-36bcdccc44445c07","label":"用容斥计算重叠人数","catalog_id":"M07","type":null,"role":"直接考查","field":"question","quote":"参加育种培训的养殖人员中，参加防病培训的人数比未参加的多76人","why":"区分两项都参加与只参加一项的人数，将组内差值转为容斥所需的人数关系。","origin":"逐题标记"},{"id":"s-36722f3b0a111400","label":"根据周期、余数和整除确定数量","catalog_id":"M08","type":null,"role":"解题依据","field":"question","quote":"人数比未参加的多21%","why":"由人数为整数推出基数是100的倍数，再用总人数上限筛选。","origin":"逐题标记"}]},"国考 2023 地市级 行测#63":{"stem":"社区计划采购10份年货礼包发放给10户独居老人，每户发放1份。年货礼包有100元/份和150元/份的两种供选\n择，总预算不能超过1250元。如采购了150元/份的年货礼包，则需要优先在3户孤寡老人中选择发放对象。问共有多\n少种不同的发放方式？","options":["21","28","36","55"],"answer":"C","analysis":"63. 正确答案：C\n解析：\n设购买150元/份的年货礼包x份，则购买100元/份的年货礼包（10-x）份，故可列式：                            ，\n解得：     。因此年货礼包采购数量情况可分为以下6类：\n（1）150元的0份，100元的10份，有         种发放方式；\n（2）150元的1份，100元的9份，有          种不同的发放方式；\n（3）150元的2份，100元的8份，有          种不同的发放方式；\n（4）150元的3份，100元的7份，有          种发放方式；\n（5）150元的4份，100元的6份，有            种不同的发放方式；\n（6）150元的5份，100元的5份，有               种不同的发放方式。\n分类用加法，共有1+3+3+1+7+21=36种不同的发放方式。\n故正确答案为C。\n【考点】\n基础排列组合","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-15b3148c470f85ea","label":"从不同对象中无序选取若干对象的组合数","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"优先在3户孤寡老人中选择发放对象","why":"同一价位礼包的发放方案由领取户的集合确定，选择顺序不影响方案。","origin":"逐题标记"},{"id":"k-e9c35702da80f9b6","label":"分类加法计数原理","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"分类用加法","why":"每种方案只对应一个高价礼包份数，各类方案数可直接相加。","origin":"逐题标记"},{"id":"s-c0f6c7e3ae9d902e","label":"按条件分类计数与排列组合","catalog_id":"M05","type":null,"role":"直接考查","field":"answer","quote":"年货礼包采购数量情况可分为以下6类","why":"先由预算确定可行份数，再按优先规则从相应人群中选取发放对象。","origin":"逐题标记"}]},"国考 2023 地市级 行测#64":{"stem":"甲和乙两个工程队共同承担某项工程的施工任务。两队合作时各自的效率均比单独施工时高20%。已知两队合作\n施工需要25天完工；如甲先施工15天后乙加入，两队合作15天后剩余工作乙单独施工还需要10天完成。问甲队的效\n率是乙队的多少倍？","options":["","","",""],"answer":"D","analysis":"64. 正确答案：D\n解析：\n设甲队和乙队单独施工时的效率分别为x、y，根据题意可知：甲队和乙队合作施工时的效率分别为1.2x、1.2y。根据\n工程总量相等，则（1.2x+1.2y）×25=15x+（1.2x+1.2y）×15+10y，解得      ，即甲队的效率是乙队的   。\n\n故正确答案为D。\n【考点】\n工程问题-其他","figs":["64bc3a15d27a04e94940.pdf#11"],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-633dda86fead0d4c","label":"工作量等于工作效率乘以工作时间","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"（1.2x+1.2y）×25","why":"合作阶段将两队调整后的效率相加，再乘以该阶段的施工时间。","origin":"逐题标记"},{"id":"s-4d945e4b584e20e6","label":"用工作总量相等列工程方程","catalog_id":"9e4ed0684594686f","type":null,"role":"直接考查","field":"answer","quote":"（1.2x+1.2y）×25=15x+（1.2x+1.2y）×15+10y","why":"按不同阶段选用对应效率，将两种施工方案的总工作量列为等式。","origin":"逐题标记"}]},"国考 2023 地市级 行测#65":{"stem":"公园里有一片四边形草坪，沿对角线修建的小道相交于O点，O到四个顶点A、B、C、D的距离之比正好为1：\n2：3：4，一名工人花费1天正好完成AOB区域的修剪，问第二天至少需要额外增加多少名效率相同的工人一起工\n作，才能在当天内完成剩余草坪的修剪？","options":["8","10","11","12"],"answer":"B","analysis":"65. 正确答案：B\n解析：\n根据题意，设        的面积为S。因为         与        的高相同，底边BO：DO=2：4=1：2，根据结论“两个三\n角形的高相同，面积之比等于底之比”可得：                           ；同理，     与    的高相同，底边\nAO：CO=1：3，则                         ；      与       的高相同，底边AO：CO=1：3，则\n               。故四边形ABCD的面积=S+2S+6S+3S=12S。根据题意可知，一名工人花费1天正好完成\nAOB区域的修剪，即一名工人花费1天修剪的面积为S，剩余面积为12S-S=11S，则要在第二天完成修剪至少需要\n11S÷S=11名效率相同的工人，故至少需要额外增加11-1=10名效率相同的工人一起工作。\n故正确答案为B。\n【考点】\n平面几何,面积相关（新）","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-11296a74810194e8","label":"等高三角形的面积比等于对应底边长之比","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"面积之比等于底之比","why":"对角线分出的相邻三角形可取等高的对应底边，由线段比推出各块面积比。","origin":"逐题标记","originalId":"k-e7a6ae39aff5b3a7"},{"id":"s-ac5c371e800baa75","label":"按几何关系列式计算","catalog_id":"M09","type":null,"role":"直接考查","field":"question","quote":"沿对角线修建的小道相交于O点","why":"利用图中对角线上的线段关系求各块面积，再用基准区域面积折算剩余工作量。","origin":"逐题标记"}]},"国考 2023 地市级 行测#66":{"stem":"甲和乙两人8：00同时从A地出发前往B地，其中乙全程匀速，甲出发时的速度是乙的一半，但全程均匀加速。已\n知10：00甲追上乙，11：00甲到达B地。问乙什么时间到达B地？","options":["11：30","11：45","12：00","12：15"],"answer":"B","analysis":"66. 正确答案：B\n解析：\n赋值出发时甲的速度为1，乙的速度为2。从8：00至10：00，甲和乙的路程相同，即该时段甲的平均速度=乙的速度\n=2。根据匀加速运动的平均速度                    ，则10：00时甲的速度为2×2-1=3。因此，甲的速度每小时增加\n\n       ，故甲11：00时的速度为3+1=4。根据甲可计算，从A地到B地的路程为                    ，则乙全程所需\n\n时间为           小时    小时=3小时45分钟，即乙在11：45到达B地。\n\n故正确答案为B。\n【考点】\n普通行程,赋值法","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-a24ddb618deb5e16","label":"匀加速直线运动的平均速度等于初末速度的算术平均值","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"10：00时甲的速度为2×2-1=3","why":"由追及前的平均速度和初速度反推追及时的速度，再求后续时段的平均速度。","origin":"逐题标记"},{"id":"s-a678755b344c536e","label":"计算行程、相遇和追及","catalog_id":"M03","type":null,"role":"直接考查","field":"answer","quote":"赋值出发时甲的速度为1，乙的速度为2。","why":"按初速度比例赋值，用追及时同程确定甲的速度变化，再用共同全程求乙的用时。","origin":"逐题标记"}]},"国考 2023 地市级 行测#67":{"stem":"工厂从某周第一天开始生产某种零件，每周生产7天，从第二天开始每一天都比前一天多生产200件。已知工厂第\n三周的产量是第一周的2倍，问第几天其日产量第一次达到1万件？","options":["37","38","39","40"],"answer":"D","analysis":"67. 正确答案：D\n解析：\n根据题意可知，每天的零件产量构成等差数列。设第一天的零件产量为x件，根据等差数列通项公式\n              ，可得第一周第四天的零件产量                             件。结合等差数列求和公式\n             ，则第一周的零件产量                    件。同理，第三周第四天的产量（即第18天）的产\n量                         件，则第三周的产量                      件。根据“第三周的产量是第\n\n一周的2倍”可列式：7x+23800=2（7x+4200），解得x=2200。设该工厂第n天的日产量第一次达到1万件，则可列\n式：2200+（n-1）×200=10000，解得n=40，即第40天其日产量第一次达到1万件。\n故正确答案为D。\n【考点】\n数列问题","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-0603bd874be76ea7","label":"等差数列通项公式","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"2200+（n-1）×200=10000","why":"由首项和公差表示第n天的产量，用指定产量反求项号。","origin":"逐题标记"},{"id":"k-4295561e641ea3cf","label":"奇数项等差数列的和等于中间项乘以项数","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"结合等差数列求和公式","why":"每周的七项产量构成一段等差数列，可用该周第四天的产量计算周总产量。","origin":"逐题标记"},{"id":"s-d968fce424f6218d","label":"将和差倍比关系转为方程","catalog_id":"M01","type":null,"role":"直接考查","field":"answer","quote":"7x+23800=2（7x+4200）","why":"用同一首项表示两周产量，再把周产量的倍数关系写成方程。","origin":"逐题标记"},{"id":"s-9fc2e5daf6bbb9d8","label":"按增量或增速推算达标时间","catalog_id":"D08","type":null,"role":"直接考查","field":"question","quote":"第几天其日产量第一次达到1万件","why":"根据首日产量和固定日增量反推首次达标的日期序号。","origin":"逐题标记"}]},"国考 2023 地市级 行测#68":{"stem":"甲、乙二人合伙成立公司，约定每年利润的60%留作公司发展用途，40%按二人投资比例分配。已知公司成立第\n三年的利润比第二年高300万元，是第一年利润的3倍；甲第二年分配的金额是第三年的一半，且比第一年多20万\n元。问乙的投资额占比为多少？","options":["40%","50%","60%","75%"],"answer":"B","analysis":"68. 正确答案：B\n解析：\n设该公司第一年的利润为x万元，根据题意可得，第三年的利润为3x万元，第二年的利润为（3x-300）万元。已知每\n年二人将利润的40%按投资比例分配，且甲第二年分配的金额是第三年的一半，设甲的投资额占比为y，可列方程：\n                        ，解得x=200。则第一年的利润为200万元，第二年的利润为3×200-\n\n300=300万元。又因甲第二年分配的金额比第一年多20万元，可列方程：300×40%×y=200×40%×y+20，解得\ny=50%，故甲的投资额占比为50%，则乙的投资额占比为1-50%=50%。\n故正确答案为B。\n【考点】\n和差倍比问题","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-4f0ccba171d29d0b","label":"按比例分配时个体所得等于可分配总量乘以其所占比例","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"40%按二人投资比例分配","why":"先取年度利润的可分配部分，再乘个人投资占比得到该年的分红。","origin":"逐题标记","originalId":"k-b186dfe3d16fad0d"},{"id":"s-d968fce424f6218d","label":"将和差倍比关系转为方程","catalog_id":"M01","type":null,"role":"直接考查","field":"answer","quote":"300×40%×y=200×40%×y+20","why":"用各年的利润倍比和分红差额列方程，再由两人占比之和求乙的份额。","origin":"逐题标记"}]},"国考 2023 地市级 行测#69":{"stem":"从A地前往B地的道路前40%的路程为上坡路，其余为下坡路。张某驾驶满载的汽车从A地去B地卸货，然后空车\n返回A地。已知他满载时上坡的速度是下坡速度的一半，空车时上、下坡的速度分别是满载时的1.5倍和1.2倍。问他\n返程的用时是去程的多少倍？","options":["","","",""],"answer":"C","analysis":"69. 正确答案：C\n解析：\n赋值去程上坡路段长度为40，则去程下坡路段长度为60；赋值满载时上坡的速度为1，则满载时下坡速度为2。根据\n题意可知，空车时上坡速度=满载时上坡速度×1.5=1×1.5=1.5，空车时下坡速度=满载时下坡速度×1.2=2×1.2=2.4。\n去程时间为         ，返程时间为            ，则所求倍数             。\n\n故正确答案为C。\n【考点】\n普通行程,赋值法","figs":["64bc3a15d27a04e94940.pdf#12"],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-a770cf753cc5a5a3","label":"分段行程的总用时等于各段路程除以对应速度所得时间之和","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"返程的用时是去程的多少倍？","why":"求用时之比需要先分别按各坡段的路程和对应速度合计往返用时。","origin":"逐题标记"},{"id":"s-a678755b344c536e","label":"计算行程、相遇和追及","catalog_id":"M03","type":null,"role":"直接考查","field":"question","quote":"返程的用时是去程的多少倍？","why":"将去程的上坡段对应为返程的下坡段，按往返各段的实际速度计算用时比。","origin":"逐题标记"},{"id":"s-7c91e017f98bac24","label":"按已知比例为路程和基准速度赋值","catalog_id":null,"type":null,"role":"解题依据","field":"answer","quote":"赋值去程上坡路段长度为40，则去程下坡路段长度为60；赋值满载时上坡的速度为1，则满载时下坡速度为2。","why":"保留坡段长度占比与速度倍数关系，用便于运算的数值计算用时比。","origin":"逐题标记"}]},"国考 2023 地市级 行测#70":{"stem":"甲、乙两名职工负责国庆7天长假的值班工作，每天安排1人值班。已知乙至少值了2天班，且在国庆期间任一天\n结束后，甲的累计值班天数都比乙的多。问两人的值班日期安排有多少种不同的可能？","options":["6","9","10","14"],"answer":"D","analysis":"70. 正确答案：D\n解析：\n因乙至少值了2天班，且在国庆期间任一天结束后，甲的累计值班天数都比乙的多，则乙值班2天或者3天，且乙最早\n从第三天开始值班。分情况讨论如下：\n①乙值班2天：当乙从第三天开始值班时，则剩下的1天可以从第五天、第六天和第七天中选1天，有3种情况；当乙\n从第四天开始值班时，则剩下的1天可以从第五天、第六天和第七天中选1天，有3种情况；当乙从第五天开始值班\n时，则剩下的1天可以从第六天和第七天中选1天，有2种情况；当乙从第六天开始值班时，则剩下的1天为第七天，\n有1种情况，共有3+3+2+1=9种情况；\n②乙值班3天：当乙从第三天开始值班时，则剩下的2天可以为第五天和第七天、第六天和第七天，有2种情况；当乙\n从第四天开始值班时，则剩下的2天可以为第五天和第七天、第六天和第七天，有2种情况；当乙从第五天开始值班\n时，则剩下的2天为第六天和第七天，有1种情况，共有2+2+1=5种情况。\n因此，两人的值班日期安排有9+5=14种不同的可能。\n故正确答案为D。\n【考点】\n基础排列组合","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"技能题","current":false,"links":[{"id":"s-c0f6c7e3ae9d902e","label":"按条件分类计数与排列组合","catalog_id":"M05","type":null,"role":"直接考查","field":"question","quote":"结束后，甲的累计值班天数都比乙的多。","why":"按乙的值班总天数分类，把累计领先条件转化为乙每次值班的最早日期，再计数并汇总。","origin":"逐题标记"}]},"国考 2023 地市级 行测#71":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","options":["A","B","C","D"],"answer":"A","analysis":"71. 正确答案：A\n解析：\n元素组成不同，优先考虑属性规律。观察发现，整体无规律，题干所有图形均由黑球和白球构成，考虑黑白分开\n看，继续观察发现，每幅图形的白色区域均为轴对称图形，且对称轴每次顺时针旋转              ，因此？处图形的白色区域\n应为轴对称图形，且对称轴应为竖直方向。B项图形的白色区域为轴对称图形，但对称轴为水平方向，C、D两项图\n形的白色区域为非对称图形，均排除。只有A项符合。\n\n故正确答案为A。\n【考点】\n对称轴的方向/数量,黑白块类-对称性","figs":["64bc3a15d27a04e94940.pdf#12","64bc3a15d27a04e94940.pdf#13"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-449c824eeb0b7f3d","label":"辨认对称、曲直与开闭","catalog_id":"G04","type":null,"role":"直接考查","field":"answer","quote":"每幅图形的白色区域均为轴对称图形","why":"单独检查白色点阵能否沿一条轴镜像重合。","origin":"逐题标记"},{"id":"s-449334f5aeb5ea84","label":"追踪平移旋转翻转","catalog_id":"G01","type":null,"role":"直接考查","field":"answer","quote":"对称轴每次顺时针旋转","why":"依次追踪白色区域对称轴的转动方向，推定下一幅图的轴向。","origin":"逐题标记"}]},"国考 2023 地市级 行测#72":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","options":["A","B","C","D"],"answer":"C","analysis":"72. 正确答案：C\n解析：\n图形元素组成不同，无明显属性规律，考虑数量规律。题干图形明显被分割，优先考虑面数量，发现题干图形均为4\n个面，据此排除A项；继续观察发现题干图形均由几个图形拼接而成，还可以考虑图形间关系。题干图形均有一个黑\n块，观察发现题干图形中黑块均与3个白块存在公共边，选项中只有C项符合。\n故正确答案为C。\n【考点】\n面数量,相交于线","figs":["64bc3a15d27a04e94940.pdf#13"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-c96dc3b8ef59659c","label":"计数区域、交点与笔画","catalog_id":"G03","type":null,"role":"直接考查","field":"answer","quote":"题干图形均为4\n个面","why":"逐幅统计分割形成的区域总数。","origin":"逐题标记"},{"id":"s-73b5da0d39715bb4","label":"辨认图形接触、相交和公共边","catalog_id":"G05","type":null,"role":"直接考查","field":"answer","quote":"黑块均与3个白块存在公共边","why":"沿黑块边界统计有线段共边的白块。","origin":"逐题标记"}]},"国考 2023 地市级 行测#73":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","options":["A","B","C","D"],"answer":"A","analysis":"73. 正确答案：A\n解析：\n题干图形均由相同数量的黑色三角形和被分成5行的矩形框架组成，元素组成相同，优先考虑位置规律。观察发现，\n每幅图形分行明显，优先按行看。黑色三角形于其所在行内每次向右移动一格，且移动到最右侧时循环走，回到最\n左侧从头 再来，方向不变继续向右移动，排 C、D两项。继续观察发现，黑色三角形在移动的过程中依次顺时针旋\n转 90°，排除B项，只有A项符合。\n故正确答案为A。\n【考点】\n位置规律-综合","figs":["64bc3a15d27a04e94940.pdf#13","64bc3a15d27a04e94940.pdf#14"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-449334f5aeb5ea84","label":"追踪平移旋转翻转","catalog_id":"G01","type":null,"role":"直接考查","field":"answer","quote":"黑色三角形于其所在行内每次向右移动一格，且移动到最右侧时循环走","why":"同时追踪三角形在行内的循环位移和每一步顺时针旋转后的朝向。","origin":"逐题标记"}]},"国考 2023 地市级 行测#74":{"stem":"从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：","options":["A","B","C","D"],"answer":"C","analysis":"74. 正确答案：C\n解析：\n题干每行图形元素组成相似，优先考虑样式规律。九宫格中优先横向看，第一行中，图一和图二求异得到图三；经\n验证，第二行也满足此规律；第三行应用此规律，图一和图二求异，只有C项符合。\n故正确答案为C。\n【考点】\n求异/相减","figs":["64bc3a15d27a04e94940.pdf#14"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-49e530b3a2c0cd4c","label":"识别图形叠加和求同求异","catalog_id":"G02","type":null,"role":"直接考查","field":"answer","quote":"图一和图二求异得到图三","why":"按位置对齐同一行的前两图，保留仅在其中一图出现的元素。","origin":"逐题标记"}]},"国考 2023 地市级 行测#75":{"stem":"下图是给定的立体图形（大圆柱内的虚线部分为挖空部分），将其从任一面剖开，下面哪一项不可能是该立体图\n形的截面？","options":["A","B","C","D"],"answer":"A","analysis":"75. 正确答案：A\n解析：\n本题考查截面图。逐一分析选项。\nA项：无法截出，当选；\nB项：如下图所示，从上方圆柱向下经过空心圆柱竖切，可以截出，排除；\n\nC项：如下图所示，从上方圆柱向下经过空心圆柱斜切，可以截出，排除；\n\n\n\n\nD项：如下图所示，斜切下方圆柱同时经过空心部分，可以截出，排除。\n\n\n\n\n本题为选非题，故正确答案为A。\n【考点】\n空间类-截面图","figs":["64bc3a15d27a04e94940.pdf#14"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-b675a81beafb818e","label":"由视图截面或拼块还原立体","catalog_id":"G07","type":null,"role":"直接考查","field":"question","quote":"大圆柱内的虚线部分为挖空部分","why":"检验同一切面穿过实体和空腔时能否同时形成选项所示的各段轮廓。","origin":"逐题标记"}]},"国考 2023 地市级 行测#76":{"stem":"将一张直角三角形形状的纸片进行两次折叠，展开后的折痕将该三角形分成如图所示的a、b、c、d四个部分，则\n两次折叠后的纸片投影面积为：","options":["b+d+c-a","b+d-c","b+c-a","b+d-a"],"answer":"D","analysis":"76. 正确答案：D\n解析：\n第一步，将直角三角形先沿水平折痕进行折叠，即将面c和面d向下折叠，覆盖面b和面a，得到如下图形，此时折叠\n后面积为：b+d；\n\n\n\n\n第二步，将直角三角形沿着竖直折痕进行折叠，即将面b和面c向右折叠，覆盖面d和面a，得到如下图形，此时折叠\n后面积为：d+b-a。\n\n故正确答案为D。\n【考点】\n图形推理-其他","figs":["64bc3a15d27a04e94940.pdf#14","64bc3a15d27a04e94940.pdf#15"],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-3ab4c2989862405c","label":"两平面区域的并集面积等于各自面积之和减去重叠面积","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"后面积为：d+b-a。","why":"计算折叠后的投影面积时，重叠区域只计一次。","origin":"逐题标记"},{"id":"s-449334f5aeb5ea84","label":"追踪平移旋转翻转","catalog_id":"G01","type":null,"role":"直接考查","field":"answer","quote":"将面b和面c向右折叠，覆盖面d和面a","why":"沿两条折痕依次翻转各分区，根据折后位置识别完全覆盖和部分重叠。","origin":"逐题标记"}]},"国考 2023 地市级 行测#77":{"stem":"左图为等大的3个灰色正方体和15个白色正方体组合成的多面体，其可以切割为①、②和③三个小多面体，问③\n代表的多面体可能是：","options":["A","B","C","D"],"answer":"A","analysis":"77. 正确答案：A\n解析：\n本题考查立体拼合。如下图所示，将图①、图②进行旋转，结合A项，即可拼合成为左图的多面体。\n\n故正确答案为A。\n【考点】\n立体拼合-相同小方块类","figs":["64bc3a15d27a04e94940.pdf#15"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-b675a81beafb818e","label":"由视图截面或拼块还原立体","catalog_id":"G07","type":null,"role":"直接考查","field":"answer","quote":"将图①、图②进行旋转","why":"在整体中试配已知拼块，用方块的空间位置和颜色核对剩余部分。","origin":"逐题标记"}]},"国考 2023 地市级 行测#78":{"stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","options":["①③⑤，②④⑥","①④⑥，②③⑤","①③④，②⑤⑥","①②④，③⑤⑥"],"answer":"D","analysis":"78. 正确答案：D\n解析：\n本题为分组分类题目。元素组成不同，且无明显属性规律，考虑数量规律。观察发现，图2为“日”字变形图，图3为多\n端点图形，优先考虑笔画数。图①②④为一笔画图形，图③⑤⑥为两笔画图形，即图①②④为一组，图③⑤⑥为一\n组。\n故正确答案为D。\n【考点】\n笔画数","figs":["64bc3a15d27a04e94940.pdf#15","64bc3a15d27a04e94940.pdf#16"],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-c96dc3b8ef59659c","label":"计数区域、交点与笔画","catalog_id":"G03","type":null,"role":"直接考查","field":"answer","quote":"图①②④为一笔画图形，图③⑤⑥为两笔画图形","why":"依据线条的连接关系判断画完各图所需的最少笔画数。","origin":"逐题标记"}]},"国考 2023 地市级 行测#79":{"stem":"把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","options":["①⑤⑥，②③④","①④⑥，②③⑤","①②⑥，③④⑤","①③④，②⑤⑥"],"answer":"B","analysis":"79. 正确答案：B\n解析：\n本题为分组分类题目。元素组成相同，但无明显位置规律和属性规律，考虑数量规律。观察发现，题干每个图形均\n存在黑球或白球被分隔开的情况，考虑部分数。图①④⑥中，黑球的部分数均为1，白球的部分数均为3；图②③⑤\n中，黑球的部分数均为3，白球的部分数均为1。即图①④⑥为一组，图②③⑤为一组。\n故正确答案为B。\n【考点】\n部分数,黑白块类-部分数","figs":["64bc3a15d27a04e94940.pdf#16"],"state":"已标记","notes":[],"domains":[],"nature":"技能题","current":false,"links":[{"id":"s-599d7fb5a061494c","label":"分色计数图形的连通部分","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"存在黑球或白球被分隔开的情况，考虑部分数。","why":"将相接的同色球视为同一部分，分别计数后按两色部分数分类。","origin":"逐题标记","originalId":"s-de856d94fa921e25"}]},"国考 2023 地市级 行测#80":{"stem":"把下面六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：","options":["①②⑤，③④⑥","①②④，③⑤⑥","①④⑤，②③⑥","①③⑤，②④⑥"],"answer":"C","analysis":"80. 正确答案：C\n解析：\n本题为分组分类题目。元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形基本都由圆和正方\n形构成，优先考虑元素的个数，圆的数量依次为5、0、1、3、4、2，正方形的数量依次为4、1、2、2、3、3，单独\n看数量无规律，考虑二者运算图①④⑤中，圆的数量-正方形的数量=1；图②③⑥中，正方形的数量-圆的数量=1。\n故图①④⑤为一组，图②③⑥为一组。\n故正确答案为C。\n【考点】\n元素运算/换算","figs":["64bc3a15d27a04e94940.pdf#16","64bc3a15d27a04e94940.pdf#17"],"state":"已标记","notes":[],"domains":[],"nature":"技能题","current":false,"links":[{"id":"s-c96dc3b8ef59659c","label":"按两类图形元素数量之差分类","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"圆的数量-正方形的数量=1；图②③⑥中，正方形的数量-圆的数量=1。","why":"分别计数后比较有方向的数量差，据此区分两类图形。","origin":"逐题标记","originalId":"s-93a984b5f65c96ba"}]},"国考 2023 地市级 行测#81":{"stem":"微量鉴定是指运用物理学、化学和仪器分析等方法，通过对案件现场有关物质材料（材料特点多为体小量微、不\n易注意）的成分及其结构进行定性、定量分析，对检材的种类、检材和嫌疑样本的同类性和同一性进行鉴定。\n根据以上定义，下列涉及交通事故的鉴定属于微量鉴定的是：","options":["对车辆驾驶人采血，分析血液中的酒精含量，判断驾驶人是否存在酒后驾车嫌疑","现场提取、检验受害人毛发、衣物纤维，认定受害人是否与嫌疑人车辆存在接触","拆解车辆特定部位，查明车辆故障原因，用以鉴定其属于人为责任还是机械故障","通过人体损伤程度检验，确定伤害损伤部位与交通事故伤害后果的关联程度"],"answer":"B","analysis":"81. 正确答案：B\n\n解析：\n第一步：找出定义关键词。\n“对案件现场体小量微、不易注意的物质材料成分及其结构进行分析”、“对检材的种类、检材和嫌疑样本的同类性和\n同一性进行鉴定”。\n第二步：逐一分析选项。\nA项：对车辆驾驶人采血，分析血液中的酒精含量，“血液”不符合“体小量微、不易注意的物质材料”，并且也不涉及\n与嫌疑样本的比对，不符合定义，排除；\nB项：现场提取、检验受害人毛发、衣物纤维，“毛发，衣物纤维”符合“体小量微、不易注意的物质材料”，认定受害\n人是否与嫌疑人车辆存在接触，符合“对检材的种类、检材和嫌疑样本的同类性和同一性进行鉴定”，符合定义，当\n选；\nC项：拆解车辆特定部位，查明车辆故障原因，“车辆特定部位”不符合“体小量微、不易注意的物质材料”，并且也不\n涉及与嫌疑样本的比对，不符合定义，排除；\nD项：通过人体损伤程度检验，确定伤害损伤部位与交通事故伤害后果的关联程度，“人体”不符合“体小量微、不易注\n意的物质材料”，并且也不涉及与嫌疑样本的比对，不符合定义，排除。\n故正确答案为B。\n【考点】\n定义-方式目的","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"对检材的种类、检材和嫌疑样本的同类性和同一性进行鉴定","why":"从案例中识别检材及检验目的，并逐项核对题内条件。","origin":"逐题标记"}]},"国考 2023 地市级 行测#82":{"stem":"政策工具是指实现政策目标所要运用的手段与方法。政策工具可分为以下三种：\n（1）供给型政策工具，对政策目标起直接促进作用，通常体现政府的重要政策导向，包含资金、人才、设施、技\n术、信息等方面的有效支持；（2）需求型政策工具，对政策目标起到拉动作用，释放对政策目标的需求，减少外部\n干扰，包括服务外包、直接采购、国际交流与贸易管制等；（3）环境型政策工具，对政策目标起到间接促进作用，\n通常体现为通过目标、计划、法规、金融与税收等方式提供有利的政策环境，包括目标规划、金融服务、税收优\n惠、法规管制以及策略性措施等。\n根据上述定义，下列属于促进养老服务的需求型政策工具的是：","options":["政府向养老机构购买居家养老服务，为低保家庭60周岁以上失能老人提供服务","政府提供资金建设社区食堂，解决失能、独居、空巢等老年人“舌尖养老”难题","政府鼓励技工院校开设老年服务与管理、健康服务与管理、护理等养老服务相关专业","商务部发布《关于推动养老服务产业发展的指导意见》，提出打造养老服务品牌"],"answer":"A","analysis":"82. 正确答案：A\n解析：\n第一步：找出定义关键词。\n供给型政策工具：“对政策目标起直接促进作用”、“通常体现政府的重要政策导向”、“包含资金、人才、设施、技术、\n信息等方面的有效支持”；\n需求型政策工具：“对政策目标起到拉动作用，释放对政策目标的需求，减少外部干扰”、“包括服务外包、直接采\n购、国际交流与贸易管制等”；\n环境型政策工具：“对政策目标起到间接促进作用”、“通常体现为通过目标、计划、法规、金融与税收等方式提供有\n利的政策环境”、“包括目标规划、金融服务、税收优惠、法规管制以及策略性措施等”。\n第二步：逐一分析选项。\nA项：政府向养老机构购买居家养老服务，体现了将服务外包给养老机构，符合“对政策目标起到拉动作用，释放对\n政策目标的需求，减少外部干扰”、“包括服务外包、直接采购、国际交流与贸易管制等”，符合“需求型政策工具”定\n义，当选；\nB项：政府提供资金建设社区食堂，说明政府直接提供资金支持，不符合“包括服务外包、直接采购、国际交流与贸\n易管制等”，不符合“需求型政策工具”定义，符合“供给型政策工具”定义，排除；\nC项：政府鼓励技工院校开设养老服务相关专业，说明进行人才培养，提供人才支持，不符合“包括服务外包、直接\n采购、国际交流与贸易管制等”，不符合“需求型政策工具”定义，符合“供给型政策工具”定义，排除；\nD项：国务院发布《关于推动养老服务产业发展的指导意见》，说明提供有利的政策环境，提出目标规划，不符\n合“包括服务外包、直接采购、国际交流与贸易管制等”，不符合“需求型政策工具”定义，符合“环境型政策工具”定\n义，排除。\n故正确答案为A。\n【考点】\n常规问法","figs":[],"state":"已标记","notes":[],"domains":["公共管理"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"包括服务外包、直接采购、国际交流与贸易管制等","why":"提取案例中的政策手段，并与题内列出的需求型手段比对。","origin":"逐题标记"}]},"国考 2023 地市级 行测#83":{"stem":"民宿是指利用当地民居等相关闲置资源，经营用客房不超过4层、建筑面积不超过800平方米，主人参与接待，为\n游客提供体验当地自然、文化与生产生活方式的小型住宿设施。\n根据上述定义，下列属于民宿的是：","options":["王某在市中心有一套两居室的房子，过了马路就是知名的景区公园。王某将闲置房间租给那些节假日来旅游的家\n庭，并提供导游服务","某家庭农场开发亲子休闲旅游业务，建设了农业科普、亲子游玩场所，为孩子和家长营造一处寓教于乐的乡村乐\n园","李某通过某网上平台找到心仪城市的会员“交换”旅行，即双方各自为对方提供住宿，住在对方家中深入体验当地的\n风土人情","张某在古镇上有一所老宅。他和某平台签订合同，将老宅租给该平台运营。该平台将老宅装修，并提供完善的酒\n店式服务机制"],"answer":"A","analysis":"83. 正确答案：A\n解析：\n第一步：找出定义关键词。\n“利用当地民居等相关闲置资源”、“经营用客房不超过4层、建筑面积不超过800平方米”、“主人参与接待，为游客提供\n体验当地自然、文化与生产生活方式”。\n第二步：逐一分析选项。\nA项：王某有一套两居室的房子，将闲置房间租给旅游家庭，符合“利用当地民居等相关闲置资源”、“经营用客房不超\n过4层、建筑面积不超过800平方米”，并提供导游服务，符合“主人参与接待，为游客提供体验当地自然、文化与生产\n生活方式”，符合定义，当选；\n\nB项：某家庭农场开发亲子休闲旅游业务，未提及该农场是否为闲置资源，不符合“利用当地民居等相关闲置资源”，\n也未提及该农场是否有经营用客房，不符合“经营用客房不超过4层、建筑面积不超过800平方米”，建设了农业科普、\n亲子游玩场所，不符合“主人参与接待，为游客提供体验当地自然、文化与生产生活方式”，不符合定义，排除；\nC项：李某与心仪城市的会员“交换”旅行，双方各自为对方提供住宿，说明双方是互相为对方提供住宿，而非用于经\n营，不符合“经营用客房”，不符合定义，排除；\nD项：张某将古镇的老宅租给某平台，符合“利用当地民居等相关闲置资源”，将老宅租给该平台运营，由该平台提供\n完善的酒店式服务机制，说明该老宅的主人张某并不提供接待服务，不符合“主人参与接待，为游客提供体验当地自\n然、文化与生产生活方式”，不符合定义，排除。\n故正确答案为A。\n【考点】\n定义-方式目的","figs":[],"state":"已标记","notes":[],"domains":["经济"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"利用当地民居等相关闲置资源，经营用客房不超过4层、建筑面积不超过800平方米，主人参与接待","why":"从案例中核对资源来源、住宿经营及接待主体等条件。","origin":"逐题标记"}]},"国考 2023 地市级 行测#84":{"stem":"背信规避是指当风险来源为另一个体而不是自然条件时，人们普遍更不愿意冒险，即在同等条件下，人们对于人\n为风险的规避程度高于对客观风险的规避程度，体现在人们面对人为风险时比面对客观风险时表现得更保守。\n根据上述定义，下列没有体现背信规避的是：","options":["在对客观题阅卷方式意愿的调查中，学生更愿意选择机器阅卷而非人工阅卷","决定谁先开球时，双方球员都倾向于由裁判抛硬币决定而非裁判随机指定","在老师打算指派一个人多承担一项任务时，同学们纷纷表示要抽签决定","与老司机相比，坐新手司机开的车时，后排座上的乘客主动系安全带的更多"],"answer":"D","analysis":"84. 正确答案：D\n解析：\n第一步：找出定义关键词。\n定义中比较易懂的关键词在于：“风险来源为另一个体而不是自然条件时”、“人为风险的规避程度高于对客观风险的\n规避程度”。\n第二步：逐一分析选项。\nA项：在客观题阅卷方式中，学生更愿意选择机器阅卷而非人工阅卷，机器阅卷对应客观风险，人工阅卷对应人为风\n险，“学生更愿意选择机器阅卷而非人工阅卷”，符合“人为风险的规避程度高于对客观风险的规避程度”，符合定义，\n排除；\nB项：在决定谁先开球时，双方球员都倾向于由裁判抛硬币决定而非裁判随机指定，抛硬币对应客观风险，裁判指定\n对应人为风险，“双方球员都倾向于由裁判抛硬币决定而不是裁判指定”，符合“人为风险的规避程度高于对客观风险\n的规避程度”，符合定义，排除；\nC项：在老师打算指派一个人多承担一项任务时，同学们纷纷表示要抽签决定，抽签对应客观风险，老师指派对应人\n为风险，“同学们纷纷表示要抽签决定”，符合“人为风险的规避程度高于对客观风险的规避程度”，符合定义，排除；\nD项：与老司机相比，坐新手司机开的车时，后排座上的乘客主动系安全带的更多，老司机开车与新手司机开车都对\n应人为风险，没有体现客观风险，“坐新手司机开的车时后排座上的乘客主动系安全带的更多”，只是人为风险规避程\n度的比较，不符合“人为风险的规避程度高于对客观风险的规避程度”，不符合定义，当选。\n本题为选非题，故正确答案为D。\n【考点】\n大前提","figs":[],"state":"已标记","notes":[],"domains":["其他"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"question","quote":"体现在人们面对人为风险时比面对客观风险时表现得更保守。","why":"先区分两种风险的来源，再检查案例是否体现定义要求的规避倾向。","origin":"逐题标记"}]},"国考 2023 地市级 行测#85":{"stem":"小中取大法是指在决策时，首先计算各方案在不同自然状态下的收益，并找出各方案在最差自然状态下的收益，\n然后进行比较，选择在最差自然状态下收益最大或损失最小的方案作为最终方案的一种决策方法。大中取大法是指\n在决策时，首先计算各方案在不同自然状态下的收益，并找出各方案在最好自然状态下的收益，然后进行比较，选\n择在最好自然状态下收益最大的方案作为最终方案的一种决策方法。\n\n\n\n\n根据上述定义，分别使用小中取大法和大中取大法对上述方案进行决策，所选择的方案依次是：","options":["方案二和方案二","方案二和方案一","方案三和方案一","方案三和方案二"],"answer":"D","analysis":"85. 正确答案：D\n解析：\n第一步：找出定义关键词。\n小中取大法：“找出各方案在最差自然状态下的收益”、“选择在最差自然状态下收益最大或损失最小的方案”；\n大中取大法：“找出各方案在最好自然状态下的收益”、“选择在最好自然状态下收益最大的方案作为最终方案”。\n第二步：逐一分析选项。\n依据设问使用“小中取大法”，需要符合“找出各方案在最差自然状态下的收益”、“选择在最差自然状态下收益最大或损\n失最小的方案”，表格中销路差此列对应的数据就是最差自然状态下的收益，方案三是销路差中收益最大的方案，因\n此根据“小中取大法”应选择方案三；\n依据设问使用“大中取大法”，需要符合“找出各方案在最好自然状态下的收益”、“选择在最好自然状态下收益最大的方\n案作为最终方案”，表格中销路好此列对应的数据就是最好自然状态下的收益，方案二是销路好中收益最大的方案，\n因此根据“大中取大法”应选择方案二，只有D项符合。\n故正确答案为D。\n【考点】\n常规问法","figs":[],"state":"已标记","notes":[],"domains":["数学"],"nature":"综合题","current":false,"links":[{"id":"k-799c394067efe0da","label":"小中取大法：比较各方案的最低收益并取最大者","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"选择在最差自然状态下收益最大或损失最小的方案","why":"该准则决定第一项决策应按各方案的最低收益进行比较。","origin":"逐题标记"},{"id":"k-47d3f93ad044253d","label":"大中取大法：比较各方案的最高收益并取最大者","catalog_id":null,"type":"方法与技能","role":"直接考查","field":"answer","quote":"选择在最好自然状态下收益最大的方案作为最终方案","why":"该准则决定第二项决策应按各方案的最高收益进行比较。","origin":"逐题标记","originalId":"k-5fccd69feeab8b6b"},{"id":"s-db4885a9ca6b54c2","label":"从收益表按方案提取并比较极值","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"表格中销路差此列对应的数据就是最差自然状态下的收益","why":"在表中定位各方案对应的极端状态收益，再跨方案比较。","origin":"逐题标记","originalId":"s-d60af0c699160b1b"}]},"国考 2023 地市级 行测#86":{"stem":"异业合作是指两个或两个以上不同行业的企业，通过分享市场营销中的资源，以达到降低成本、提高效率、增强\n市场竞争力等目的的一种营销策略。\n根据上述定义，下列体现了异业合作的是：","options":["某集团下属的两家餐饮公司通过公众号互推产品信息，提升了各自的品牌影响力","某互联网公司和商业银行共同发行联名信用卡，办卡成员将享受更大购物优惠","某日用品企业将不同尺寸的收纳盒组成套装促销，销量剧增，其他企业也纷纷效仿","某运动品牌在奥运会期间推出绘有奥运标志的限量款球鞋，搭配赠送新奥运吉祥物"],"answer":"B","analysis":"86. 正确答案：B\n解析：\n第一步：找出定义关键词。\n“两个或两个以上不同行业的企业”、“分享市场营销中的资源”、“降低成本、提高效率、增强市场竞争力”。\n\n第二步：逐一分析选项。\nA项：某集团下属的两家餐饮公司，都是餐饮行业，不符合“两个或两个以上不同行业的企业”，不符合定义，排除；\nB项：某互联网公司和商业银行，分属两个不同的行业，符合“两个或两个以上不同行业的企业”，共同发行联名信用\n卡，符合“分享市场营销中的资源”，办卡成员将享受更大购物优惠，说明可以通过更大的购物优惠来吸引客户办卡，\n增强市场竞争力，符合“降低成本、提高效率、增强市场竞争力”，符合定义，当选；\nC项：某日用品企业将不同尺寸的收纳盒组成套装促销的行为被其他企业效仿，说明其他企业也卖收纳盒，没有体现\n出是不同的行业，不符合“两个或两个以上不同行业的企业”，且其他企业只是效仿该企业的做法，并没有涉及到“分\n享市场营销中的资源”，不符合定义，排除；\nD项：某运动品牌在奥运会期间推出绘有奥运标志的限量款球鞋，搭配赠送新奥运吉祥物，只涉及某运动品牌一个企\n业，不符合“两个或两个以上不同行业的企业”，不符合定义，排除。\n故正确答案为B。\n【考点】\n主客体","figs":[],"state":"已标记","notes":[],"domains":["经济"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"“两个或两个以上不同行业的企业”、“分享市场营销中的资源”","why":"核对参与方的行业归属以及实际开展的资源共享行为。","origin":"逐题标记"}]},"国考 2023 地市级 行测#87":{"stem":"植物病害分为侵染性病害和非侵染性病害。侵染性病害是由病原物引起的，可以在植物个体间互相传染的病害；\n非侵染性病害是由于环境不良、营养元素不足等非生物因素造成的病害，由于没有病原物的侵袭，所以不会在植物\n间相互传染。\n根据上述定义，下列属于非侵染性病害的是：\n①需要微酸性生长环境的杜鹃花，种植在偏碱性土壤中，叶片会黄化\n②植株浇水过多，盆土积水后，由于植株根系缺氧，会导致植株萎蔫\n③除草剂使用不当会引起西瓜苗嫩叶黄化，叶片枯焦，植株萎缩\n④灰葡萄孢真菌会引起番茄灰霉病，发病后造成番茄大量烂果","options":["仅①④","仅①②","仅①②③","仅②③④"],"answer":"C","analysis":"87. 正确答案：C\n解析：\n第一步：找出定义关键词。\n侵染性病害：“由病原物引起”、“可以在植物个体间互相传染”；\n非侵染性病害：“由于环境不良、营养元素不足等非生物因素造成”、“不会在植物间相互传染”。\n第二步：逐一进行分析。\n①：杜鹃花由于生长在偏碱性土壤环境中而导致其叶片黄化，其中偏碱性土壤属于环境因素，符合“由于环境不良、\n营养元素不足等非生物因素造成”、“不会在植物间相互传染”，符合“非侵染性病害”的定义；\n②：植株由于盆土积水后，根系缺氧导致其萎蔫，其中盆土积水属于环境因素，符合“由于环境不良、营养元素不足\n等非生物因素造成”、“不会在植物间相互传染”，符合“非侵染性病害”的定义；\n③：西瓜苗由于除草剂使用不当而导致其嫩叶黄化等后果，其中除草剂使用不当属于非生物因素，符合“由于环境不\n良、营养元素不足等非生物因素造成”、“不会在植物间相互传染”，符合“非侵染性病害”的定义；\n④：番茄大量烂果是由灰葡萄孢真菌引起的，其中灰葡萄孢真菌属于病原物，而不是非生物因素，并且番茄因感染\n灰霉病而大量烂果，符合“由病原物引起”、“可以在植物个体间互相传染”，符合“侵染性病害”定义，不符合“非侵染性\n病害”的定义。\n综上，仅①②③符合“非侵染性病害”的定义。\n故正确答案为C。\n【考点】\n常规问法","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"由于环境不良、营养元素不足等非生物因素造成","why":"从病例描述中识别致病因素，并结合传播条件核对定义。","origin":"逐题标记"}]},"国考 2023 地市级 行测#88":{"stem":"联合式构词法是由两个意义相同、相反或相对的词根联合起来构成新词的方法，在词内两个词根是平等的，没有\n主从、正副之分。\n根据上述定义，下列使用了联合式构词法的是：","options":["“叮当”，因摹拟动作的声音而构成的词","“椅子”，在单字“椅”后面附加“子”而构成的词","“蹉跎”，由韵母相同的两个单字组合构成意义与单字无关的词","“开关”，由“开”和“关”两个单字组合而构成的词"],"answer":"D","analysis":"88. 正确答案：D\n解析：\n第一步：找出定义关键词。\n“由两个意义相同、相反或相对的词根联合起来构成新词”、“两个词根是平等的，没有主从、正副之分”。\n第二步：逐一分析选项。\nA项：“叮”和“当”代表两个不同的声音，二者不符合“由两个意义相同、相反或相对的词根联合起来构成新词”，不符合\n定义，排除；\nB项：“椅子”中侧重于“椅”，即“椅”为主，“子”为从，不符合“两个词根是平等的，没有主从、正副之分”，不符合定\n义，排除；\nC项：“蹉”的意思有失足、差错等，而“跎”的意思有背负、驼背等，二者不符合“由两个意义相同、相反或相对的词根\n联合起来构成新词”，不符合定义，排除；\nD项：“开关”是指电器装置上接通和截断电路的设备，“开”有打开的意思，“关”有关闭的意思，二者意思相反且无主从\n之分，符合“由两个意义相同、相反或相对的词根联合起来构成新词”、“两个词根是平等的，没有主从、正副之分”，\n符合定义，当选。\n故正确答案为D。\n【考点】\n单定义-其他句式","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"“由两个意义相同、相反或相对的词根联合起来构成新词”、“两个词根是平等的，没有主从、正副之分”","why":"逐项核对词根的意义关系和句内所述的平等条件。","origin":"逐题标记"}]},"国考 2023 地市级 行测#89":{"stem":"细胞学检查是指对患者病变部位脱落、刮取或穿刺抽取的细胞，进行病理形态学的观察并做出定性诊断的检查方\n式。细胞学检查主要应用于肿瘤的诊断，也可用于某些疾病的检查和诊断，如内部器官炎症性疾病的诊断和激素水\n平的判定等。\n根据上述定义，下列属于细胞学检查的是：","options":["采集患者血液样本，分析血细胞比例变化，判断患者是否出现感染","针对外伤患者皮肤纤维细胞的过度增生，实行激光打磨法，抑制炎性细胞浸润，修复再生皮肤组织","通过拉网法收集食道癌患者的食道脱落细胞，鉴定细胞形态，明确癌变性质","对脑疝患者脑室穿刺，放出脑室液以降低脑压，后再次穿刺注入造影剂，诊断其颅内占位病变的情况"],"answer":"C","analysis":"89. 正确答案：C\n\n解析：\n第一步：找出定义关键词。\n“患者病变部位脱落、刮取或穿刺抽取的细胞”、“进行病理形态学的观察”、“做出定性诊断的检查方式”。\n第二步：逐一分析选项。\nA项：采集患者血液样本，分析血细胞比例变化，不涉及病变部位的细胞，不符合“患者病变部位脱落、刮取或穿刺\n抽取的细胞”，不符合定义，排除；\nB项：激光打磨抑制炎性细胞浸润，修复再生皮肤组织，属于一种治疗方法，而不是定性诊断的检查方式，不符\n合“做出定性诊断的检查方式”，不符合定义，排除；\nC项：食道癌患者的食道脱落细胞，符合“患者病变部位脱落的细胞”，鉴定细胞形态，符合“进行病理形态学的观\n察”，明确癌变性质，符合“做出定性诊断的检查方式”，符合定义，当选；\nD项：放出脑室液以降低脑压，后再次穿刺注入造影剂，诊断其颅内占位病变的情况，是通过注入造影剂进行观察诊\n断，而不是对细胞进行观察诊断，不符合“患者病变部位脱落、刮取或穿刺抽取的细胞”，不符合定义，排除。\n故正确答案为C。\n【考点】\n定义-方式目的","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"“患者病变部位脱落、刮取或穿刺抽取的细胞”、“进行病理形态学的观察”、“做出定性诊断的检查方式”","why":"把诊疗过程中的取样、观察和判断分别与定义条件对应。","origin":"逐题标记"}]},"国考 2023 地市级 行测#90":{"stem":"预判设计是一种能够引导用户、缩短用户行为路径的有效设计手段。它可以根据用户的行为或用户所在的场景，\n让功能“主动找到”用户，并让用户与之产生自然的交互，为用户提供更好的使用体验，本质就是为用户多想一步，让\n用户使用起来尽量简单。\n根据上述定义，下列不属于预判设计的是：","options":["某购物软件，根据用户输入的搜索关键词，将商品按与关键词的相关性排列","某翻译软件，用户第一次点击播放，语音速度正常；再次点击，语音速度变慢","某外卖软件，当用户对店家给出差评，系统自动勾选“将评价设为匿名评价”","某购物软件，所选商品缺货时，出现“找相似”按钮，点击可看到同款、相似商品"],"answer":"A","analysis":"90. 正确答案：A\n解析：\n第一步：找出定义关键词。\n“引导用户、缩短用户行为路径”、“让功能‘主动找到’用户”、“为用户多想一步，让用户使用起来尽量简单”。\n第二步：逐一分析选项。\nA项：用户在购物软件输入搜索关键词以后，购物软件列出与用户搜索关键词相关的商品，此时仅仅是该软件配合了\n用户的搜索行为，并没有对其下一步行为进行预判，更没有引导用户，不符合“引导用户、缩短用户行为路径”、“让\n功能‘主动找到’用户”、“为用户多想一步，让用户使用起来尽量简单”，不符合定义，当选；\nB项：某翻译软件第一次点击播放，语速正常，再次点击，语速变慢，体现了产品会预判用户可能是刚刚没听清楚、\n或者想听清某个词的念法等，从而不用等用户自行操作，而主动将语音播放速度变慢，符合“引导用户、缩短用户行\n为路径”、“让功能‘主动找到’用户”、“为用户多想一步，让用户使用起来尽量简单”，符合定义，排除；\nC项：某外卖软件，当用户给差评时，系统自动勾选“匿名评价”，因为绝大多数用户给商家差评时都不希望商家看到\n自己的身份，所以该软件不等用户自行勾选匿名评价，而自动帮用户勾选，缩短了用户行为路径，为用户多想一\n步，符合“引导用户、缩短用户行为路径”、“让功能‘主动找到’用户”、“为用户多想一步，让用户使用起来尽量简单”，\n符合定义，排除；\nD项：大多数用户在购物软件上遇到想要的商品缺货时，接下来最可能的就是去找一些相似的商品，所以某购物软件\n为用户多想了一步，不用等用户自行搜索相似商品，而是当所选商品缺货时，自动出现“找相似”按钮，点击可看到同\n款、相似商品，符合“引导用户、缩短用户行为路径”、“让功能‘主动找到’用户”、“为用户多想一步，让用户使用起来\n尽量简单”，符合定义，排除。\n本题为选非题，故正确答案为A。\n【考点】\n定义-方式目的","figs":[],"state":"已标记","notes":[],"domains":["科技"],"nature":"技能题","current":false,"links":[{"id":"s-conditions","label":"按题内定义核对案例条件","catalog_id":"L04","type":null,"role":"直接考查","field":"answer","quote":"引导用户、缩短用户行为路径","why":"结合功能的触发场景和后续操作，核对它是否主动预判并简化路径。","origin":"逐题标记"}]},"国考 2023 地市级 行测#91":{"stem":"小计：总计","options":["平均值：总值","被乘数：总数","单科分：总分","分目录：总目"],"answer":"C","analysis":"91. 正确答案：C\n解析：\n第一步：判断题干词语间逻辑关系。\n“小计”是数字列表中一部分数字的总和，“总计”是数字列表中所有数字的总和，因此，所有“小计”相加可以得到“总\n计”，二者是对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：“平均值”乘以群体总个数等于“总值”，与题干逻辑关系不一致，排除；\nB项：“被乘数”指乘法中被乘的数字，一般放在算式的前面，“总数”是所有数的总和，二者无明显逻辑关系，与题干\n逻辑关系不一致，排除；\nC项：所有“单科分”相加可以得到“总分”，二者是对应关系，与题干逻辑关系一致，当选；\nD项：“分目录”指在各部分之前的目录，“总目”指在整个文档之前的目录，“总目”是对“分目录”的汇总，不存在相加的\n计算关系，与题干逻辑关系不一致，排除。\n故正确答案为C。\n\n【考点】\n对应-其他","figs":[],"state":"已标记","notes":[],"domains":["数学","形式逻辑"],"nature":"综合题","current":false,"links":[{"id":"k-4f447e889052dc5c","label":"小计与总计的含义及求和关系","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“小计”是数字列表中一部分数字的总和，“总计”是数字列表中所有数字的总和","why":"两个术语的含义确定了将各分组小计相加得到总计的关系。","origin":"逐题标记","originalId":"k-c5bd1873f6671b75"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"所有“单科分”相加可以得到“总分”","why":"比较各词对能否通过汇加分项得到总体数值。","origin":"逐题标记"}]},"国考 2023 地市级 行测#92":{"stem":"猛药去疴：重典治乱","options":["民生在勤：勤则不匮","从善如登：从恶如崩","静以修身：俭以养德","名非天造：必从其实"],"answer":"C","analysis":"92. 正确答案：C\n解析：\n第一步：判断题干词语间逻辑关系。\n“猛药去疴”意思是通过威力大的药达到去除疾病的目的，“重典治乱”意思是通过严酷的刑罚达到惩治坏人的目的，二\n者都可指问题很严重，必须采取有力的措施来处理，二者是近义关系，但选项没有近义关系，考虑拆词看结构，“猛\n药去疴”和“重典治乱”拆词后都能构成方式目的对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：“民生在勤”的意思是人民的生计在于勤劳，“勤则不匮”意思是勤劳就不会缺乏财物，二者拆词之后不存在方式\n目的对应关系，与题干逻辑关系不一致，排除；\nB项：“从善如登”意思是顺随良善像登山一样难，比喻学好向善很难，“从恶如崩”意思是顺随恶行像山崩一样容易，\n比喻学坏很容易，二者拆词之后不存在方式目的对应关系，与题干逻辑关系不一致，排除；\nC项：“静以修身”意思是通过内心安静精力集中来修养身心，“俭以养德”意思是通过俭朴的作风来培养品德，二者拆\n词后都能构成方式目的对应关系，与题干逻辑关系一致，当选；\nD项：“名非天造”的意思是名声不是天生就有的，“必从其实”的意思是必须依据其客观现实，二者拆词之后不存在方\n式目的对应关系，与题干逻辑关系不一致，排除。\n故正确答案为C。\n【考点】\n拆分-逻辑","figs":[],"state":"已标记","notes":[],"domains":["汉语","形式逻辑"],"nature":"综合题","current":false,"links":[{"id":"k-06d4ce551a193870","label":"猛药去疴的含义","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“猛药去疴”意思是通过威力大的药达到去除疾病的目的","why":"理解短语的含义才能识别用药与去除疾病之间的方式和目的关系。","origin":"逐题标记"},{"id":"k-de829a34c1c83d32","label":"重典治乱的含义","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“重典治乱”意思是通过严酷的刑罚达到惩治坏人的目的","why":"理解短语的含义才能识别施用严刑与治理乱象之间的方式和目的关系。","origin":"逐题标记"},{"id":"k-82678b9cd4c22c94","label":"静以修身的含义","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“静以修身”意思是通过内心安静精力集中来修养身心","why":"词义明确了保持内心安静是修养身心的方式。","origin":"逐题标记"},{"id":"k-168b95368790472f","label":"俭以养德的含义","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"“俭以养德”意思是通过俭朴的作风来培养品德","why":"词义明确了践行俭朴是培养品德的方式。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"拆词后都能构成方式目的对应关系","why":"拆分各短语后，逐一比对内部成分的关系及顺序。","origin":"逐题标记"}]},"国考 2023 地市级 行测#93":{"stem":"强光照射：视力损伤","options":["台风过境：渔业停产","网络招聘：业务扩张","原油进口：能源紧缺","风险防范：消防演练"],"answer":"A","analysis":"93. 正确答案：A\n解析：\n第一步：判断题干词语间逻辑关系。\n“强光照射”会导致“视力损伤”，二者为因果对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：“台风过境”会导致“渔业停产”，二者为因果对应关系，与题干逻辑关系一致，当选；\nB项：“业务扩张”会导致“网络招聘”，二者为因果对应关系，但词语顺序与题干相反，与题干逻辑关系不一致，排\n除；\nC项：“能源紧缺”会导致“原油进口”，二者为因果对应关系，但词语顺序与题干相反，与题干逻辑关系不一致，排\n除；\nD项：“风险防范”是“消防演练”的目的，二者为方式与目的对应关系，与题干逻辑关系不一致，排除。\n故正确答案为A。\n【考点】\n因果","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"二者为因果对应关系，但词语顺序与题干相反","why":"匹配词对时同时核对关系类型和因果方向。","origin":"逐题标记"}]},"国考 2023 地市级 行测#94":{"stem":"铜镜：化妆镜","options":["门帘：纱帘","木碗：汤碗","金簪：发簪","瓷瓶：古瓶"],"answer":"B","analysis":"94. 正确答案：B\n解析：\n第一步：判断题干词语间逻辑关系。\n铜镜一般是指由含锡量较高的青铜铸造的镜子，化妆镜一般指专门用于化妆的镜子。有的铜镜是化妆镜，有的铜镜\n不是化妆镜，有的化妆镜是铜镜，有的化妆镜不是铜镜，二者为交叉关系，且前者是根据材质命名，后者是根据功\n能命名。\n第二步：判断选项词语间逻辑关系。\nA项：有的门帘是纱帘，有的门帘不是纱帘，有的纱帘是门帘，有的纱帘不是门帘，二者为交叉关系，但前者是根据\n悬挂的位置命名，与题干逻辑关系不一致，排除；\nB项：有的木碗是汤碗，有的木碗不是汤碗，有的汤碗是木碗，有的汤碗不是木碗，二者为交叉关系，且前者是根据\n材质命名，后者是根据功能命名，与题干逻辑关系一致，当选；\nC项：金簪是发簪的一种，二者为种属关系，与题干逻辑关系不一致，排除；\nD项：古瓶可指古董瓶子或古代的瓶子，有的瓷瓶是古瓶，有的瓷瓶不是古瓶，有的古瓶是瓷瓶，有的古瓶不是瓷\n瓶，二者为交叉关系，但后者是根据历史时代命名，与题干逻辑关系不一致，排除。\n故正确答案为B。\n【考点】\n\n逻辑关系-交叉关系","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"综合题","current":false,"links":[{"id":"k-5db0f370d743d9ec","label":"概念外延的交叉关系","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"有的木碗是汤碗，有的木碗不是汤碗，有的汤碗是木碗，有的汤碗不是木碗，二者为交叉关系","why":"两个概念外延有交集且各自还有独有部分时，构成交叉关系。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"材质命名，后者是根据功能命名，与题干逻辑关系一致","why":"先比对概念外延关系，再核对两个分类维度及其顺序。","origin":"逐题标记"}]},"国考 2023 地市级 行测#95":{"stem":"片剂：散剂：气雾剂","options":["边塞诗：山水诗：抒情诗","口头契约：君子协定：书面协议","泉水：湖水：天然水","头部理疗：腰部理疗：腿部理疗"],"answer":"D","analysis":"95. 正确答案：D\n解析：\n第一步：判断题干词语间逻辑关系。\n片剂是药物与辅料均匀混合后压制而成的片状或异形片状的固体制剂，散剂是指药物或与适宜的辅料经粉碎、均匀\n混合制成的干燥粉末状制剂，气雾剂是指药物和抛射剂共同封装于带有阀门的耐压容器中，使用时借抛射剂气化所\n产生的压力，定量或非定量地将药物以雾状喷出的制剂。三者是根据药物的剂型划分的，为并列关系中的反对关\n系。\n第二步：判断选项词语间逻辑关系。\nA项：边塞诗是以边疆地区军民生活和自然风光为题材的诗，山水诗是描写山水风景的诗，抒情诗是抒发诗人思想感\n情的诗，三者互为交叉关系，与题干逻辑关系不一致，排除；\nB项：口头契约是指不用书面的形式，通过口头达成的协议，书面协议指以书面形式达成的协议，二者均以协议形式\n进行划分，为并列关系，但君子协定是借指彼此之间互相信任的约定，并不是以协议形式进行划分，与另外两词不\n构成并列关系，与题干逻辑关系不一致，排除；\nC项：泉水是指从地下流出来的水，一般是天然水，二者为种属关系，与题干逻辑关系不一致，排除；\nD项：头部理疗、腰部理疗和腿部理疗是根据理疗的身体部位划分的，三者为并列关系中的反对关系，与题干逻辑关\n系一致，当选。\n故正确答案为D。\n【考点】\n反对关系","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"综合题","current":false,"links":[{"id":"k-59bf95524d8ac95d","label":"反对关系：同一上位类下互不相容且未穷尽该类","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"三者为并列关系中的反对关系","why":"解析以理疗部位的分类确认了题干所要求的并列关系。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"question","quote":"片剂：散剂：气雾剂","why":"需核对各组概念的上位类、划分标准及相互关系。","origin":"逐题标记"}]},"国考 2023 地市级 行测#96":{"stem":"春季过敏：花粉：喷嚏","options":["肺炎：咳嗽：支原体","乙型脑炎：病毒：发热","失眠：恐惧：噩梦","秋季腹泻：饮食：脱水"],"answer":"B","analysis":"96. 正确答案：B\n解析：\n第一步：判断题干词语间逻辑关系。\n花粉可能会导致春季过敏，前两词为因果关系；打喷嚏是春季过敏的症状，第一词和第三词为对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：咳嗽是肺炎的症状，前两词为对应关系；支原体感染可能会导致肺炎，第一词和第三词为因果关系，与题干逻\n辑关系不一致，排除；\nB项：病毒感染可能会导致乙型脑炎，前两词为因果关系；发热是乙型脑炎的症状，第一词和第三词为对应关系，与\n题干逻辑关系一致，当选；\nC项：恐惧可能会导致失眠，前两词为因果关系；噩梦不是失眠的症状，与题干逻辑关系不一致，排除；\nD项：秋季腹泻指发生在秋冬季的腹泻病，原因可能是饮食不当或饮食不洁，而非饮食，前两词不是因果关系，与题\n干逻辑关系不一致，排除。\n故正确答案为B。\n【考点】\n因果,对应-其他","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑","科技"],"nature":"综合题","current":false,"links":[{"id":"k-92b992eeaf65c246","label":"花粉可引发春季过敏，喷嚏可为其症状","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"花粉可能会导致春季过敏，前两词为因果关系；打喷嚏是春季过敏的症状","why":"这两项事实确定了题干第二词和第三词的角色。","origin":"逐题标记"},{"id":"k-654b1289fbbb1524","label":"乙型脑炎由病毒感染引起，发热可为其症状","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"answer","quote":"病毒感染可能会导致乙型脑炎，前两词为因果关系；发热是乙型脑炎的症状","why":"病因和症状的对应关系用于核对参考答案的词序。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"前两词为因果关系；打喷嚏是春季过敏的症状，第一词和第三词为对应关系","why":"需同时比对两种关系及其在三词中的位置。","origin":"逐题标记"}]},"国考 2023 地市级 行测#97":{"stem":"标清：高清：超清","options":["亚音速：音速：超音速","厅级：市级：省级","迁怒：愤怒：暴怒","幽静：寂静：安静"],"answer":"A","analysis":"97. 正确答案：A\n解析：\n第一步：判断题干词语间逻辑关系。\n三者均对清晰度进行分类，构成并列关系，且清晰度依次递增。\n第二步：判断选项词语间逻辑关系。\nA项：三者均对速度进行分类，构成并列关系，且速度依次递增，与题干逻辑关系一致，当选；\nB项：厅级是我国的一个行政级别，而市级和省级属于我国的行政区划，三者不构成并列关系，与题干逻辑关系不一\n致，排除；\nC项：迁怒为动词，指把怒气发泄到别人身上，愤怒为形容词，指因极度不满而情绪激动，暴怒指极端愤怒，三者不\n构成并列关系，与题干逻辑关系不一致，排除；\nD项：幽静指清幽寂静，寂静指没有声音、很静，安静指安稳平静、没有声音，三者均是对静的描述，构成并列关\n系，但不是静的程度从低到高的依次递增，与题干逻辑关系不一致，排除。\n故正确答案为A。\n【考点】\n并列-二级辨析","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑","科技"],"nature":"综合题","current":false,"links":[{"id":"k-d68c1cda63db6ac4","label":"亚音速低于音速，超音速高于音速","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"三者均对速度进行分类，构成并列关系，且速度依次递增","why":"三个速度概念的含义决定了其排列方向。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"三者均对清晰度进行分类，构成并列关系，且清晰度依次递增。","why":"需核对各组的并列关系及同一维度上的递增顺序。","origin":"逐题标记"}]},"国考 2023 地市级 行测#98":{"stem":"资产评估：审核通过：股票发售","options":["预定新车：加装内饰：购买车险","修剪草坪：设备检修：园林养护","选购家电：上门安装：维修保养","收看节目：视频连线：观众互动"],"answer":"C","analysis":"98. 正确答案：C\n解析：\n第一步：判断题干词语间逻辑关系。\n先资产评估，再审核通过，最后股票发售，三者为时间先后顺序的对应关系。\n第二步：判断选项词语间逻辑关系。\nA项：先预定新车，但购买车险和加装内饰并无固定的先后顺序，与题干逻辑关系不一致，排除；\nB项：修剪草坪是园林养护的一部分，与题干逻辑关系不一致，排除；\nC项：先选购家电，再上门安装，最后维修保养，三者为时间先后顺序的对应关系，与题干逻辑关系一致，当选；\nD项：视频连线是观众互动的一种方式，与题干逻辑关系不一致，排除。\n故正确答案为C。\n【考点】\n动作/状态先后顺序","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"三者为时间先后顺序的对应关系","why":"需比对各组环节之间是否具有固定的时间顺序。","origin":"逐题标记"}]},"国考 2023 地市级 行测#99":{"stem":"深空探测 对于 （    ） 相当于 （   ） 对于 公益组织","options":["无人采样；慈善捐款","遥感技术；红十字会","宇宙空间；公益事业","火星探测；社会组织"],"answer":"D","analysis":"99. 正确答案：D\n解析：\n逐一代入选项。\nA项：深空探测是指脱离地球引力场，进入太阳系空间和宇宙空间的探测。探测方式上，一般包括飞越、硬着陆（撞\n击）、环绕、软着陆（+巡视）、无人采样返回、载人探测等形式，无人采样是一种深空探测的方式，二者为种属关\n系；公益组织一般为组织慈善捐款的主体，二者为对应关系，前后逻辑关系不一致，排除；\nB项：遥感技术是从人造卫星、飞机或其他飞行器上收集地物目标的电磁辐射信息，判认地球环境和资源的技术，在\n深空探测中会应用到遥感技术，二者为对应关系；红十字会是公益组织，二者为种属关系，前后逻辑关系不一致，\n排除；\nC项：深空探测的对象之一是宇宙空间，二者为工作对象的对应关系；公益组织是致力于社会公益事业和解决各种社\n会性问题的民间志愿性的社会中介组织，公益组织的工作对象之一是公益事业，二者为工作对象的对应关系，但前\n后顺序相反，前后逻辑关系不一致，排除；\nD项：火星探测是一种深空探测，二者为种属关系；公益组织是一种社会组织，二者为种属关系，前后逻辑关系一\n致，当选。\n故正确答案为D。\n【考点】\n种属关系","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑","科技","社会治理"],"nature":"综合题","current":false,"links":[{"id":"k-2826045170745a5c","label":"火星探测属于深空探测","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"火星探测是一种深空探测","why":"该分类确定左侧从上位概念到下位概念的方向。","origin":"逐题标记"},{"id":"k-4e09782e054e8cc0","label":"公益组织属于社会组织","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"公益组织是一种社会组织","why":"该分类确定右侧从上位概念到下位概念的方向。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"answer","quote":"逐一代入选项。","why":"代入后需同时核对两侧的关系类型与方向。","origin":"逐题标记"}]},"国考 2023 地市级 行测#100":{"stem":"缄口不言 对于 （   ） 相当于 （   ） 对于 虚怀若谷","options":["三缄其口；大智若愚","畅所欲言；放荡不羁","守口如瓶；礼贤下士","口若悬河；矜功伐善"],"answer":"D","analysis":"100. 正确答案：D\n解析：\n逐一代入选项。\nA项：缄口不言意思是封住嘴巴，不开口说话，形容畏惧权势，言语谨慎，怕招惹是非，应当说的而不敢说或不愿意\n说。三缄其口形容说话极其谨慎、不轻易开口，二者为近义关系；大智若愚指有智慧有才能的人，看起来好像很愚\n笨，也比喻有智慧的人极有涵养，不露锋芒。虚怀若谷指胸怀像山谷一样深广，形容十分谦虚，能容纳别人的意\n见，二者不是近义关系，前后逻辑关系不一致，排除；\nB项：缄口不言意思是封住嘴巴，不开口说话，形容畏惧权势，言语谨慎，怕招惹是非，应当说的而不敢说或不愿意\n说。畅所欲言指尽情地说出想说的话，没有约束地把心里话吐露出来，二者为反义关系；放荡不羁意思是放纵任\n性，不加检点，不受约束。虚怀若谷指胸怀像山谷一样深广，形容十分谦虚，能容纳别人的意见，二者不是反义关\n系，前后逻辑关系不一致，排除；\nC项：缄口不言意思是封住嘴巴，不开口说话，形容畏惧权势，言语谨慎，怕招惹是非，应当说的而不敢说或不愿意\n说。守口如瓶意思是闭口不谈，像瓶口塞紧了一般，形容说话谨慎，严守秘密，二者为近义关系；礼贤下士形容重\n视人才。虚怀若谷指胸怀像山谷一样深广，形容十分谦虚，能容纳别人的意见，二者不是近义关系，前后逻辑关系\n不一致，排除；\nD项：缄口不言意思是封住嘴巴，不开口说话，形容畏惧权势，言语谨慎，怕招惹是非，应当说的而不敢说或不愿意\n说。口若悬河意为说话滔滔不绝，像河水倾泄一样，形容能说善辩，话语不断，二者为反义关系；矜功伐善意思是\n夸耀自己的功劳和才能，形容极不虚心。虚怀若谷指胸怀像山谷一样深广，形容十分谦虚，能容纳别人的意见，二\n者为反义关系，前后逻辑关系一致，当选。\n故正确答案为D。\n【考点】\n\n语义关系-反义关系","figs":[],"state":"已标记","notes":[],"domains":["汉语","形式逻辑"],"nature":"综合题","current":false,"links":[{"id":"k-72a705667e55a451","label":"缄口不言与口若悬河的词义辨析","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"口若悬河意为说话滔滔不绝","why":"缄口不言指闭口不说，口若悬河指说话滔滔不绝，两者在言语表现上相反。","origin":"逐题标记"},{"id":"k-d6e6aca0d5edb600","label":"矜功伐善与虚怀若谷的词义辨析","catalog_id":null,"type":"概念与词义","role":"直接考查","field":"answer","quote":"夸耀自己的功劳和才能，形容极不虚心。","why":"矜功伐善指夸耀功劳和才能，虚怀若谷指谦虚且能容纳他人意见，两者在谦虚程度上相反。","origin":"逐题标记"},{"id":"s-d45531f0ca63ae30","label":"比对概念或对象之间的关系","catalog_id":"L05","type":null,"role":"直接考查","field":"question","quote":"缄口不言 对于 （   ） 相当于 （   ） 对于 虚怀若谷","why":"需把候选成语成对代入，并比较两侧是否具有相同的语义关系。","origin":"逐题标记"}]},"国考 2023 地市级 行测#101":{"stem":"深度学习是一系列复杂的算法，使计算机能够识别数据中的模式并作出预测。研究人员利用深度学习技术训练\nAI系统自动读取视网膜扫描数据，并识别那些在接下来的一年中患心脏病风险较高的人。研究人员认为该项技术有\n可能彻底改变传统的心脏病筛查方式。\n上述论证的成立须补充以下哪项作为前提？","options":["视网膜扫描数据反映的微小血管变化是预测心脏疾病较为灵敏的指标","心脏病筛查需要进行复杂且昂贵的超声心动图或心脏磁共振成像检查","视网膜扫描相对便宜，并且在许多配镜服务中被使用","AI系统是解开自然界中存在的复杂模式的绝佳工具"],"answer":"A","analysis":"101. 正确答案：A\n解析：\n第一步：找出论点和论据。\n论点：深度学习技术有可能彻底改变传统的心脏病筛查方式。\n论据：研究人员利用深度学习技术训练AI系统自动读取视网膜扫描数据，并识别那些在接下来的一年中患心脏病风\n险较高的人。\n本题提问为“须补充以下哪项作为前提”，优先考虑搭桥和必要条件。论点讨论的是深度学习技术有可能彻底改变传统\n的心脏病筛查方式，而论据讨论的是利用深度学习技术可以训练AI系统自动读取视网膜扫描数据，二者话题不一\n致，优先考虑搭桥，即建立“视网膜扫描数据”和“心脏病筛查”的联系。\n第二步：逐一分析选项。\nA项：该项说的是视网膜扫描数据反映的微小血管变化可以用来预测心脏疾病，将“视网膜扫描数据”和“心脏病筛\n查”建立了联系，属于搭桥项，可以加强，当选；\nB项：该项说的是心脏病筛查需要进行复杂且昂贵的超声心动图或心脏磁共振成像检查，而论点讨论的是深度学习技\n术有可能彻底改变传统的心脏病筛查方式，话题不一致，无法加强，排除；\nC项：该项说的是视网膜扫描相对便宜且在配镜中使用很多，而论点讨论的是深度学习技术有可能彻底改变传统的心\n脏病筛查方式，话题不一致，无法加强，排除；\nD项：该项说的是AI系统是解开自然界中存在的复杂模式的绝佳工具，而论点讨论的是深度学习技术有可能彻底改变\n传统的心脏病筛查方式，话题不一致，无法加强，排除。\n故正确答案为A。\n【考点】\n搭桥","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-bd23484a6c3aa41a","label":"识别论据到结论的隐含前提","catalog_id":"L07","type":null,"role":"直接考查","field":"question","quote":"上述论证的成立须补充以下哪项作为前提？","why":"需补足视网膜扫描数据与心脏病筛查之间的联系。","origin":"逐题标记"}]},"国考 2023 地市级 行测#102":{"stem":"调查显示，某地区第二产业从业人员与五年前相比减少了10.4%，对于第二产业从业人员减少的原因，一种观\n点认为，产业优化升级是第二产业从业人员减少的原因，第二产业在实现产业规模快速扩大的同时，不断加快技术\n改造，实现“机器换工”，客观上降低了工业企业的用工需求。另一种观点则认为，这与第二产业的优化升级无关，第\n三产业的蓬勃发展发挥了就业“蓄水池”的功能，吸纳了大量第二产业从业人员。\n以下哪项如果为真，最能削弱第二种观点？","options":["第二产业优化升级拉动了第三产业蓬勃发展","该地区第三产业的整体规模比第二产业要小","第三产业的发展得益于持续优化的营商环境","第二产业和第三产业都对吸纳就业作出贡献"],"answer":"A","analysis":"102. 正确答案：A\n解析：\n第一步：找出论点和论据。\n论点：第二产业从业人员减少的原因，与第二产业的优化升级无关，第三产业的蓬勃发展发挥了就业“蓄水池”的功\n能，吸纳了大量第二产业从业人员。\n论据：无。\n本题只有论点没有论据，削弱优先考虑直接否定论点。\n第二步：逐一分析选项。\nA项：该项说的是第二产业优化升级拉动了第三产业蓬勃发展，进而导致第二产业从业人员减少，也就是说，导致第\n二产业从业人员减少的根本原因还是第二产业优化升级，直接削弱了论点，可以削弱，当选；\nB项：该项说的是该地区第三产业的整体规模比第二产业要小，与题干讨论的第二产业从业人员减少的原因无关，话\n题不一致，无法削弱，排除；\nC项：该项说的是第三产业发展的原因，与题干讨论的第二产业从业人员减少的原因无关，话题不一致，无法削弱，\n排除；\nD项：该项说的是第二产业和第三产业都对吸纳就业作出贡献，与题干讨论的第二产业从业人员减少的原因无关，话\n题不一致，无法削弱，排除。\n故正确答案为A。\n【考点】\n削弱论点","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-ae670e69128d8e55","label":"用间接因果链反驳无关断言","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"第二产业优化升级拉动了第三产业蓬勃发展，进而导致第二产业从业人员减少","why":"需识别能把被排除的原因接回原有因果链的条件。","origin":"逐题标记","originalId":"s-b6dc582e9d8ebca4"}]},"国考 2023 地市级 行测#103":{"stem":"太平洋中部的海底，散落着大量的矿石，这些矿石名为“多金属结核”，是镍、钴、锰等稀有金属的混合物。支持\n深海开采的人认为，多金属结核可以提供开发清洁能源所需的矿物，同时海洋每年吸收约四分之一的全球碳排放\n量，开采结核的过程本身对海洋的碳吸收能力影响不大，反对者则认为海洋本就已经受到过度捕捞、工业污染和塑\n料垃圾等人类活动的威胁，在这种情况下，深海开采将加剧人类活动对海洋产生不利的影响。\n以下哪项如果为真，最能支持反对者的观点？","options":["目前人类对深海生物及环境的研究还不够深入，还不足以支持对深海进行大规模开采矿物的活动","即使海洋开采活动能够为日益增加的能源需求提供更多的金属，人类对金属的需求仍然得不到满足，只会与日俱\n增","地球上的海洋彼此相连，并共享一个环绕地球的洋流系统，开采活动的评估应该进行全局考虑","深海开采过程中释放的泥浆会威胁矿区之上深海中层水域的生态环境，还会产生很大的噪音向上层水域扩散"],"answer":"D","analysis":"103. 正确答案：D\n解析：\n第一步：找出论点和论据。\n论点：海洋本就已经受到过度捕捞、工业污染和塑料垃圾等人类活动的威胁，在这种情况下，深海开采将加剧人类\n活动对海洋产生不利的影响。\n论据：无。\n本题只有论点，没有论据，加强优先考虑补充论据，即解释原因或举例。\n第二步：逐一分析选项。\n\nA项：该项讨论的是已有研究还不够深入，无法支持在深海大规模开采矿物，但不清楚深海开采后会不会对海洋环境\n产生不利影响，为不明确项，不能加强，排除；\nB项：该项讨论的是深海开采的金属能否满足人类的需要，和论点讨论的深海开采对海洋环境的影响无关，话题不一\n致，不能加强，排除；\nC项：该项讨论的是地球上的海洋彼此相连并相互影响，开采活动的评估应该进行全局考虑，但是没有明确说明是否\n开采深海，以及深海开采后会不会对海洋环境产生不利影响，为不明确项，不能加强，排除；\nD项：该项指出深海开采中释放的泥浆影响中层水域，噪音污染向上层水域扩散，补充说明深海开采会影响海洋水\n域、造成噪音污染等不利影响，解释原因，可以加强，当选。\n故正确答案为D。\n【考点】\n补充论据","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-2ee7513507dfe397","label":"用具体作用机制补充论据","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"深海开采中释放的泥浆影响中层水域，噪音污染向上层水域扩散","why":"识别能说明某项活动如何造成所述后果的具体证据。","origin":"逐题标记","originalId":"s-f15036ccc1fa459c"}]},"国考 2023 地市级 行测#104":{"stem":"传统污水处理，或通过重力沉降、混凝澄清、浮力浮上、离心力分离、磁力分离等物理方法对不溶态污染物进\n行分离，或通过酸碱中和法、化学沉淀法、氧化还原法等化学方法让污染物发生转化，而新兴的微生物治理技术则\n是通过水体微生物来净化污水。有专家认为，与传统手段相比，微生物治理技术是一种处理污水的更佳手段。\n\n以下哪项如果为真，不能支持上述观点？","options":["近年来，微生物技术的科研投入持续扩大，相关技术成果在土壤改良等领域已经得到了有效转化","物理方法进行污水治理的处理厂，通常占地面积大，基建费、运行费高，能耗大，易出现污泥膨胀现象","化学方法进行污水治理运行成本高，需消耗大量的化学试剂，易产生二次污染","微生物技术污水治理的能耗低，效率高，剩余污泥量少，操作管理方便"],"answer":"A","analysis":"104. 正确答案：A\n解析：\n第一步：找出论点和论据。\n论点：与传统手段相比，微生物治理技术是一种处理污水的更佳手段。\n论据：传统污水处理，或通过重力沉降、混凝澄清、浮力浮上、离心力分离、磁力分离等物理方法对不溶态污染物\n进行分离，或通过酸碱中和法、化学沉淀法、氧化还原法等化学方法让污染物发生转化，而新兴的微生物治理技术\n则是通过水体微生物来净化污水。\n本题论点和论据话题一致，都是在对传统手段和微生物治理技术进行比较，加强优先考虑补充论据，本题为选非\n题，将可以加强的选项排除即可。\n第二步：逐一分析选项。\nA项：该项指出近年来微生物技术的科研投入持续扩大，相关技术成果在土壤改良等领域已经得到了有效转化，仅说\n明微生物技术对土壤改良的作用，没有提及对污水处理的作用，为无关项，无法加强，当选；\nB项：该项指出物理方法进行污水治理的处理厂，通常占地面积大，基建费、运行费高，能耗大，易出现污泥膨胀现\n象，补充说明传统手段具有成本高、能耗高、污染环境等缺点，补充论据，可以加强，排除；\nC项：该项指出化学方法进行污水治理运行成本高，需消耗大量的化学试剂，易产生二次污染，补充说明传统手段存\n在成本高、污染环境等缺点，补充论据，可以加强，排除；\nD项：该项指出微生物技术污水治理的能耗低，效率高，剩余污泥量少，操作管理方便，补充说明微生物技术治理污\n水有优势，补充论据，可以加强，排除。\n本题为选非题，故正确答案为A。\n【考点】\n加强选非题","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-e207f62725dca283","label":"识别与比较结论无关的证据","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"微生物技术对土壤改良的作用，没有提及对污水处理的作用","why":"依据结论限定的应用场景，判断其他领域的成果能否支持该比较。","origin":"逐题标记","originalId":"s-a8da5167016f7d26"}]},"国考 2023 地市级 行测#105":{"stem":"近来，国际大宗商品市场中，原油和天然气价格达到近十年以来的高位，锌矿价格也上涨了7%左右，有分析人\n士认为，大宗商品市场将进入“超级周期”（大宗商品价格高于长期平均价格的时期）。从宏观层面看，大宗商品进\n入“超级周期”是全球经济出现新的增长动力的结果。历史上大宗商品进入“超级周期”往往会带动全球经济复苏，这也\n预示着当下全球经济正在复苏。\n以下哪项如果为真，最能削弱上述论证？","options":["地缘政治的风险加剧了大宗商品供应的紧张局势，引发本轮大宗商品价格上涨","飙升的天然气价格推高了化肥的主要成分——氨的价格，进而推高全球粮食价格","全球经济将更注重环保，碳中和与碳达峰将改变能源产业格局，进而影响金属和原油产业的发展远景","全球主要经济体正在加紧出台强有力的救市计划，以寻求本国新的经济增长动力"],"answer":"A","analysis":"105. 正确答案：A\n解析：\n第一步：找出论点和论据。\n论点：大宗商品市场将进入“超级周期”（大宗商品价格高于长期平均价格的时期）。从宏观层面看，大宗商品进\n入“超级周期”是全球经济出现新的增长动力的结果。历史上大宗商品进入“超级周期”往往会带动全球经济复苏，这也\n预示着当下全球经济正在复苏。\n论据：无。\n本题的论点的逻辑是“全球经济出现新的增长动力”导致大宗商品市场将进入“超级周期”，进而预示当下全球经济正在\n复苏，本题只有论点，没有论据，削弱优先考虑削弱论点。\n第二步：逐一分析选项。\nA项：论点的逻辑是“全球经济新的增长动力导致大宗商品价格上涨”，该项给出了导致“大宗商品价格上涨”的另一个\n原因，削弱论点，可以削弱，当选；\nB项：该项说的是天然气价格推高了氨的价格，进而推高全球粮食价格，只说明了部分商品之间的价格关联度，而论\n点讨论的是大宗商品价格高于平均的原因以及产生的结果，话题不一致，无法削弱，排除；\nC项：该项说的是全球经济将更注重环保，碳中和与碳达峰将改变能源产业格局，而论点讨论的是大宗商品价格高于\n平均的原因以及产生的结果，话题不一致，无法削弱，排除；\nD项：该项说的是全球主要经济体为寻求本国新的经济增长动力而出台救市计划，而论点讨论的是大宗商品价格高于\n平均的原因以及产生的结果，话题不一致，无法削弱，排除。\n\n故正确答案为A。\n【考点】\n削弱论点","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-ae670e69128d8e55","label":"用其他解释削弱因果推断","catalog_id":"264ebd474a4792dc","type":null,"role":"直接考查","field":"question","quote":"地缘政治的风险加剧了大宗商品供应的紧张局势，引发本轮大宗商品价格上涨","why":"识别同一价格现象的替代成因，判断它如何削弱由涨价推断经济复苏的论证。","origin":"逐题标记"}]},"国考 2023 地市级 行测#106":{"stem":"关于6天中的人选，以下哪项安排符合上述条件？","options":["财务、人事、后勤、法务、财务、人事","销售、财务、法务、人事、财务、销售","人事、财务、法务、研发、法务、后勤","法务、销售、人事、后勤、财务、销售"],"answer":"B","analysis":"106. 正确答案：B\n解析：\n第一步：分析题干条件。\n6天假期每天需安排一人值班，6个部门各推荐2人，从12人中选择6人，每人值班一天。安排要求如下：\n（1）法务部    第二、四天；\n（2）后勤值班    后勤安排在法务前一天；\n（3）研发值班    研发安排在后勤前一天。\n第二步：根据题干条件进行推理。\n本题题干信息确定，选项信息充分，优先考虑排除法。\n根据条件（1）“法务部    第二、四天”，排除A项。\n根据条件（2）“后勤值班    后勤安排在法务前一天”，排除C、D两项。\n经验证，B项满足题干所有条件，当选。\n故正确答案为B。\n【考点】\n一拖五,排除法（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"本题题干信息确定，选项信息充分，优先考虑排除法。","why":"将完整排班逐项与约束核对，排除违反任一条件的方案。","origin":"逐题标记"}]},"国考 2023 地市级 行测#107":{"stem":"后勤部门的人可以安排在哪几天值班？","options":["只有第二天、第四天、第五天","只有第一天、第三天、第五天","只有第二天、第六天","只有第一天、第三天"],"answer":"A","analysis":"107. 正确答案：A\n解析：\n第一步：分析题干条件。\n6天假期每天需安排一人值班，6个部门各推荐2人，从12人中选择6人，每人值班一天。安排要求如下：\n（1）法务部    第二、四天；\n（2）后勤值班    后勤安排在法务前一天；\n（3）研发值班    研发安排在后勤前一天。\n第二步：根据题干条件进行推理。\n提问为“可以”，优先考虑代入选项。因为选项表述均为“只有”，说明是要列举后勤部门值班的所有可能情况，此时可\n以从选项中只出现一次的情况入手，即A项中的“后勤部门的人是否可以安排在第四天”，如果可以，即A项当选，如\n果不可以，即排除A项。\n如果后勤部门安排在第四天，根据条件（2）可知，法务部门安排在第五天，题干所有条件均可满足，即后勤部门可\n以安排在第四天，排除B、C、D三项。\n故正确答案为A。\n【考点】\n一拖五,代入法（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"M1","quote":"若安排后勤部门的人值班，则只能安排在法务部门的人值班的前一天","why":"由后勤值班日确定次日的部门，再检验次日是否允许安排法务。","origin":"逐题标记"}]},"国考 2023 地市级 行测#108":{"stem":"如果安排后勤部门的两人值班，则以下哪项一定是错误的？","options":["第一天安排研发部门的人值班","第六天安排人事部门的人值班","第三天安排财务部门的人值班","第五天安排法务部门的人值班"],"answer":"C","analysis":"108. 正确答案：C\n解析：\n第一步：分析题干条件。\n6天假期每天需安排一人值班，6个部门各推荐2人，从12人中选择6人，每人值班一天。安排要求如下：\n（1）法务部    第二、四天；\n（2）后勤值班    后勤安排在法务前一天；\n（3）研发值班    研发安排在后勤前一天；\n（4）后勤有两人值班。\n第二步：根据题干条件进行推理。\n条件（4）表明后勤有两人值班，结合条件（2）可知，法务也应有两人值班，且后勤紧挨在法务值班的前一天，据\n此可知，法务不能安排在第一天。\n再结合条件（1）可知，法务的两人只能安排在第三天、第五天、第六天这三天中的两天。由于法务两人值班的前一\n天均应是后勤的人在值班，所以法务的两人不能同时安排在第五天和第六天，因此法务一定有一人是安排在第三天\n的，则C项第三天安排财务部门的人值班是错误的。\n本题为选非题，故正确答案为C。\n【考点】\n\n一拖五,从确定信息开始推或其他（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"法务的两人不能同时安排在第五天和第六天","why":"为两名后勤人员分别匹配次日的法务人员，排除日期重叠的组合并确定必占日期。","origin":"逐题标记"}]},"国考 2023 地市级 行测#109":{"stem":"如果在第三天、第五天分别安排两个财务部门的人值班，则第一天、第六天可安排的值班人员可能分别来自：","options":["后勤部门和法务部门","法务部门和销售部门","财务部门和销售部门","研发部门和人事部门"],"answer":"B","analysis":"109. 正确答案：B\n解析：\n第一步：分析题干条件。\n6天假期每天需安排一人值班，6个部门各推荐2人，从12人中选择6人，每人值班一天。安排要求如下：\n（1）法务部    第二、四天；\n（2）后勤值班       后勤安排在法务前一天；\n（3）研发值班       研发安排在后勤前一天；\n（4）在第三天、第五天分别安排两个财务部门的人值班。\n第二步：根据题干条件进行推理。\n提问方式为“可能”，优先使用代入法。\n代入A项：如果第一天、第六天安排的值班人员分别来自后勤部门和法务部门，根据条件（2）后勤值班     后勤安排\n在法务前一天，可知第二天为法务，不满足条件（1），排除；\n代入B项：如果第一天、第六天安排的值班人员分别来自法务部门和销售部门，根据条件（4）在第三天、第五天分\n别安排财务，根据条件（2）后勤值班      后勤安排在法务前一天，可知第二天和第四天不能安排后勤，根据条件\n（1），可知第二天和第四天不能安排法务，根据条件（3）研发值班     研发安排在后勤前一天，可知第二天和第四\n天不能安排研发，所以第二天和第四天可以安排人事或者销售，可进行如下安排，满足题干条件，当选；\n\n\n\n\n代入C项：如果第一天、第六天安排的值班人员分别来自财务部门和销售部门，此时第一天、第三天和第五天安排的\n值班人员均来自财务部门，不符合题干条件“6个部门各推荐2人”，不满足题干条件，排除；\n代入D项：如果第一天、第六天安排的值班人员分别来自研发部门和人事部门，根据条件（3）研发值班     研发安排\n在后勤前一天，可知第二天的值班人员来自后勤部门，根据条件（2）后勤值班      后勤安排在法务前一天，可知第三\n天的值班人员来自法务部门，此时不符合条件（4）“第三天安排财务部门的人值班”，不满足题干条件，排除。\n故正确答案为B。\n【考点】\n一拖五,代入法（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"技能题","current":false,"links":[{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"提问方式为“可能”，优先使用代入法。","why":"把首尾两天的部门代入固定排班，结合相邻顺序和人数上限检验其余日期能否补全。","origin":"逐题标记"}]},"国考 2023 地市级 行测#110":{"stem":"如果没有安排财务和后勤部门的人值班，则以下哪项一定是正确的？","options":["第四天安排销售部门的人值班","第五天安排法务部门的人值班","第二天安排销售部门或者人事部门的人值班","第三天安排法务部门或者人事部门的人值班"],"answer":"C","analysis":"110. 正确答案：C\n解析：\n第一步：分析题干条件。\n6天假期每天需安排一人值班，6个部门各推荐2人，从12人中选择6人，每人值班一天。安排要求如下：\n（1）法务部    第二、四天；\n（2）后勤值班       后勤安排在法务前一天；\n（3）研发值班       研发安排在后勤前一天；\n（4）没有安排财务和后勤部门的人值班。\n第二步：根据题干条件进行推理。\n根据条件（4）没有安排后勤部门的人值班，可知研发部门不可能安排在后勤部门的前一天，结合条件（3）可知，\n没有安排研发部门的人值班。此时已知没有安排研发、财务和后勤这3个部门的人值班，结合题干开头给出的信息可\n知，值班人员只能从剩下的人事、法务、销售这3个部门中选择。再结合条件（1）可知，第二天不能安排法务部门\n的人值班，所以第二天只能安排销售部门或者人事部门的人值班。\n故正确答案为C。\n【考点】\n一拖五,从确定信息开始推或其他（材料）","figs":[],"state":"已标记","notes":[],"domains":["形式逻辑"],"nature":"综合题","current":false,"links":[{"id":"k-484bd793f96d3d75","label":"充分条件假言命题的否后推否前","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"没有安排后勤部门的人值班，可知研发部门不可能安排在后勤部门的前一天","why":"若前件成立必然后件成立，则否定后件可以推出前件不成立。","origin":"逐题标记"},{"id":"s-aa16640dd943508a","label":"按多条约束确定对应或次序","catalog_id":"L02","type":null,"role":"直接考查","field":"answer","quote":"第二天不能安排法务部门","why":"将附加条件缩小后的部门范围与指定日期的禁排要求相交，确定该日可排的部门。","origin":"逐题标记"}]},"国考 2023 地市级 行测#111":{"stem":"2021年四季度，Z省有几个市的中心城市道路机动车依法礼让率高于上季度水平？","options":["5","6","7","8"],"answer":"C","analysis":"111. 正确答案：C\n解析：\n\n定位表格材料可得：2021年四季度Z省各市中心城市道路机动车依法礼让率高于上季度水平的有A市（98.8%＞\n98.0%）、B市（98.8%＞96.0%）、D市（99.6%＞97.3%）、E市（98.3%＞96.5%）、F市（98.2%＞96.0%）、\nG市（100.0%＞94.8%）、H市（99.3%＞98.2%），共7个。\n故正确答案为C。\n【考点】\n统计表,直接找数","figs":["64bc3a15d27a04e94940.pdf#21"],"state":"已标记","notes":[],"domains":["统计"],"nature":"技能题","current":false,"links":[{"id":"s-a28704d6c4e47be4","label":"逐对象比较两期指标并计数","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"有几个市的中心城市道路机动车依法礼让率高于上季度水平","why":"按城市配对两季数值，逐一比较后计数。","origin":"逐题标记"}]},"国考 2023 地市级 行测#112":{"stem":"2021年三季度Z省中心城市道路非机动车遵守交通信号灯率最低的城市，其四季度中心城市道路非机动车遵守\n交通信号灯率比上季度增长了：","options":["4~6个百分点之间","超过6个百分点","不到2个百分点","2~4个百分点之间"],"answer":"B","analysis":"112. 正确答案：B\n解析：\n定位表格材料可得：2021年三季度Z省中心城市道路非机动车遵守交通信号灯率最低的城市是G市（90.9%）。2021\n年四季度以及三季度G市中心城市道路非机动车遵守交通信号灯率分别为98.2%、90.9%。则2021年四季度G市中心\n城市道路非机动车遵守交通信号灯率比上季度增长了98.2%-90.9%=7.3%，即增长了7.3个百分点，在B项范围内。\n故正确答案为B。\n【考点】\n统计表,简单加减计算","figs":["64bc3a15d27a04e94940.pdf#21"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-80728c8245361582","label":"百分点表示两个百分率直接相减的差","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"98.2%-90.9%=7.3%，即增长了7.3个百分点","why":"选项以百分点划分区间，口径为两期百分率直接相减。","origin":"逐题标记"},{"id":"s-base","label":"按基期极值筛选对象","catalog_id":null,"type":null,"role":"解题依据","field":"answer","quote":"非机动车遵守交通信号灯率最低的城市是G市","why":"先用第三季度同一指标的最小值锁定后续取数对象。","origin":"逐题标记","originalId":"s-b32646ba8186c477"},{"id":"s-22e0d443f4e8833e","label":"比较比重与百分点差","catalog_id":"D06","type":null,"role":"直接考查","field":"answer","quote":"即增长了7.3个百分点，在B项范围内","why":"求出同一城市两季的百分点差，再匹配选项区间。","origin":"逐题标记"}]},"国考 2023 地市级 行测#113":{"stem":"如用求各市算术平均值的方式计算全省数值，则2021年四季度Z省中心城市道路汽车前排驾乘人员安全带使用\n率比上季度：","options":["下降了不到2个百分点","下降了2个百分点以上","提升了不到2个百分点","提升了2个百分点以上"],"answer":"D","analysis":"113. 正确答案：D\n解析：\n根据题干“如用求各市算术平均值的方式计算全省数值，则2021年四季度······比上季度”，结合选项为下降/提升+百分\n点，可判定本题为平均数的增长量问题。定位表格材料可得：2021年四季度Z省各市中心城市道路汽车前排驾乘人员\n安全带使用率分别为99.2%、98.8%、98.0%、98.6%、99.8%、99.1%、98.2%、99.4%，2021年三季度分别为\n99.6%、96.5%、96.0%、97.4%、92.5%、96.1%、91.9%、98.8%。则所求\n\n\n\n                                                      ，即约比上季度提升了2个\n\n百分点以上。\n故正确答案为D。\n【考点】\n统计表,平均数的增长量","figs":["64bc3a15d27a04e94940.pdf#21"],"state":"已标记","notes":[],"domains":["统计","数学"],"nature":"综合题","current":false,"links":[{"id":"k-4fdce583a106b393","label":"算术平均数等于各数值之和除以数值个数","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"用求各市算术平均值的方式计算全省数值","why":"题干规定各市等权，每季将各市使用率求和后除以城市数。","origin":"逐题标记"},{"id":"k-80728c8245361582","label":"百分点表示两个百分率直接相减的差","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"D.提升了2个百分点以上","why":"选项采用百分点口径，需用第四季度平均率减第三季度平均率。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"answer","quote":"可判定本题为平均数的增长量问题","why":"对两季各市数据分别求均值，用均值之差判断方向和幅度。","origin":"逐题标记"}]},"国考 2023 地市级 行测#114":{"stem":"如单纯从统计数据判断，则2021年四季度B市在提升中心城市道路交通守法率方面，工作相比三季度最有成效\n的是：","options":["机动车依法礼让","行人、非机动车遵守交通信号灯","摩托车驾乘人员佩戴安全头盔","汽车前排驾乘人员使用安全带"],"answer":"A","analysis":"114. 正确答案：A\n解析：\n定位表格材料可得2021年三季度、四季度B市在选项四个方面的城市道路交通守法率，具体情况为：\n\n\n\n\n对比可得，B市2021年三季度的机动车依法礼让率最低（96.0%），而四季度最高（98.8%），差值最大，即工作相\n比三季度最有成效。\n故正确答案为A。\n【考点】\n统计表,简单加减计算","figs":["64bc3a15d27a04e94940.pdf#21"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-80728c8245361582","label":"百分点表示两个百分率直接相减的差","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"而四季度最高（98.8%），差值最大","why":"参考解析以第四季度守法率减第三季度守法率衡量提升幅度。","origin":"逐题标记"},{"id":"s-22e0d443f4e8833e","label":"比较比重与百分点差","catalog_id":"D06","type":null,"role":"直接考查","field":"answer","quote":"差值最大","why":"比较同一城市各指标的两季度百分点差，找出最大值。","origin":"逐题标记"}]},"国考 2023 地市级 行测#115":{"stem":"以下条形图反映了2021年四季度Z省哪个城市中心城市道路交通守法率五项指标之间的大小关系？","options":["E市","F市","G市","H市"],"answer":"B","analysis":"115. 正确答案：B\n解析：\n定位表格材料可得2021年四季度E市、F市、G市、H市中心城市道路交通五项指标的守法率。逐一分析选项：\n\nA项：2021年四季度E市中心城市道路交通机动车依法礼让率、行人遵守交通信号灯率、非机动车遵守交通信号灯\n率、摩托车安全头盔佩戴率、汽车前排驾乘人员安全带使用率五项指标的守法率依次为98.3%、99.2%、99.3%、\n98.9%、99.8%。即排名第2的指标为非机动车遵守交通信号灯率（99.3%），不符合条形图五项指标之间的大小关\n系，排除；\nB项：2021年四季度F市中心城市道路交通机动车依法礼让率、行人遵守交通信号灯率、非机动车遵守交通信号灯\n率、摩托车安全头盔佩戴率、汽车前排驾乘人员安全带使用率五项指标的守法率依次为98.2%、99.0%、98.8%、\n98.8%、99.1%。即符合条形图五项指标之间的大小关系，正确；\nC项：2021年四季度G市中心城市道路交通机动车依法礼让率、行人遵守交通信号灯率、非机动车遵守交通信号灯\n率、摩托车安全头盔佩戴率、汽车前排驾乘人员安全带使用率五项指标的守法率依次为100.0%、98.2%、98.2%、\n95.6%、98.2%。即排名第1的指标为机动车依法礼让率（100.0%），不符合条形图五项指标之间的大小关系，排\n除；\nD项：2021年四季度H市中心城市道路交通机动车依法礼让率、行人遵守交通信号灯率、非机动车遵守交通信号灯\n率、摩托车安全头盔佩戴率、汽车前排驾乘人员安全带使用率五项指标的守法率依次为99.3%、99.3%、99.4%、\n99.0%、99.4%。即并列排名第1的指标为非机动车遵守交通信号灯率和汽车前排驾乘人员安全带使用率\n（99.4%），不符合条形图五项指标之间的大小关系，排除。\n故正确答案为B。\n【考点】\n统计表,直接找数","figs":["64bc3a15d27a04e94940.pdf#21"],"state":"待核","notes":["所附页图未呈现本题条形图，图表大小关系的关联依据题干与参考解析。"],"domains":["统计"],"nature":"技能题","current":false,"links":[{"id":"s-6cfd92b2f027f1a1","label":"按排序和并列关系匹配条形图与表格数据","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"道路交通守法率五项指标之间的大小关系","why":"将柱长反映的大小和相等关系与同一城市五项表值逐项核对。","origin":"逐题标记","originalId":"s-d37a6ce3ac9ca326"}]},"国考 2023 地市级 行测#116":{"stem":"2020～2021年，中国超算服务市场累计规模约为多少亿元？","options":["328","354","371","396"],"answer":"B","analysis":"116. 正确答案：B\n解析：\n定位统计表可得2020年中国尖端超算、通用超算、业务超算和人工智能超算服务市场规模分别为28.3亿元、37.8亿\n元、64.4亿元、27.7亿元；2021年这四类超算服务市场规模分别为31.4亿元、40.3亿元、85.6亿元、38.3亿元。则\n2020～2021年，中国超算服务市场累计规模=28.3+37.8+64.4+27.7+31.4+40.3+85.6+38.3   亿元。\n故正确答案为B。\n【考点】\n综合资料,简单加减计算","figs":["64bc3a15d27a04e94940.pdf#23"],"state":"已标记","notes":[],"domains":["统计"],"nature":"技能题","current":false,"links":[{"id":"s-9d6535a8dad068a9","label":"跨年份和类别汇总表格数据","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"2020～2021年，中国超算服务市场累计规模约为多少亿元？","why":"需定位两年各类别的数据并加总。","origin":"逐题标记","originalId":"s-7216abd1b45a29d5"}]},"国考 2023 地市级 行测#117":{"stem":"2019年，中国第三方超算服务市场规模约占同年超算服务总体市场规模的：","options":["15%","18%","21%","24%"],"answer":"A","analysis":"117. 正确答案：A\n解析：\n根据题干“2019年······占同年······”，结合材料时间为2019年，可判定本题为现期比重问题。定位统计表可得2019年\n中国尖端超算、通用超算、业务超算和人工智能超算的市场规模；定位统计图可得2019年中国第三方独立超算服务\n商和互联网超算服务商的市场规模。则所求比重\n\n                ，与A项最接近。\n\n故正确答案为A。\n【考点】\n综合资料,现期比重","figs":["64bc3a15d27a04e94940.pdf#23"],"state":"待核","notes":["所附页面缺少第三方服务商统计图，解析也缺少比重算式，分子取值无法核验。"],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-share","label":"现期比重等于同一时期的部分量除以总体量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"中国第三方超算服务市场规模约占同年超算服务总体市场规模的","why":"题干指定第三方市场为部分、同年总体市场为分母。","origin":"逐题标记"},{"id":"s-a7ce466b25f8ea1b","label":"计算现期比重","catalog_id":"7a985b326fc58141","type":null,"role":"直接考查","field":"answer","quote":"可判定本题为现期比重问题。","why":"需分别汇总同年的部分量与总体量，再求比值。","origin":"逐题标记"}]},"国考 2023 地市级 行测#118":{"stem":"2018年，中国超算服务4类细分市场中，同比增速最快和最慢的市场当年市场规模同比增速相差约多少个百分\n点？","options":["41","47","53","59"],"answer":"C","analysis":"118. 正确答案：C\n解析：\n根据题干“2018年······同比增速······百分点”，可判定本题为一般增长率问题。定位统计表可得2017、2018年中国超\n算服务4类细分市场的市场规模。根据公式：增长率                         ，可知2018年，中国超算服务4类细分市场的\n\n市场规模同比增速分别为：\n尖端超算：                    ；\n\n通用超算：                     ；\n\n业务超算：                     ；\n\n人工智能超算：                      。\n\n则增速最快的市场为人工智能超算，最慢的市场为尖端超算，所求=58%-5%=53%，即相差约53个百分点。\n故正确答案为C。\n【考点】\n\n综合资料,一般增长率","figs":["64bc3a15d27a04e94940.pdf#23"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-growth","label":"同比增长率等于本期量与上年同期量之差除以上年同期量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"定位统计表可得2017、2018年","why":"以2017年市场规模为基期，才能得到2018年各类市场的同比增速。","origin":"逐题标记"},{"id":"k-43398f26c401b6e0","label":"两个百分率直接相减的差以百分点表示","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"所求=58%-5%=53%，即相差约53个百分点。","why":"题目要求用百分点表示两个增速的差。","origin":"逐题标记"},{"id":"s-rates","label":"比较同比增速","catalog_id":"e749694b526d0e5e","type":null,"role":"直接考查","field":"question","quote":"同比增速最快和最慢的市场","why":"需计算并比较四类市场的同比增速，找出两端再求差。","origin":"逐题标记"}]},"国考 2023 地市级 行测#119":{"stem":"如保持2021年同比增量不变，则到哪一年第三方互联网超算服务商提供的服务市场规模将第一次超过第三方独\n立超算服务商？","options":["2025年","2026年","2027年","2028年"],"answer":"B","analysis":"119. 正确答案：B\n解析：\n根据题干“如保持2021年同比增量不变，则到哪一年······将第一次超过······”，可判定本题为现期追赶问题。定位统计\n图可知2020年、2021年中国第三方独立超算和互联网超算服务商市场规模。根据公式：增长量=现期量-基期量，则\n2021年第三方互联网超算服务商市场规模同比增量=13.8-9.5=4.3亿元，2021年第三方独立超算服务商市场规模同比\n增量=18.3-15.0=3.3亿元。根据公式：现期量=基期量+n×增长量，可列式：13.8+n×4.3＞18.3+n×3.3，解得n＞\n4.5，则n至少为5，即到2026年第三方互联网超算服务商提供的服务市场规模将第一次超过第三方独立超算服务商。\n故正确答案为B。\n【考点】\n综合资料,现期追赶","figs":["64bc3a15d27a04e94940.pdf#23"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-6cec509f7b1cbf36","label":"同比增长量等于本期量减上年同期量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"增长量=现期量-基期量","why":"需由相邻两年规模的差确定两类服务商各自的年度增量。","origin":"逐题标记","originalId":"k-a65839210f7ce8f1"},{"id":"k-10c78f5272e0889f","label":"固定年增量下未来规模等于基准规模加预测年数乘以年增量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"现期量=基期量+n×增长量","why":"以2021年规模为基准推算两类服务商在同一未来年份的规模。","origin":"逐题标记","originalId":"k-6ba1fcd95cf4cf83"},{"id":"s-9fc2e5daf6bbb9d8","label":"按增量或增速推算达标时间","catalog_id":"D08","type":null,"role":"直接考查","field":"answer","quote":"13.8+n×4.3＞18.3+n×3.3","why":"按各自固定增量列严格不等式，取满足条件的最小整数年数。","origin":"逐题标记"}]},"国考 2023 地市级 行测#120":{"stem":"能够从上述资料中推出的是：","options":["2016～2020年，通用超算服务市场累计规模超过160亿元","2016～2017年，业务超算服务市场累计规模比人工智能超算服务高30多亿元","2018～2021年，第三方独立超算服务市场规模同比增量逐年递增","2017～2020年，第三方互联网超算服务市场规模同比增速逐年递减"],"answer":"D","analysis":"120. 正确答案：D\n解析：\nA项：定位统计表可得2016~2020年通用超算服务市场规模分别为23.9亿元、26.9亿元、29.7亿元、32.2亿元、37.8\n亿元。则所求=23.9+26.9+29.7+32.2+37.8                  亿元＜160亿元，错误；\nB项：定位统计表可得2016~2017年业务超算服务市场规模分别为15.6亿元、24.1亿元，人工智能超算服务市场规模\n分别为4.7亿元、7.9亿元。则所求=（15.6+24.1）-（4.7+7.9）=39.7-12.6=27.1亿元＜30亿元，错误；\nC项：定位统计图可得2017~2021年中国第三方独立超算服务市场规模。根据公式：增长量=现期量-基期量，则2018\n年同比增量=8.7-7.1=1.6亿元；2019年同比增量=11.7-8.7=3.0亿元；2020年同比增量=15.0-11.7=3.3亿元；2021年\n同比增量=18.3-15.0=3.3亿元。因2021年同比增量与2020年相等，则非逐年递增，错误；\nD项：定位统计图可得2016~2020年中国第三方互联网超算服务市场规模。根据公式：增长率                             ，\n\n则2017年同比增速                        ；2018年同比增速                 ；2019年同比增速\n\n                   ；2020年同比增速                   。则2017~2020年中国第三方互联网超算\n\n服务市场规模同比增速逐年递减，正确。\n故正确答案为D。\n【考点】\n综合资料,综合分析","figs":["64bc3a15d27a04e94940.pdf#23"],"state":"待核","notes":["所附页面缺少第三方服务商统计图，解析也未保留各年同比增速，所述逐年递减趋势无法独立核验。"],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-growth","label":"同比增长率等于本期量与上年同期量之差除以上年同期量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"2017~2020年中国第三方互联网超算服务市场规模同比增速逐年递减","why":"检验所述趋势需按各年的上年同期规模分别计算同比增速。","origin":"逐题标记"},{"id":"s-rates","label":"比较同比增速","catalog_id":"e749694b526d0e5e","type":null,"role":"直接考查","field":"question","quote":"第三方互联网超算服务市场规模同比增速逐年递减","why":"逐一比较相邻年份的同比增速，核验是否每年都低于上一年。","origin":"逐题标记"}]},"国考 2023 地市级 行测#121":{"stem":"2017-2021年，我国总计进口了约多少亿吨木材？","options":["1.4","1.3","1.2","1.1"],"answer":"D","analysis":"121. 正确答案：D\n解析：\n定位图1可知2017-2021年我国每年木材进口量。故2017-2021年，我国总计进口木材量\n                                                       万吨     亿吨，与D项最接\n近。\n故正确答案为D。\n【考点】\n统计图,简单加减计算","figs":["64bc3a15d27a04e94940.pdf#24","64bc3a15d27a04e94940.pdf#25"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-00f94bb51e3fd43c","label":"1亿吨等于10000万吨","catalog_id":null,"type":"事实与事件","role":"解题依据","field":"question","quote":"约多少亿吨木材","why":"图中以万吨计量，题目要求以亿吨表示累计量。","origin":"逐题标记","originalId":"k-468590eaf403df01"},{"id":"s-9d6535a8dad068a9","label":"从统计图读取各期数值并求和","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"定位图1可知2017-2021年我国每年木材进口量。","why":"需要读取指定年份的柱形数据并合计。","origin":"逐题标记","originalId":"s-bde6a9848f090e89"}]},"国考 2023 地市级 行测#122":{"stem":"2017-2021年，我国木材进口平均单价高于400美元/吨的年份有几个？","options":["4","3","2","1"],"answer":"B","analysis":"122. 正确答案：B\n解析：\n根据题干“2017-2021年······平均单价高于400美元/吨的年份有几个”，可判定本题为现期平均数问题。定位图1可知\n2017-2021年我国每年木材进口量及进口额。根据公式：进口平均单价                  ，则2017-2021年我国木材进口平均\n\n单价分别为：2017年，                  美元/吨；2018年，            美元/吨；2019年，\n\n              美元/吨；2020年，              美元/吨；2021年，             美元/吨。因此，平均\n单价高于400美元/吨的年份有2017年、2018年、2021年，共3个。\n故正确答案为B。\n【考点】\n统计图,现期平均数","figs":["64bc3a15d27a04e94940.pdf#24","64bc3a15d27a04e94940.pdf#25"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-5db4b46712552e56","label":"平均单价等于总金额除以总数量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"每年木材进口量及进口额","why":"每年的平均单价由同年进口额和进口量之比换算得到。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"question","quote":"木材进口平均单价高于400美元/吨的年份有几个","why":"需要按年判断平均单价是否超过给定阈值，再统计符合条件的年份。","origin":"逐题标记"}]},"国考 2023 地市级 行测#123":{"stem":"2021年，松木、冷杉和针叶木材进口量之和占当年我国木材进口总量的：","options":["不到60%","60%~65%之间","65%~70%之间","70%以上"],"answer":"B","analysis":"123. 正确答案：B\n解析：\n\n根据题干“2021年······占当年······的”，结合材料给出2021年相关数据，可判定本题为现期比重问题。定位图1可得：\n2021年，我国木材进口量为1892万吨。定位图2可得：2021年，我国松木、冷杉、针叶木材进口量分别为575万吨、\n432万吨、209万吨。根据公式：比重            ，则松木、冷杉和针叶木材进口量之和占当年我国木材进口总量的比重\n\n                            ，在B项范围内。\n\n故正确答案为B。\n【考点】\n统计图,现期比重","figs":["64bc3a15d27a04e94940.pdf#24","64bc3a15d27a04e94940.pdf#25"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-share","label":"现期比重等于现期部分量除以现期总体量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"进口量之和占当年我国木材进口总量","why":"三类木材进口量之和是部分量，同年木材进口总量是总体量。","origin":"逐题标记"},{"id":"s-a7ce466b25f8ea1b","label":"计算现期比重","catalog_id":"7a985b326fc58141","type":null,"role":"直接考查","field":"question","quote":"松木、冷杉和针叶木材进口量之和占当年我国木材进口总量","why":"需要从两张图中提取同年数据，合计部分量并判断比重落在哪个区间。","origin":"逐题标记"}]},"国考 2023 地市级 行测#124":{"stem":"2021年，自俄罗斯进口的木材占当年木材进口总量的比重约比美国高多少个百分点？","options":["44","50","32","38"],"answer":"A","analysis":"124. 正确答案：A\n解析：\n根据题干“2021年······的比重约比······高多少个百分点”，可判定本题为现期比重问题。定位图1可得：2021年我国木\n材进口量为1892万吨；定位图3可得：2021年我国自俄罗斯和美国进口木材量分别为929万吨和90万吨。根据公式：\n比重      ，故所求为                            。\n\n故正确答案为A。\n【考点】\n统计图,现期比重","figs":["64bc3a15d27a04e94940.pdf#24","64bc3a15d27a04e94940.pdf#25"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-b4be6d3b12f772a4","label":"同一总体下的比重差等于部分量之差除以总体量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"占当年木材进口总量的比重约比美国高多少个百分点","why":"两国进口量采用同一个总体作分母，比重之差用百分点表示。","origin":"逐题标记"},{"id":"s-22e0d443f4e8833e","label":"比较比重与百分点差","catalog_id":"D06","type":null,"role":"直接考查","field":"question","quote":"比重约比美国高多少个百分点","why":"需要从图中读取两国进口量和当年总量，估算两国占比的差值。","origin":"逐题标记"}]},"国考 2023 地市级 行测#125":{"stem":"以下折线图中，最能准确反映2018-2021年我国木材进口额同比增量变化趋势的是：","options":["","","",""],"answer":"C","analysis":"125. 正确答案：C\n解析：\n根据题干“······2018-2021年······同比增量变化趋势”，可判定本题为增长量比较问题。定位图1可得，2017-2021年，\n我国木材进口额分别为96.9亿美元、97.8亿美元、83.1亿美元、74.4亿美元、78.6亿美元。根据公式：增长量=现期\n量-基期量，则2018-2021年我国木材进口额同比增量分别为：\n2018年，97.8-96.9=0.9亿美元；\n2019年，83.1-97.8=-14.7亿美元；\n2020年，74.4-83.1=-8.7亿美元；\n2021年，78.6-74.4=4.2亿美元。\n综上可知，同比增量呈先下降后上升的趋势，且2019年同比增量最低，2021年同比增量最高，与C项变化趋势一\n致。\n故正确答案为C。\n【考点】\n统计图,增长量比较","figs":["64bc3a15d27a04e94940.pdf#26","64bc3a15d27a04e94940.pdf#27","64bc3a15d27a04e94940.pdf#24","64bc3a15d27a04e94940.pdf#25"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-84fb513a5d91a257","label":"同比增长量等于现期量减上年同期量","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"question","quote":"我国木材进口额同比增量变化趋势","why":"需以各年的上年同期为基期，保留差值的正负号。","origin":"逐题标记"},{"id":"s-f29bc501c32a5bee","label":"计算与比较增长量","catalog_id":"D02","type":null,"role":"直接考查","field":"question","quote":"最能准确反映2018-2021年我国木材进口额同比增量变化趋势","why":"需要逐年求差，并用增量的升降顺序和相对高低匹配折线图。","origin":"逐题标记"}]},"国考 2023 地市级 行测#126":{"stem":"2021年，全国商品、服务类电子商务交易额同比增长了：","options":["17.2%","19.5%","21.8%","24.1%"],"answer":"B","analysis":"126. 正确答案：B\n解析：\n根据题干“2021年······同比增长了”，结合选项为百分数，可判定本题为一般增长率问题。定位文字材料第一段可得：\n2021年H省商品、服务类电子商务交易额为11526.13亿元，比上年同期增长21.8%，高于全国增速2.3个百分点。则\n2021年，全国商品、服务类电子商务交易额同比增长了21.8%-2.3%=19.5%。\n故正确答案为B。\n【考点】\n文字资料,一般增长率","figs":["64bc3a15d27a04e94940.pdf#27"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-c5c1d4d13089938f","label":"百分点表示两个百分率的算术差","catalog_id":null,"type":"概念与词义","role":"解题依据","field":"answer","quote":"高于全国增速2.3个百分点","why":"材料用百分点表示H省同比增速与全国同比增速的差。","origin":"逐题标记"},{"id":"s-a227494d12288056","label":"根据百分点差反推增长率","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"21.8%-2.3%=19.5%","why":"根据已知增速领先的方向和幅度，选择减法反推另一增速。","origin":"逐题标记","originalId":"s-10edffb17143f9af"}]},"国考 2023 地市级 行测#127":{"stem":"2021年，H省实物商品网上零售额占网上零售额的比重比上年同期：","options":["下降了不到3个百分点","下降了3个百分点以上","上升了不到3个百分点","上升了3个百分点以上"],"answer":"A","analysis":"127. 正确答案：A\n解析：\n根据题干“2021年······占······比重比上年同期”，结合选项为“下降/上升+百分点”，可判定本题为两期比重问题。定位\n文字材料第一段可得：2021年，H省网上零售额为2948.2亿元（B），同比增长12.5%（b），其中，实物商品网上\n零售额为2426.4亿元（A），同比增长10.1%（a）。根据公式：两期比重              ，可得所求\n\n                                       ，即比重比上年同期下降了不到3个百分点。\n\n故正确答案为A。\n【考点】\n文字资料,两期比重","figs":["64bc3a15d27a04e94940.pdf#27"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-58db2e624f2d2295","label":"两期比重差公式","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"根据公式：两期比重","why":"现期比重减基期比重等于现期比重乘以部分与整体的增速差，再除以一加部分增速。","origin":"逐题标记"},{"id":"s-22e0d443f4e8833e","label":"比较比重与百分点差","catalog_id":"D06","type":null,"role":"直接考查","field":"question","quote":"比重比上年同期","why":"利用部分和整体的同比增速判断比重变化方向，并将变化幅度与给定阈值比较。","origin":"逐题标记"}]},"国考 2023 地市级 行测#128":{"stem":"以下饼图中，最能准确反映2021年H省商品类（白色）和服务类（黑色）电子商务交易额占商品、服务类电子\n商务交易额比重关系的是：","options":["","","",""],"answer":"B","analysis":"128. 正确答案：B\n解析：\n\n根据题干“以下饼图中，最能准确反映2021年H省······占······比重关系的是”，可判定本题为现期比重问题。定位文字\n材料第一、二段可得：2021年H省商品、服务类电子商务交易额为11526.13亿元······商品类电子商务交易额为\n8896.60亿元，服务类电子商务交易额为2629.53亿元。服务类电子商务交易额占比为                 ，\n\n占比略小于25%，即在饼图中黑色部分应略小于圆的     ，排除A、C、D三项，B项当选。\n\n故正确答案为B。\n【考点】\n文字资料,现期比重","figs":["64bc3a15d27a04e94940.pdf#27","64bc3a15d27a04e94940.pdf#28"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-1a8bbbacdb884f13","label":"饼图扇形占整圆的比例等于类别占总体的比重","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"占比略小于25%，即在饼图中黑色部分应略小于圆的","why":"饼图用黑色扇形占整圆的比例表示服务类交易额占总额的比重。","origin":"逐题标记"},{"id":"s-a7ce466b25f8ea1b","label":"计算现期比重","catalog_id":"7a985b326fc58141","type":null,"role":"直接考查","field":"answer","quote":"服务类电子商务交易额占比为","why":"用当年服务类交易额除以两类交易额合计，估算黑色扇形对应的份额。","origin":"逐题标记"}]},"国考 2023 地市级 行测#129":{"stem":"2021年，H省除Z市外其他地区的电子商务平台平均每个平台实现的交易金额约为多少亿元？","options":["5","12","26","62"],"answer":"C","analysis":"129. 正确答案：C\n解析：\n根据题干“2021年······平均每个······交易金额约为多少亿元”，可判定本题为现期平均数问题。定位文字材料第三段可\n得，2021年H省共有电子商务平台87个，在本省电商平台上实现交易金额为5354.93亿元······2021年本地电子商务平\n台拥有量最多的为Z市，有44个平台，实现交易金额4239.04亿元。故2021年H省除Z市外其他地区的电子商务平台平\n均每个平台实现的交易金额                        亿元。\n\n故正确答案为C。\n【考点】\n文字资料,现期平均数","figs":["64bc3a15d27a04e94940.pdf#27"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-b703c7033d160a56","label":"子集的算术平均数等于子集总量除以子集数量","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"question","quote":"H省除Z市外其他地区的电子商务平台平均每个平台实现的交易金额","why":"平均交易金额的分子和分母都取自剔除Z市后的同一平台集合。","origin":"逐题标记"},{"id":"s-e9ffdd08e7f0ec51","label":"计算平均数、倍数及其变化","catalog_id":"D07","type":null,"role":"直接考查","field":"question","quote":"除Z市外其他地区的电子商务平台平均每个平台实现的交易金额","why":"分别求交易额差和平台数差，再用两差相除求指定范围内的平均数。","origin":"逐题标记"}]},"国考 2023 地市级 行测#130":{"stem":"关于H省电子商务交易，能够从上述资料中推出的是：","options":["2021年，跨境电商进出口交易额同比增长16%以上","2021年，网上零售额占商品、服务类电子商务交易额的比重高于上年水平","2020年，对个人电子商务交易额占商品、服务类电子商务交易额的38%以上","2020年，省内电子商务平台收取的平台交易服务费超过2亿元"],"answer":"D","analysis":"130. 正确答案：D\n解析：\nA项：定位材料第一段可得：（2021年）H省跨境电商进出口交易额为2018.3亿元，其中，出口1475.5亿元，同比增\n长15.7%；进口542.8亿元，同比增长16.0%。进出口交易额=出口额+进口额，根据混合增长率口诀“混合后居中”可\n知，2021年跨境电商进出口交易额的同比增速在15.7%~16.0%之间，错误；\nB项：定位材料第一段可得：2021年H省商品、服务类电子商务交易额为11526.13亿元，比上年同期增长21.8%\n（b）······H省网上零售额为2948.2亿元，同比增长12.5%（a）。根据两期比重比较结论：当部分增长率（a）＜整\n体增长率（b）时，比重下降。12.5%＜21.8%，即2021年网上零售额占商品、服务类电子商务交易额的比重低于上\n年水平，错误；\nC项：定位材料第一段可得：2021年H省商品、服务类电子商务交易额为11526.13亿元（B），比上年同期增长\n21.8%（b）；定位材料第二段可得：（2021年H省）对个人电子商务交易额为4271.38亿元（A），同比增长25.4%\n（a）。根据公式：基期比重          ，则2020年占比为                   ，2020年对个人电\n\n子商务交易额占商品、服务类电子商务交易额的比重不足38%，错误；\nD项：定位材料第三段可得：（2021年H省）在本省电商平台上······收取的平台交易服务费为3.17亿元，同比增长\n49.5%。根据公式：基期量       ，则2020年省内电子商务平台收取的平台交易服务费为            亿元，\n正确。\n故正确答案为D。\n【考点】\n文字资料,综合分析","figs":["64bc3a15d27a04e94940.pdf#27"],"state":"已标记","notes":[],"domains":["统计"],"nature":"综合题","current":false,"links":[{"id":"k-c1e02ee36e8303c5","label":"基期量等于现期量除以一加增长率","catalog_id":null,"type":"原理与机制","role":"解题依据","field":"answer","quote":"根据公式：基期量","why":"核验平台交易服务费的上年金额时，需要按同比增长率将现期金额折回基期。","origin":"逐题标记"},{"id":"s-base","label":"反推基期量","catalog_id":"D01","type":null,"role":"直接考查","field":"question","quote":"2020年，省内电子商务平台收取的平台交易服务费超过2亿元","why":"根据当年服务费和同比增速反推上年金额，并与给定阈值比较。","origin":"逐题标记"}]}},"mats":{"c05ee6cfb96bdbd9":["题组1","（一）\n\n6天休假期间，单位需要每天安排一人值班。财务、研发、人事、后勤、法务和销售6个部门各推荐了2人，值班人员\n从这12人中选择，每人至多值班一天。安排要求：\n（1）第二天和第四天不安排法务部门的人值班；\n（2）若安排后勤部门的人值班，则只能安排在法务部门的人值班的前一天；\n（3）若安排研发部门的人值班，则只能安排在后勤部门的人值班的前一天。",["64bc3a15d27a04e94940.pdf",21]],"a219ab711a3b0b8a":["题组2","（一）",["64bc3a15d27a04e94940.pdf",21]],"2349b04531975b25":["题组3","（二）\n\n   超级计算，也被称为高性能计算。从算力资源的需求看，高性能计算可以分为尖端超算、通用超算、业务超算\n和人工智能超算四大类。",["64bc3a15d27a04e94940.pdf",23]],"ff984a3afed358c6":["题组4","（三）\n\n〔原页图像：资料分析图表，中国木材进口数量及进口额、主要进口来源地〕",["64bc3a15d27a04e94940.pdf",24]],"ce4df1cd8524ca58":["题组5","（四）\n\n     2021年H省商品、服务类电子商务交易额为11526.13亿元，比上年同期增长21.8%，高于全国增速2.3个百分\n点。H省跨境电商进出口交易额为2018.3亿元，其中，出口1475.5亿元，同比增长15.7%；进口542.8亿元，同比增\n长16.0%。H省网上零售额为2948.2亿元，同比增长12.5%，其中，实物商品网上零售额为2426.4亿元，同比增长\n10.1%。\n     从交易对象看，2021年H省商品类电子商务交易额为8896.60亿元，同比增长16.6%；服务类电子商务交易额为\n2629.53亿元，同比增长43.5%。从交易主体看，2021年H省对单位电子商务交易额为7254.75亿元，同比增长\n19.8%，占商品、服务类电子商务交易额比重为62.9%；对个人电子商务交易额为4271.38亿元，同比增长25.4%。\n     2021年H省共有电子商务平台87个，在本省电商平台上实现交易金额为5354.93亿元，同比增长41.0%，收取的\n平台交易服务费为3.17亿元，同比增长49.5%。从地区分布来看，2021年本地电子商务平台拥有量最多的为Z市，有\n44个平台，实现交易金额4239.04亿元。",["64bc3a15d27a04e94940.pdf",27]]}};
